('617d183d-8898-4592-9695-72582b0109bb', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'In a survey, 0.35 of Year 7 students said maths is their favourite subject. Write 0.35 as a fraction in simplest form.', '["7/20","3/5","35/100","7/10"]'::jsonb, 0, '0.35 = 35/100. Simplify by dividing by 5: 7/20.', 'AC9M7N03', null, null, true, null, null, null, null),
('61a7eacb-c722-480d-92b1-edd7865d8250', 'algebra_equations', 'year_7', 'foundation', 'multiple_choice', 'A fair charges $4 entry plus $2 per raffle ticket. Kyle spent $16 in total at the fair. Write an equation for the number of tickets, t, he bought, then solve it.', '["t = 6","t = 5","t = 8","t = 10"]'::jsonb, 0, 'Let t = number of tickets. 4 + 2t = 16, so 2t = 12, t = 6.', 'AC9M7A02', null, null, true, null, null, null, null),
('2d67f5a7-047c-4453-98f5-13a4a897d540', 'algebra_equations', 'year_7', 'developing', 'multiple_choice', 'A stadium''s seating chart adds seats in each new row: row 1 has 3 seats, row 2 has 7, row 3 has 11, row 4 has 15. If the pattern of adding 4 extra seats per row continues, how many seats are in row 5?', '["17","19","18","20"]'::jsonb, 1, 'The common difference is +4. 15 + 4 = 19 seats.', 'AC9M7A01', null, null, true, null, null, null, null),
('f21ff070-d3d8-4e69-b9d1-cc965b53e1ff', 'algebra_equations', 'year_9', 'proficient', 'multiple_choice', 'Factorise the expression x² − 9.', '["(x+3)(x+3)","(x−9)(x+1)","(x−3)(x+3)","(x+9)(x−1)"]'::jsonb, 2, 'Difference of two squares: a² − b² = (a−b)(a+b). So x² − 9 = (x−3)(x+3).', 'AC9M9A01', null, null, true, null, null, null, null),
('98490cd9-b9c1-4b78-a692-4636eea71cbc', 'algebra_equations', 'year_10', 'proficient', 'multiple_choice', 'A stone is dropped from a bridge. Its height above the water, in metres, after t seconds is h(t) = 45 − 5t². Its height after 2 seconds is', '["35 m","5 m","25 m","45 m"]'::jsonb, 2, 'Substituting t = 2 gives h(2) = 45 − 5 × 4 = 45 − 20 = 25 metres. Option B squares only after subtracting.', 'AC9M10A01', null, false, true, null, null, null, null),
('df773e2f-c2be-4735-bdef-ae4030e187a0', 'statistics_probability', 'year_7', 'foundation', 'multiple_choice', 'A fair six-sided die, numbered 1 to 6, is rolled once. What is the probability of rolling a 6?', '["1/3","1/4","1/6","1/2"]'::jsonb, 2, 'There are 6 equally likely outcomes (1–6), and only one of them is a 6: P(6) = 1/6.', 'AC9M7P01', null, null, true, null, null, null, null),
('4c9c48fc-ba92-47c2-b8e7-d85eee10b828', 'reading_comprehension', 'grade_3', 'foundation', 'multiple_choice', 'Read: "Tom packed his bag and ran to catch the bus. He was late for school." Why did Tom run?', '["He wanted exercise","He lost his bag","He was late for school","He missed the bus"]'::jsonb, 2, 'The passage says Tom ''was late for school,'' which is why he ran to catch the bus.', 'AC9E3LY06', null, null, true, null, null, null, null),
('88176768-82e6-40f6-a4b6-e2a8449adfe7', 'reading_comprehension', 'grade_5', 'developing', 'multiple_choice', 'Read: "Although it was raining, Maya decided to go for a walk because she loved the smell of wet earth." What is Maya''s motivation for going outside?', '["She had to walk the dog","She loved the smell of rain","She was late","She wanted to get wet"]'::jsonb, 1, 'The word ''because'' signals her reason: she loved the smell of wet earth.', 'AC9E5LY07', null, null, true, null, null, null, null),
('f32db62e-cfd9-4ce9-a39e-0bf06cb95bc2', 'reading_comprehension', 'grade_6', 'developing', 'multiple_choice', 'In a story, a character who changes and grows over time is called a:', '["Static character","Dynamic character","Narrator","Antagonist"]'::jsonb, 1, 'A dynamic character undergoes meaningful internal change during the story.', 'AC9E6LE07', null, null, true, null, null, null, null),
('57e7176d-1784-41e5-b934-b008fe956f1a', 'reading_literary_analysis', 'year_7', 'proficient', 'multiple_choice', 'Read: "The old bridge groaned under the weight of the truck, its timbers creaking like tired bones." This sentence mainly uses which literary device?', '["Simile","Metaphor","Onomatopoeia","Hyperbole"]'::jsonb, 0, '''Creaking like tired bones'' compares the bridge''s sound to bones using ''like'', which makes it a simile.', 'AC9E7LE05', null, null, true, null, null, null, null),
('f8f0d371-501c-4e1e-8a34-ba7636d6558d', 'reading_literary_analysis', 'year_9', 'advanced', 'multiple_choice', 'An author who writes with a critical or mocking tone about the flaws of society is using:', '["Satire","Elegy","Parody","Soliloquy"]'::jsonb, 0, 'Satire uses irony, humour, and exaggeration to criticise society''s flaws.', 'AC9E9LE04', null, null, true, null, null, null, null),
('13289b3d-55d7-4388-8289-12e944e75a28', 'grammar_punctuation', 'grade_3', 'foundation', 'multiple_choice', 'Which sentence uses the correct punctuation?', '["Where is my hat","Where is my hat.","Where is my hat?","Where is my hat??"]'::jsonb, 2, 'Questions must end with a question mark and start with a capital letter.', 'AC9E3LA05', null, null, true, null, null, null, null),
('b4e8d10c-3038-4248-acbf-99c71fe7dd11', 'grammar_punctuation', 'grade_4', 'developing', 'multiple_choice', 'Choose the correctly punctuated sentence.', '["Its a sunny day.","It''s a sunny day.","Its'' a sunny day.","Its a sunny day"]'::jsonb, 1, '''It''s'' is the contraction of ''it is''. ''Its'' (no apostrophe) shows possession.', 'AC9E4LA06', null, null, true, null, null, null, null),
('50d57618-b6ac-4a40-9414-11fc145bebcb', 'grammar_punctuation', 'grade_6', 'proficient', 'multiple_choice', 'Identify the sentence with correct subject-verb agreement.', '["The team are winning.","The team am winning.","The team is winning.","The team be winning."]'::jsonb, 2, '''Team'' is a collective noun treated as singular in Australian English, so it takes ''is''.', 'AC9E6LA07', null, null, true, null, null, null, null),
('44031c53-3fe9-401e-be48-ed1ff2ccc2bc', 'grammar_punctuation', 'year_7', 'developing', 'multiple_choice', 'Which word correctly completes: ''Neither the students nor the teacher ___ ready.''', '["were","is","was","are"]'::jsonb, 2, 'With ''neither/nor'', the verb agrees with the nearer subject, ''teacher'' (singular), so ''was''.', 'AC9E7LA05', null, null, true, null, null, null, null),
('06ae62bf-37df-4c5e-a56e-ed9c1cf7512c', 'grammar_punctuation', 'year_8', 'proficient', 'multiple_choice', 'Which sentence correctly uses a semicolon?', '["I like tea, however I prefer coffee.","I like tea; and coffee.","I like tea; however, I prefer coffee.","I like tea however; I prefer coffee."]'::jsonb, 2, 'A semicolon can join two related independent clauses, often before a conjunctive adverb like ''however''.', 'AC9E8LA06', null, null, true, null, null, null, null),
('d0787f9d-fc16-4824-bd33-9b5a9ce48d10', 'vocabulary', 'grade_3', 'foundation', 'multiple_choice', 'Which word means the same as ''happy''?', '["Sad","Angry","Glad","Tired"]'::jsonb, 2, '''Glad'' is a synonym for ''happy''; both describe feeling pleased.', 'AC9E3LA09', null, null, true, null, null, null, null),
('38223913-5840-4bd4-8f9d-1bbea56a700f', 'vocabulary', 'grade_5', 'developing', 'multiple_choice', 'What is the antonym (opposite) of ''generous''?', '["Kind","Wealthy","Selfish","Helpful"]'::jsonb, 2, '''Selfish'' means the opposite of ''generous'', which means willing to give.', 'AC9E5LA10', null, null, true, null, null, null, null),
('ef89ac55-5590-45b9-8ca7-8a935961c8a9', 'vocabulary', 'grade_6', 'developing', 'multiple_choice', 'The prefix ''un-'' in the word ''unhappy'' means:', '["Very","Again","Not","Before"]'::jsonb, 2, 'The prefix ''un-'' means ''not'', so ''unhappy'' means ''not happy''.', 'AC9E6LA09', null, null, true, null, null, null, null),
('96962a07-d84a-4489-b4b4-4324f88b2b26', 'vocabulary', 'year_7', 'proficient', 'multiple_choice', 'Which word best fits: ''The detective''s ___ observation solved the case.''', '["meticulous","careless","hasty","vague"]'::jsonb, 0, '''Meticulous'' means very careful and precise, fitting a detective solving a case.', 'AC9E7LA10', null, null, true, null, null, null, null),
('bf750551-cf5e-491e-9e3c-eac4f1057ee0', 'vocabulary', 'year_9', 'advanced', 'multiple_choice', '''Ubiquitous'' most nearly means:', '["Rare","Present everywhere","Ancient","Loud"]'::jsonb, 1, '''Ubiquitous'' describes something found everywhere or very common.', 'AC9E9LA08', null, null, true, null, null, null, null),
('5ca913e1-318e-47f6-b043-4719b7bb1540', 'life_science', 'grade_3', 'foundation', 'multiple_choice', 'Which of these is a living thing?', '["Rock","Tree","Chair","Cloud"]'::jsonb, 1, 'Living things grow, reproduce, and need energy, so a tree is alive, while rocks, chairs and clouds are not.', 'AC9S3U01', null, null, true, null, null, null, null),
('9bf731e1-fa29-4479-92ed-ba7882e1b692', 'life_science', 'grade_5', 'developing', 'multiple_choice', 'What is the main function of a plant''s roots?', '["Make food using sunlight","Absorb water and nutrients","Produce seeds","Release oxygen"]'::jsonb, 1, 'Roots anchor the plant and absorb water and nutrients from the soil.', 'AC9S5U01', null, null, true, null, null, null, null),
('12310b4f-6289-41b5-8379-2d52e086a163', 'life_science', 'grade_6', 'developing', 'multiple_choice', 'Which organ pumps blood around the human body?', '["Lungs","Liver","Heart","Stomach"]'::jsonb, 2, 'The heart is a muscular organ that pumps blood through the circulatory system.', 'AC9S6U02', null, null, true, null, null, null, null),
('a7543b7a-a68d-4973-bed4-370427f0228d', 'life_science', 'year_7', 'proficient', 'multiple_choice', 'In a food chain, what is the primary role of a producer?', '["Eats other animals","Decomposes dead matter","Makes its own food using sunlight","Hunts prey"]'::jsonb, 2, 'Producers, like plants, make their own food through photosynthesis.', 'AC9S7U03', null, null, true, null, null, null, null),
('75a77b8c-543b-4772-a94b-1f700d4c4f3f', 'life_science', 'year_9', 'advanced', 'multiple_choice', 'Which process allows cells to divide and produce two genetically identical daughter cells?', '["Meiosis","Mitosis","Fertilisation","Osmosis"]'::jsonb, 1, 'Mitosis produces two genetically identical daughter cells for growth and repair.', 'AC9S9U03', null, null, true, null, null, null, null),
('2f9423e0-9e64-47f0-ba90-f0e31d32a1ff', 'physical_science', 'grade_4', 'foundation', 'multiple_choice', 'What happens to water when it is heated to boiling point?', '["It freezes","It turns into rock","It turns into gas","It disappears forever"]'::jsonb, 2, 'At boiling point, water changes from a liquid to a gas (water vapour).', 'AC9S4U01', null, null, true, null, null, null, null),
('d7c1d9c5-c9de-4188-851b-fb10521c436b', 'physical_science', 'grade_6', 'developing', 'multiple_choice', 'Which of these is a force that slows down moving objects?', '["Gravity","Magnetism","Friction","Light"]'::jsonb, 2, 'Friction acts opposite to motion between surfaces, slowing objects down.', 'AC9S6U01', null, null, true, null, null, null, null),
('b4135d64-f9bb-403b-8899-464791404fae', 'physical_science', 'year_7', 'developing', 'multiple_choice', 'What is the unit used to measure electric current?', '["Volt","Watt","Ampere","Ohm"]'::jsonb, 2, 'Electric current is measured in amperes (amps), symbol A.', 'AC9S7U01', null, null, true, null, null, null, null),
('08c4487d-e0de-45dd-a475-9b23f8d3b6ee', 'physical_science', 'year_8', 'proficient', 'multiple_choice', 'Which state of matter has a fixed volume but no fixed shape?', '["Solid","Liquid","Gas","Plasma"]'::jsonb, 1, 'A liquid takes the shape of its container but keeps a fixed volume.', 'AC9S8U01', null, null, true, null, null, null, null),
('fa75ee6b-7411-4dc0-8f24-9db75d523b3e', 'physical_science', 'year_10', 'advanced', 'multiple_choice', 'According to Newton''s second law, force equals:', '["mass ÷ acceleration","mass + acceleration","mass × acceleration","acceleration ÷ mass"]'::jsonb, 2, 'Newton''s second law states F = m × a (force equals mass times acceleration).', 'AC9S10U03', null, null, true, null, null, null, null),
('5955cdef-1a18-49bc-867e-83772e0bb443', 'earth_space', 'grade_3', 'foundation', 'multiple_choice', 'What causes day and night on Earth?', '["The Moon orbiting Earth","Earth spinning on its axis","The Sun moving around Earth","Clouds covering the Sun"]'::jsonb, 1, 'Earth rotates on its axis once every 24 hours, causing day and night.', 'AC9S3U02', null, null, true, null, null, null, null),
('c6fb52e0-4bff-4659-bb3d-5374d17ab882', 'earth_space', 'grade_5', 'developing', 'multiple_choice', 'Which layer of the Earth is the hottest?', '["Crust","Mantle","Outer core","Inner core"]'::jsonb, 3, 'The inner core is the hottest layer, reaching temperatures similar to the Sun''s surface.', 'AC9S5U02', null, null, true, null, null, null, null),
('6eec1bb8-817f-4d8a-9cfe-f1fea7cc875b', 'earth_space', 'grade_6', 'developing', 'multiple_choice', 'What is the main cause of the seasons on Earth?', '["Distance from the Sun changing a lot","The Moon''s gravity","The tilt of Earth''s axis","Ocean currents"]'::jsonb, 2, 'Earth''s axial tilt means different hemispheres receive more or less direct sunlight through the year, causing seasons.', 'AC9S6U03', null, null, true, null, null, null, null),
('5327c5a5-d566-472a-9c20-46d7b7130175', 'earth_space', 'year_8', 'proficient', 'multiple_choice', 'Which type of rock forms from cooled magma or lava?', '["Sedimentary","Metamorphic","Igneous","Fossil"]'::jsonb, 2, 'Igneous rock forms when magma or lava cools and solidifies.', 'AC9S8U02', null, null, true, null, null, null, null),
('2a50a3c3-40ff-4e56-947a-394adc7cab21', 'earth_space', 'year_9', 'advanced', 'multiple_choice', 'What is the primary evidence used to support the theory of plate tectonics?', '["Fossil records only","Matching coastlines, fossils, and rock strata across continents","Ocean temperature","Moon phases"]'::jsonb, 1, 'Matching coastlines, fossil distributions, and rock strata across continents provide strong evidence for plate tectonics.', 'AC9S9U04', null, null, true, null, null, null, null),
('3b42d2be-fbd4-4d3b-8827-22a090d39f3e', 'chem_atomic_structure', 'year_11', 'foundation', 'multiple_choice', 'How many electrons can the first electron shell (n = 1) hold at maximum?', '["2","8","18","6"]'::jsonb, 0, 'The first shell (n = 1) holds a maximum of 2 electrons.', null, null, null, true, null, null, null, null),
('065e91db-0de0-4986-9df8-b9511054b68a', 'chem_atomic_structure', 'year_11', 'foundation', 'multiple_choice', 'What does the atomic number of an element tell you?', '["The number of neutrons","The number of protons plus neutrons","The number of protons","The number of outer-shell electrons"]'::jsonb, 2, 'The atomic number is the number of protons in the nucleus, which also equals the number of electrons in a neutral atom.', null, null, null, true, null, null, null, null),
('0ddf4f17-0812-4cdd-aa13-f4aaad38b896', 'chem_reactions', 'year_11', 'developing', 'multiple_choice', 'In the reaction Mg + 2HCl → MgCl₂ + H₂, what type of reaction is this?', '["Combustion","Neutralisation","Displacement","Decomposition"]'::jsonb, 2, 'Magnesium displaces hydrogen from hydrochloric acid, making this a displacement reaction.', null, null, null, true, null, null, null, null),
('557bbb2b-67b7-4b2b-9f4b-47b80434436d', 'chem_reactions', 'year_11', 'developing', 'multiple_choice', 'What are the correct coefficients to balance: __H₂ + __O₂ → __H₂O?', '["1, 1, 1","2, 1, 2","2, 2, 2","1, 2, 1"]'::jsonb, 1, '2H₂ + O₂ → 2H₂O balances both hydrogen (4 atoms) and oxygen (2 atoms) on each side.', null, null, null, true, null, null, null, null),
('0a07ed7f-3495-412f-843c-c967b7394a2b', 'phys_mechanics', 'year_11', 'developing', 'multiple_choice', 'A car accelerates from rest at 2 m/s² for 5 seconds. What is its final velocity?', '["5 m/s","10 m/s","15 m/s","20 m/s"]'::jsonb, 1, 'v = u + at = 0 + (2 × 5) = 10 m/s.', null, null, null, true, null, null, null, null),
('6c48df1d-33ae-4d32-91b5-6e353d6e176d', 'phys_mechanics', 'year_11', 'foundation', 'multiple_choice', 'Which formula gives the kinetic energy of a moving object?', '["mgh","½mv²","mv","ma"]'::jsonb, 1, 'Kinetic energy is calculated as ½mv², where m is mass and v is velocity.', null, null, null, true, null, null, null, null),
('f7de488d-5e3b-4931-b68a-5db63687a461', 'phys_electricity', 'year_11', 'developing', 'multiple_choice', 'Using Ohm''s law, what is the current through a 10 Ω resistor with 20 V across it?', '["0.5 A","10 A","2 A","200 A"]'::jsonb, 2, 'I = V / R = 20 / 10 = 2 A.', null, null, null, true, null, null, null, null),
('044beb53-783a-4caf-a5b7-26d10f2e1650', 'phys_electricity', 'year_11', 'foundation', 'multiple_choice', 'Which particle carries negative charge and flows to create a typical electric current in a wire?', '["Electron","Proton","Neutron","Positron"]'::jsonb, 0, 'Electrons carry negative charge and are the particles that flow through a conductor.', null, null, null, true, null, null, null, null),
('c2a82f32-e1b5-4a7e-82e3-5843a6d0f39a', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'Differentiate f(x) = 3x² + 2x.', '["f''(x) = 3x + 2","f''(x) = 6x","f''(x) = 6x + 2","f''(x) = 6x² + 2"]'::jsonb, 2, 'Using the power rule: d/dx(3x²) = 6x and d/dx(2x) = 2, giving 6x + 2.', null, null, null, true, null, null, null, null),
('2bd3853a-b67a-4cc7-baf4-227f343c1874', 'mm_calculus', 'year_11', 'foundation', 'multiple_choice', 'What is the derivative of a constant, such as f(x) = 7?', '["0","7","1","x"]'::jsonb, 0, 'The derivative of any constant is 0, since a constant does not change as x changes.', null, null, null, true, null, null, null, null),
('8205de0f-8534-4eb8-8199-371a67bc7156', 'mm_probability', 'year_11', 'developing', 'multiple_choice', 'A fair coin is tossed twice. What is the probability of getting exactly one head?', '["1/4","1/2","3/4","1"]'::jsonb, 1, 'Of the four equally likely outcomes (HH, HT, TH, TT), two have exactly one head, giving 2/4 = 1/2.', null, null, null, true, null, null, null, null),
('26ca60d4-2c6d-4f9e-b97c-c0f37655220c', 'mm_probability', 'year_11', 'developing', 'multiple_choice', 'If P(A) = 0.3 and P(B) = 0.4 and A and B are independent, what is P(A and B)?', '["0.7","0.12","0.1","0.34"]'::jsonb, 1, 'For independent events, P(A and B) = P(A) × P(B) = 0.3 × 0.4 = 0.12.', null, null, null, true, null, null, null, null),
('91dd8c91-8f1f-491f-96b8-e2610b41fe99', 'gm_data_analysis', 'year_11', 'foundation', 'multiple_choice', 'What does the median of a data set represent?', '["The most frequent value","The average of all values","The middle value when the data is ordered","The range of the values"]'::jsonb, 2, 'The median is the middle value once the data set is arranged in order.', null, null, null, true, null, null, null, null),
('91c45557-dbe3-465b-9fd5-3be3080e9dc9', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'A data set has Q1 = 10 and Q3 = 18. What is the interquartile range (IQR)?', '["8","18","28","10"]'::jsonb, 0, 'IQR = Q3 − Q1 = 18 − 10 = 8.', null, null, null, true, null, null, null, null),
('23d8c575-deee-4f27-b355-ce6a665086d3', 'gm_financial', 'year_11', 'developing', 'multiple_choice', '$1000 is invested at 5% simple interest per year. How much interest is earned after 3 years?', '["$50","$150","$1050","$1150"]'::jsonb, 1, 'Simple interest = P × r × t = 1000 × 0.05 × 3 = $150.', null, null, null, true, null, null, null, null),
('181fa7ab-86e6-4dde-b712-b5d3351df455', 'gm_financial', 'year_11', 'foundation', 'multiple_choice', 'What does "principal" mean in the context of a loan or investment?', '["The interest earned","The final balance","The original amount borrowed or invested","The interest rate"]'::jsonb, 2, 'The principal is the original sum of money borrowed or invested, before interest is applied.', null, null, null, true, null, null, null, null),
('3cad9f55-12a8-4c1a-86bb-c1aa38995a9d', 'sm_complex_numbers', 'year_11', 'foundation', 'multiple_choice', 'Simplify i², where i is the imaginary unit.', '["1","i","−1","−i"]'::jsonb, 2, 'By definition, i² = −1.', null, null, null, true, null, null, null, null),
('265515d5-2037-4970-afd7-2def26515b11', 'sm_complex_numbers', 'year_11', 'developing', 'multiple_choice', 'What is the modulus of the complex number 3 + 4i?', '["5","7","25","12"]'::jsonb, 0, 'The modulus is √(3² + 4²) = √(9 + 16) = √25 = 5.', null, null, null, true, null, null, null, null),
('82f2daa3-b0b0-4c9f-be83-ca7d3b56b0c9', 'sm_vectors', 'year_11', 'developing', 'multiple_choice', 'What is the magnitude of the vector (6, 8)?', '["10","14","48","100"]'::jsonb, 0, 'Magnitude = √(6² + 8²) = √(36 + 64) = √100 = 10.', null, null, null, true, null, null, null, null),
('e1a9f16e-7ff7-4bbd-9f4b-599e364ceb21', 'sm_vectors', 'year_11', 'foundation', 'multiple_choice', 'Two vectors are perpendicular to each other. What is their dot product?', '["1","−1","0","Undefined"]'::jsonb, 2, 'Perpendicular vectors always have a dot product of 0.', null, null, null, true, null, null, null, null),
('c46988b5-f4e6-47d2-806b-54ff80b87bb8', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'A lift starts at basement level −8 and rises 5 floors. Using integers, what floor is it on now (−8 + 5)?', '["13","3","−13","−3"]'::jsonb, 3, 'Starting at −8 and moving 5 floors up gives −3.', 'AC9M7N02', null, null, true, null, null, null, null),
('313de050-f86d-4513-a3cf-f48c96c07a20', 'number_operations', 'year_7', 'developing', 'short_answer', 'A hiker starts at an elevation of 4 m above sea level. A nearby valley floor sits at −9 m. What is the difference in elevation between the hiker and the valley floor (4 − (−9))?', null, null, 'Subtracting a negative is the same as adding: 4 − (−9) = 4 + 9 = 13 m.', 'AC9M7N02', null, null, true, '13', null, null, null),
('2fc97a40-bd34-4417-a714-a96c102b6413', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'A scuba diver descends at a steady rate of 6 metres per minute below sea level. What is the diver''s change in height after 3 minutes, expressed as −6 × 3?', '["18","−18","−9","9"]'::jsonb, 1, 'A negative times a positive is negative: −6 × 3 = −18 m.', 'AC9M7N02', null, null, true, null, null, null, null),
('f95f13ff-73ec-4cd4-a218-bb81acb3d8e6', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'A social media post is shared by 3 people, and each of those people shares it with 3 new people, and this pattern repeats for a total of 4 rounds of sharing. How many people receive the post in the 4th round alone (3^4)?', '["12","64","81","34"]'::jsonb, 2, '3^4 means 3 × 3 × 3 × 3 = 81.', 'AC9M7N01', null, null, true, null, null, null, null),
('5fc67278-0e64-4736-b656-15f81cc0ecfb', 'number_operations', 'year_7', 'proficient', 'multiple_choice', 'A café orders 3.6 kg of coffee beans every week. How many kilograms of coffee beans does the café order over 8 weeks?', '["26.8 kg","30.8 kg","28.8 kg","21.6 kg"]'::jsonb, 2, '3.6 × 8 = 28.8 kg.', 'AC9M7N04', null, true, true, null, null, null, null),
('dc316ba0-4192-4570-9780-3a43a39a35f5', 'number_operations', 'year_7', 'proficient', 'short_answer', 'A charity fun run collects $6.85 per entrant, and 214 people register. How much money is collected in total?', null, null, '6.85 × 214 = $1465.90.', 'AC9M7N04', null, true, true, '$1465.90', ARRAY['1465.90', '1465.9']::text[], null, null),
('e27f8705-f33b-40b5-abe6-c7bd90613821', 'number_operations', 'year_7', 'proficient', 'multiple_choice', 'A cyclist travels 187.5 km over 7.5 hours at a constant speed. What is the cyclist''s speed in km/h?', '["22.5 km/h","27.5 km/h","20 km/h","25 km/h"]'::jsonb, 3, 'Speed = distance ÷ time = 187.5 ÷ 7.5 = 25 km/h.', 'AC9M7N05', null, true, true, null, null, null, null),
('57bbfce9-d36c-4c3e-bb63-8ab24a43fa74', 'number_operations', 'year_9', 'developing', 'multiple_choice', 'A digital storage capacity is represented by (2³)². Simplify this expression as a single power of 2.', '["2⁵","2⁹","4⁶","2⁶"]'::jsonb, 3, 'When raising a power to a power, multiply the exponents: 3 × 2 = 6.', 'AC9M9N01', null, null, true, null, null, null, null),
('7d4e96aa-648a-4d6a-ab43-d8d65280e457', 'number_operations', 'year_9', 'developing', 'multiple_choice', 'A physics formula includes the term 5⁻². Write this as a fraction in simplest form.', '["−25","1/10","1/25","25"]'::jsonb, 2, 'A negative exponent means the reciprocal: 5⁻² = 1/5² = 1/25.', 'AC9M9N01', null, null, true, null, null, null, null),
('73d8b99d-af3a-40fb-8ca2-fe299089215c', 'number_operations', 'year_9', 'developing', 'multiple_choice', 'An architect is working with a length related to √50. Simplify √50 to simplest surd form.', '["10√5","2√5","25√2","5√2"]'::jsonb, 3, '50 = 25 × 2, and √25 = 5, so √50 = 5√2.', 'AC9M9N01', null, null, true, null, null, null, null),
('aaa8bb88-9515-4757-bc38-4149bd566e31', 'number_operations', 'year_9', 'proficient', 'short_answer', 'A square garden bed has an area of 144 m². What is the length of one side of the garden bed?', null, null, '12 × 12 = 144, so the side length is √144 = 12 m.', 'AC9M9N01', null, null, true, '12 m', ARRAY['12']::text[], null, null),
('b13fafbf-d4c9-4e5c-aea8-c80143858572', 'number_operations', 'year_9', 'proficient', 'multiple_choice', 'A virus particle measures 0.000067 m across. Write this measurement in scientific notation.', '["6.7 × 10⁵","6.7 × 10⁻⁴","67 × 10⁻⁶","6.7 × 10⁻⁵"]'::jsonb, 3, 'Move the decimal 5 places right to get 6.7, so the exponent is −5: 6.7 × 10⁻⁵.', 'AC9M9N02', null, null, true, null, null, null, null),
('fbaff0bc-53e5-4488-ad98-2fce8cac537c', 'number_operations', 'year_9', 'proficient', 'short_answer', 'Find the simple interest earned on $3,450 invested at 4.25% p.a. for 3.5 years.', null, null, 'Simple interest = P × R × T = 3450 × 0.0425 × 3.5 = $513.19 (rounded to the nearest cent).', 'AC9M9N02', null, true, true, '$513.19', ARRAY['513.19']::text[], null, null),
('b32a0243-b462-4c90-a2aa-9aa87f309c90', 'number_operations', 'year_10', 'proficient', 'multiple_choice', 'A bacterium is about 0.000 002 metres across. Written in scientific notation, this is', '["2 × 10⁻⁶ m","2 × 10⁶ m","2 × 10⁻⁵ m","20 × 10⁻⁷ m"]'::jsonb, 0, 'The decimal point moves six places to the right to give 2, and the number is smaller than 1, so the index is negative: 2 × 10⁻⁶. Option D has the right value but the first number must lie between 1 and 10.', 'AC9M10N01', null, false, true, null, null, null, null),
('b26bbf0f-a601-4b42-a98c-48023f080bbc', 'number_operations', 'year_10', 'proficient', 'multiple_choice', 'A $1000 investment earns 10% per annum, compounding annually. Its value after 2 years is', '["$1200","$1100","$1210","$1021"]'::jsonb, 2, 'After one year the balance is 1000 × 1.1 = 1100, and after two it is 1100 × 1.1 = 1210 dollars. Option B applies simple interest instead.', 'AC9M10N01', null, true, true, null, null, null, null),
('ff00843a-5a16-4895-90d5-a33fe20a5ca6', 'number_operations', 'year_10', 'proficient', 'multiple_choice', 'A sheet of paper is folded in half repeatedly. After n folds its thickness is multiplied by 2ⁿ. The value of 2⁻³, the factor for "unfolding" three times, is', '["−8","−6","8","1/8"]'::jsonb, 3, 'A negative index means the reciprocal of the positive power: 2⁻³ = 1 ÷ 2³ = 1/8. A negative index never makes the value itself negative.', 'AC9M10N01', null, false, true, null, null, null, null),
('904bda3f-a679-4ee5-bcf9-e1a72312636e', 'number_operations', 'year_10', 'proficient', 'multiple_choice', 'A square tile has an area of 72 cm². Its side length in simplest surd form is', '["8√3 cm","6√2 cm","2√18 cm","36√2 cm"]'::jsonb, 1, 'The side is √72. Since 72 = 36 × 2, √72 = 6√2 cm. Option C is equal in value but is not in simplest form.', 'AC9M10N01', null, false, true, null, null, null, null),
('d423a0cd-68bf-42d5-815e-ccecb203bcc6', 'number_operations', 'year_10', 'foundation', 'multiple_choice', 'A cubical shipping crate has a volume of 27 m³. The length of one edge is', '["9 m","3 m","27 m","81 m"]'::jsonb, 1, 'The edge length is the cube root of the volume, and 3³ = 27, so each edge is 3 metres. Option B is the square root.', 'AC9M10N01', null, false, true, null, null, null, null),
('e10e329a-885c-4e04-a86d-38d46211122e', 'number_operations', 'year_10', 'foundation', 'multiple_choice', 'A square garden has an area of 16 m². Written as a power, its side length is 16^(1/2), which equals', '["8 m","32 m","256 m","4 m"]'::jsonb, 3, 'An index of 1/2 means the square root, and √16 = 4 metres. Option B halves 16 instead of taking the root.', 'AC9M10N01', null, false, true, null, null, null, null),
('9ca182f3-aa85-4808-9eac-0ba9d53a7a73', 'algebra_equations', 'year_7', 'foundation', 'multiple_choice', 'Jayden had some marbles. After his friend gave him 9 more, he had 15 marbles in total. How many marbles did Jayden start with?', '["7","9","6","24"]'::jsonb, 2, 'Let x = marbles Jayden started with. x + 9 = 15, so x = 15 − 9 = 6.', 'AC9M7A02', null, null, true, null, null, null, null),
('1034b9c8-fcdb-4e09-83e0-7a6acb0b5534', 'algebra_equations', 'year_7', 'developing', 'short_answer', 'Sam starts with $3 saved and adds $2 to his money box every week. After how many weeks, w, will he have saved $11 in total?', null, null, 'Subtract the initial $3: 2w = 8. Divide by 2: w = 4 weeks.', 'AC9M7A02', null, null, true, 'w = 4', ARRAY['4']::text[], null, null),
('2ec5007b-d101-4f23-971a-aa1ff1ccbd92', 'algebra_equations', 'year_7', 'foundation', 'multiple_choice', 'After giving away 5 of his trading cards, Oliver has 9 left. How many trading cards did he start with?', '["4","9","45","14"]'::jsonb, 3, 'Let x = the number Oliver started with. x − 5 = 9, so x = 9 + 5 = 14.', 'AC9M7A02', null, null, true, null, null, null, null),
('6265866a-edcd-44cb-9263-12c42b079adc', 'algebra_equations', 'year_7', 'developing', 'short_answer', 'A savings challenge: Chloe saves $2 in week 1, $5 in week 2, $8 in week 3, and $11 in week 4, saving $3 more than the previous week each time. Following this pattern, how much does she save in week 5?', null, null, 'The pattern increases by $3 each week. 11 + 3 = $14.', 'AC9M7A01', null, null, true, '$14', ARRAY['14']::text[], null, null),
('38bb97ff-90c9-4a51-a22b-6bd878efc1c9', 'algebra_equations', 'year_9', 'proficient', 'multiple_choice', 'Solve the inequality 3x − 5 > 13.', '["x > 6","x > 8","x < 6","x > 18"]'::jsonb, 0, 'Add 5 to both sides: 3x > 18. Divide both sides by 3: x > 6.', 'AC9M9A02', null, null, true, null, null, null, null),
('cdb1676d-faf1-4a1a-b5a8-6abd8d8fcd55', 'algebra_equations', 'year_9', 'proficient', 'multiple_choice', 'Expand and simplify (x + 4)².', '["x² + 16","x² + 4x + 16","x² + 8x + 8","x² + 8x + 16"]'::jsonb, 3, '(x + 4)² = (x + 4)(x + 4) = x² + 4x + 4x + 16 = x² + 8x + 16.', 'AC9M9A02', null, null, true, null, null, null, null),
('2e3ec299-6c90-4274-a80c-063637322cad', 'algebra_equations', 'year_9', 'developing', 'short_answer', 'The perimeter of a triangular garden bed is given by the expression 4x + 12. Factorise this expression to write it as a product of two factors.', null, null, '4 is the highest common factor of 4x and 12: 4x + 12 = 4(x + 3).', 'AC9M9A02', null, null, true, '4(x + 3)', null, null, null),
('2b040909-ef98-42cd-b62e-15d11622c042', 'algebra_equations', 'year_9', 'proficient', 'short_answer', 'If a = −3 and b = 5, what is the value of 2a² − b?', null, null, 'a² = (−3)² = 9, so 2a² = 18. Then 18 − 5 = 13.', 'AC9M9A02', null, null, true, '13', null, null, null),
('c831234d-63b0-48fc-a865-d80d2c0d00fc', 'algebra_equations', 'year_10', 'proficient', 'multiple_choice', 'The profit, in dollars, from selling x items is P(x) = 2x² − 30x. The profit from selling 20 items is', '["$200","$170","$−200","$1000"]'::jsonb, 0, 'Substituting x = 20 gives P(20) = 2 × 400 − 30 × 20 = 800 − 600 = 200 dollars.', 'AC9M10A01', null, false, true, null, null, null, null),
('5cd03b0a-fa8f-4aaf-a9ab-52d0e9c65fd9', 'algebra_equations', 'year_10', 'proficient', 'multiple_choice', 'A rectangular courtyard is 1 metre longer than it is wide and has an area of 6 m². Solving w² + w − 6 = 0 gives the possible widths as', '["w = 3 or w = −2, so the width is 3 m","w = 2 or w = 3, so the width is 3 m","w = 2 or w = −3, so the width is 2 m","w = 6 or w = 1, so the width is 1 m"]'::jsonb, 2, 'Factorising gives (w + 3)(w − 2) = 0, so w = −3 or w = 2. A width cannot be negative, so the courtyard is 2 m by 3 m, giving the area of 6 m².', 'AC9M10A01', null, false, true, null, null, null, null),
('9eea03a2-7aaf-4102-9dae-7d1af6e23012', 'algebra_equations', 'year_10', 'proficient', 'multiple_choice', 'The temperature of a cooling engine, in degrees Celsius above the air temperature, is T(t) = 80 − t² after t minutes. After 3 minutes it is', '["77 °C above air temperature","74 °C above air temperature","80 °C above air temperature","71 °C above air temperature"]'::jsonb, 3, 'Substituting t = 3 gives T(3) = 80 − 9 = 71 degrees above the air temperature. Option B subtracts 3 rather than 3².', 'AC9M10A01', null, false, true, null, null, null, null),
('9190e288-22eb-429b-bbff-ad3610605c4c', 'geometry_measurement', 'year_10', 'advanced', 'multiple_choice', 'A cylindrical water tank has a radius of 5 m and a height of 10 m. Its capacity, in litres, is closest to', '["785 000 L","785 L","157 000 L","1 570 000 L"]'::jsonb, 0, 'Volume = π × 5² × 10 = 785.4 m³, and one cubic metre is 1000 litres, so the tank holds about 785 000 L.', 'AC9M10M01', null, true, true, null, null, null, null),
('22ac34c3-6ca4-41f6-a24b-c44d778edee9', 'geometry_measurement', 'year_10', 'proficient', 'multiple_choice', 'A spherical ball bearing has a radius of 3 mm. Its volume is closest to', '["36 mm³","339 mm³","28 mm³","113 mm³"]'::jsonb, 3, 'Volume = (4/3)πr³ = (4/3) × π × 27 = 113 mm³. Option B leaves out the factor of 4/3 and π.', 'AC9M10M01', null, true, true, null, null, null, null),
('b353a08f-7d72-48af-833a-46de67966067', 'geometry_measurement', 'year_10', 'advanced', 'multiple_choice', 'A conical paper cup has a radius of 3 cm and a height of 9 cm. Its capacity is closest to', '["254 mL","85 mL","28 mL","9 mL"]'::jsonb, 1, 'Volume = (1/3)πr²h = (1/3) × π × 9 × 9 = 84.8 cm³, and 1 cm³ is 1 mL, so the cup holds about 85 mL. Option B forgets the one third.', 'AC9M10M01', null, true, true, null, null, null, null),
('7ae20c34-1e76-4ccb-bea8-715be3833434', 'statistics_probability', 'year_7', 'developing', 'multiple_choice', 'A bag contains counters of two colours:
Colour | Count
Red    | 4
Blue   | 6
What is the probability of drawing a blue counter?', '["3/5","2/5","4/10","6/4"]'::jsonb, 0, 'There are 6 blue counters out of 10 total: 6/10 simplifies to 3/5.', 'AC9M7P01', null, null, true, null, null, null, null),
('01a71c8b-d3c3-45b7-a9f9-aec9fb89aa2f', 'statistics_probability', 'year_7', 'developing', 'multiple_choice', 'The weather bureau reports that the probability it rains tomorrow is 0.3. What is the probability that it does NOT rain?', '["0.3","0.7","1.3","0"]'::jsonb, 1, 'Probabilities of complementary events add to 1: 1 − 0.3 = 0.7.', 'AC9M7P02', null, null, true, null, null, null, null),
('24ca0892-e742-40b3-90d2-bacd6f042369', 'statistics_probability', 'year_7', 'developing', 'short_answer', 'A spinner has 8 equal sections numbered 1 to 8. What is the probability, as a fraction in simplest form, of landing on a number greater than 6?', null, null, 'Numbers greater than 6 are 7 and 8 — that is 2 out of 8 sections, which simplifies to 1/4.', 'AC9M7P01', null, null, true, '1/4', ARRAY['2/8', '0.25', '25%']::text[], null, null),
('ad5e5694-03c5-45e1-80ae-e76b2276f813', 'statistics_probability', 'year_9', 'developing', 'multiple_choice', 'On a given day, the probability of rain is 0.5, and the probability of strong wind is 0.4. These two events are independent. What is the probability that it rains AND is windy on that day?', '["0.9","0.1","0.5","0.2"]'::jsonb, 3, 'For independent events, P(A and B) = P(A) × P(B) = 0.5 × 0.4 = 0.2.', 'AC9M9P01', null, null, true, null, null, null, null),
('58bfdf43-2257-4814-9ae8-879911ca29b1', 'statistics_probability', 'year_9', 'proficient', 'multiple_choice', 'A card is drawn from a standard 52-card deck. Let A = drawing a heart, with P(A) = 0.25, and B = drawing a spade, with P(B) = 0.25. A card cannot be both a heart and a spade, so A and B are mutually exclusive. What is P(A or B)?', '["0.5","0.0625","0.25","1"]'::jsonb, 0, 'For mutually exclusive events, P(A or B) = P(A) + P(B) = 0.25 + 0.25 = 0.5.', 'AC9M9P01', null, null, true, null, null, null, null),
('ef259b67-35f8-4296-ac80-2e647796ccf0', 'statistics_probability', 'year_9', 'developing', 'multiple_choice', 'A quality inspector finds that the probability a light bulb fails a test is 0.1. What is the probability that a randomly chosen bulb passes the test?', '["0.1","0.9","1.1","0"]'::jsonb, 1, 'Probabilities of complementary events add to 1: 1 − 0.1 = 0.9.', 'AC9M9P02', null, null, true, null, null, null, null),
('33ba0bde-9e60-4363-b071-94f8999ec83e', 'statistics_probability', 'year_10', 'proficient', 'multiple_choice', 'The times taken by a group of runners have a lower quartile of 10 minutes and an upper quartile of 18 minutes. Any time greater than which value would be shown as an outlier?', '["26 minutes","30 minutes","22 minutes","18 minutes"]'::jsonb, 1, 'The interquartile range is 18 − 10 = 8, and 1.5 × 8 = 12. The upper fence is 18 + 12 = 30 minutes.', 'AC9M10ST01', null, false, true, null, null, null, null),
('1627fa12-a6e1-42f8-bb1f-9234b9c854a7', 'statistics_probability', 'year_10', 'advanced', 'multiple_choice', 'A class recorded these test scores: 12, 15, 15, 18, 21, 22, 25, 27, 30, 34. The interquartile range is', '["10","12","22","15"]'::jsonb, 1, 'With ten values, the lower half is 12, 15, 15, 18, 21 with median 15, and the upper half is 22, 25, 27, 30, 34 with median 27. The interquartile range is 27 − 15 = 12.', 'AC9M10ST01', null, true, true, null, null, null, null),
('b38473c1-47fc-4301-a8cc-5bd40adbe16f', 'statistics_probability', 'year_10', 'advanced', 'multiple_choice', 'Seven students recorded the number of books they read over summer: 2, 4, 5, 7, 9, 12, 15. If an eighth student who read 20 books is added, the median becomes', '["7","9","8","9.25"]'::jsonb, 2, 'With eight values the median is the average of the fourth and fifth: (7 + 9) ÷ 2 = 8. Adding one large value moves the median only slightly, from 7 to 8, while the mean rises much more.', 'AC9M10ST01', null, false, true, null, null, null, null),
('623b4eb3-bc36-4ee6-ad22-f40f68a81bec', 'reading_comprehension', 'grade_3', 'foundation', 'multiple_choice', 'Read: "The puppy chased its tail in circles until it got dizzy and flopped onto the grass." What happened after the puppy chased its tail?', '["It flopped onto the grass","It ran away","It fell asleep","It chased a cat"]'::jsonb, 0, 'The passage says the puppy "flopped onto the grass" after getting dizzy from chasing its tail.', 'AC9E3LY06', null, null, true, null, null, null, null),
('09b17030-e907-4497-a0ba-49ffcd93f568', 'reading_comprehension', 'grade_3', 'developing', 'multiple_choice', 'Read: "Mia forgot her umbrella, so she got soaked walking home in the rain." Why did Mia get soaked?', '["She dropped her umbrella","She stood in a puddle","She walked too slowly","She forgot her umbrella"]'::jsonb, 3, 'The word "so" signals the reason: Mia forgot her umbrella, which is why she got soaked.', 'AC9E3LY06', null, null, true, null, null, null, null),
('4b595291-84d1-4e63-be7e-5dee4e35c421', 'reading_comprehension', 'grade_4', 'developing', 'multiple_choice', 'Read: "Even though Sam was scared of the dark, he walked into the basement to find the flashlight for his dad." What can you tell about Sam?', '["He was looking for a toy","He was brave despite his fear","He was not afraid of anything","He refused to help his dad"]'::jsonb, 1, 'Sam went into the dark basement even though he was scared, showing he acted bravely despite his fear.', 'AC9E4LY07', null, null, true, null, null, null, null),
('43ff48d0-9ead-4b89-848e-df4e9d20f7a2', 'reading_comprehension', 'grade_4', 'developing', 'multiple_choice', 'Read: "The recipe said to bake the cake for 30 minutes, but after 20 minutes it already smelled burnt." What might happen next?', '["The cake may need to be checked or removed early","The cake will taste better","The oven will turn off by itself","The recipe was wrong about the ingredients"]'::jsonb, 0, 'A burnt smell before the timer ends suggests the cake should be checked, since it may be overcooking.', 'AC9E4LY07', null, null, true, null, null, null, null),
('770bdf3e-1561-40a5-b3d1-53064b6b431c', 'reading_comprehension', 'grade_5', 'developing', 'multiple_choice', 'Read: "Even though the shop was closing, the shopkeeper let the child search a little longer for her lost coin." What does this show about the shopkeeper?', '["He was in a hurry to leave","He was patient and kind","He disliked children","He wanted to close early"]'::jsonb, 1, 'Letting the child keep searching despite closing time shows the shopkeeper being patient and kind.', 'AC9E5LY07', null, null, true, null, null, null, null),
('6b2d3c0d-2330-4040-9a4e-273c6ffb690e', 'reading_comprehension', 'grade_5', 'proficient', 'multiple_choice', 'Read: "The old dog no longer chased balls, but its tail still wagged the moment its owner walked through the door." What does this suggest about the dog?', '["It is a puppy learning new tricks","It is afraid of its owner","It is older and slower, but still loves its owner","It no longer likes its owner"]'::jsonb, 2, 'The dog''s slower behaviour paired with its wagging tail suggests age has not changed its affection for its owner.', 'AC9E5LY07', null, null, true, null, null, null, null),
('98be739d-2fde-47b4-9c42-69962c3c5031', 'reading_comprehension', 'grade_6', 'developing', 'multiple_choice', 'A story told from the perspective of a character using "I" and "me" is written in which point of view?', '["Third person omniscient","First person","Second person","Third person limited"]'::jsonb, 1, 'First person narration uses "I" and "me" because the narrator is a character inside the story.', 'AC9E6LE07', null, null, true, null, null, null, null),
('328d774b-e27a-49d0-bc8b-be509b424240', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'Read: "The coach benched their star player for missing practice, even though it meant a tougher game ahead." What value does this show the coach holds?', '["Discipline matters more than winning","Winning is the only priority","Practice is unimportant","Star players deserve special treatment"]'::jsonb, 0, 'Choosing to bench a key player despite the cost to the team shows the coach values discipline over winning.', 'AC9E6LY08', null, null, true, null, null, null, null),
('84ebf2ed-7779-4e09-bcae-e390049ba658', 'reading_literary_analysis', 'year_7', 'proficient', 'multiple_choice', 'Read: "The classroom was a zoo the moment the teacher stepped out." This sentence mainly uses which literary device?', '["Simile","Metaphor","Onomatopoeia","Alliteration"]'::jsonb, 1, 'Calling the classroom "a zoo" directly, without using "like" or "as", makes this a metaphor.', 'AC9E7LE05', null, null, true, null, null, null, null),
('33c43391-43cc-458f-ba46-227185b1a029', 'reading_literary_analysis', 'year_7', 'proficient', 'multiple_choice', 'Read: "She smiled and wished them luck, but her clenched fists told a different story." What technique is being used here?', '["A flashback to an earlier event","Dialogue between two characters","Contrast between words and actions to reveal true feelings","A direct statement of her feelings"]'::jsonb, 2, 'The gap between her smiling words and clenched fists shows the reader her true feelings without stating them directly.', 'AC9E7LE05', null, null, true, null, null, null, null),
('1933a286-11e0-4eaa-89c8-019c574bdb87', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'Read: "The committee ''carefully considered'' the proposal for three years before rejecting it in a five-minute meeting." The phrase "carefully considered" is likely being used:', '["To describe a scientific process","Ironically, to suggest the opposite was true","Literally, to praise the committee","As a direct quotation from the proposal"]'::jsonb, 1, 'The contrast between three years of "careful" consideration and a five-minute rejection signals irony.', 'AC9E8LE05', null, null, true, null, null, null, null),
('feca9da2-0898-43b8-8692-6b5b5522d2eb', 'reading_literary_analysis', 'year_8', 'developing', 'multiple_choice', 'What is the primary purpose of a topic sentence in a paragraph?', '["To state the main idea the paragraph will develop","To conclude the paragraph","To provide a citation","To ask a rhetorical question"]'::jsonb, 0, 'A topic sentence introduces the main idea that the rest of the paragraph explains or supports.', 'AC9E8LY07', null, null, true, null, null, null, null),
('27871b25-bb65-41f1-8e4b-7a279d3863a2', 'reading_literary_analysis', 'year_9', 'advanced', 'multiple_choice', 'A brief, exaggerated imitation of another work, created for comic effect, is called a:', '["Elegy","Parody","Soliloquy","Satire"]'::jsonb, 1, 'A parody humorously imitates the style of another work, whereas satire more broadly criticises a subject.', 'AC9E9LE04', null, null, true, null, null, null, null),
('c711af90-db1d-490b-bd37-0bfaeec82ce2', 'reading_literary_analysis', 'year_9', 'proficient', 'multiple_choice', 'Read: "Progress," the mayor announced, standing before the newly bulldozed park. What is the effect of placing "Progress" before describing the bulldozed park?', '["It shows the mayor dislikes progress","It is simply a neutral description","It creates irony by contrasting the word with the destruction shown","It proves the mayor is honest"]'::jsonb, 2, 'Opening with "Progress" right before revealing a destroyed park creates a jarring, ironic contrast.', 'AC9E9LE04', null, null, true, null, null, null, null),
('436f667e-877d-420c-bbac-7fe10db6b9bd', 'reading_literary_analysis', 'year_10', 'advanced', 'multiple_choice', 'In a persuasive text, an appeal to the audience''s emotions is known as:', '["Kairos","Pathos","Logos","Ethos"]'::jsonb, 1, 'Pathos refers to a persuasive appeal to the audience''s emotions, as distinct from logos (logic) and ethos (credibility).', 'AC9E10LE05', null, null, true, null, null, null, null),
('a06f3979-5b58-46d5-a0e3-698f7430b297', 'reading_literary_analysis', 'year_10', 'proficient', 'multiple_choice', 'Read: "The report concluded that further research was needed, a phrase repeated in every study the company had funded for a decade." What does this suggest about the company''s intentions?', '["It may be deliberately delaying a definitive conclusion","It is committed to rapid scientific progress","It has already solved the problem","It disagrees with all its own research"]'::jsonb, 0, 'A decade of studies all reaching the same inconclusive result suggests the delay may be intentional rather than accidental.', 'AC9E10LY07', null, null, true, null, null, null, null),
('18b155bb-548c-4040-9968-5522e31026cb', 'reading_comprehension', 'grade_3', 'developing', 'multiple_choice', 'Read: "Ben planted a seed and watered it every day until a tiny green sprout appeared." What lesson does this story teach?', '["Seeds grow without water","Patience and care lead to growth","Plants grow overnight","Watering plants is unnecessary"]'::jsonb, 1, 'Ben''s daily care over time, ending in a sprout, shows that patience and care lead to results.', 'AC9E3LY06', null, null, true, null, null, null, null),
('ee79bbce-3912-4e91-bd70-d0589438a95d', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'Read: "Lily wanted to join the soccer team, but she practised kicking a ball alone in her backyard for weeks first." What does this show about Lily?', '["She is not a team player","She gave up on her goal","She prepares before taking on a challenge","She dislikes soccer"]'::jsonb, 2, 'Practising alone for weeks before joining shows Lily prepares herself before facing a new challenge.', 'AC9E4LY07', null, null, true, null, null, null, null),
('fbb0f1ed-8775-4083-9e1e-ef902c7fe830', 'reading_comprehension', 'grade_5', 'proficient', 'multiple_choice', 'Read: "The librarian whispered even when the library was empty, out of habit." What does this detail suggest about the librarian?', '["The librarian is afraid of being heard","Years of habit shape behaviour even when it is not needed","The librarian dislikes silence","The library is never empty"]'::jsonb, 1, 'Whispering out of habit, even alone, shows how a long-practised behaviour can continue automatically.', 'AC9E5LY07', null, null, true, null, null, null, null),
('6bb7f299-1ee6-49a3-b7a1-9be4915d8ffb', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'Read: "The map was old and torn, but the explorer trusted it more than the shiny new one in his pocket." What can you infer about the explorer?', '["He values experience and familiarity over newness","He dislikes maps in general","He is lost without any map","He prefers new technology"]'::jsonb, 0, 'Trusting the old, worn map over a new one suggests the explorer values familiarity and proven reliability.', 'AC9E6LY08', null, null, true, null, null, null, null),
('7e00dce8-0d74-4a87-a49e-2c0c5debd1ed', 'reading_literary_analysis', 'year_7', 'developing', 'multiple_choice', 'Read: "The crowd fell silent the moment the conductor raised his baton." What is the effect of this sentence?', '["It shows the audience was bored","It suggests the concert had ended","It describes the conductor leaving the stage","It builds anticipation before the music begins"]'::jsonb, 3, 'The sudden silence right before the baton rises creates a sense of anticipation for what is about to happen.', 'AC9E7LE05', null, null, true, null, null, null, null),
('f5f03776-8a15-41a2-9526-81c26f13d799', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'Read: "He apologised with his mouth, but his eyes never left his phone." What technique is the author using?', '["Foreshadowing a future event","A direct statement of the character''s honesty","Contrasting words and actions to reveal insincerity","A literal description of an apology"]'::jsonb, 2, 'Placing the spoken apology next to the distracted action reveals that the apology was not sincere.', 'AC9E8LE05', null, null, true, null, null, null, null),
('c9b26a99-93a8-4f9e-a2ca-d3d179f86c82', 'reading_literary_analysis', 'year_9', 'proficient', 'multiple_choice', 'Read: "The factory''s brochure called it a ''family,'' though most employees had never met the owner." What is implied by this sentence?', '["The factory is small and close-knit","The word \"family\" may be misleading marketing language","The employees are all related","The owner visits often"]'::jsonb, 1, 'The contrast between the word "family" and employees never meeting the owner suggests the term is used loosely, perhaps for marketing effect.', 'AC9E9LY07', null, null, true, null, null, null, null),
('ef3f93b1-2b8b-4db2-8299-e13112850520', 'reading_literary_analysis', 'year_10', 'advanced', 'multiple_choice', 'Read: "The senator promised transparency, then closed the meeting to the public for the third time that year." What rhetorical effect does this sequence create?', '["It exposes a contradiction between the senator''s words and actions","It confirms the senator kept their promise","It shows the senator dislikes public meetings","It has no particular effect"]'::jsonb, 0, 'Stating a promise of transparency immediately before describing closed meetings highlights the contradiction between word and deed.', 'AC9E10LE05', null, null, true, null, null, null, null),
('42b696fb-1053-48fa-9656-45a4e5141a7b', 'grammar_punctuation', 'grade_3', 'foundation', 'multiple_choice', 'Which sentence is punctuated correctly?', '["My dog is called Max.","my dog is called max.","My dog is called max","My Dog is called max"]'::jsonb, 0, 'Sentences start with a capital letter, names are capitalised, and statements end with a full stop.', 'AC9E3LA05', null, null, true, null, null, null, null),
('aab3ff12-c8b9-4ba9-965f-3186716d33f7', 'grammar_punctuation', 'grade_3', 'developing', 'multiple_choice', 'Which word correctly completes: ''I ___ to the park yesterday.''', '["goes","going","go","went"]'::jsonb, 3, '''Went'' is the past tense of ''go'', matching the word ''yesterday''.', 'AC9E3LA06', null, null, true, null, null, null, null),
('83502520-39b2-4d5f-8508-a10b47070e8f', 'grammar_punctuation', 'grade_4', 'developing', 'multiple_choice', 'Which sentence uses "there", "their", or "they''re" correctly?', '["Their going to the park.","They''re going to the park.","There going to the park.","They is going to the park."]'::jsonb, 1, '''They''re'' is the contraction of ''they are'', which fits before ''going''.', 'AC9E4LA07', null, null, true, null, null, null, null),
('8d305fb5-75f6-4354-99df-5b2252eb4b8a', 'grammar_punctuation', 'grade_4', 'developing', 'multiple_choice', 'Which sentence uses commas correctly in a list?', '["I packed apples bananas and grapes.","I packed apples, bananas and, grapes.","I packed apples, bananas, and grapes.","I packed, apples, bananas, and grapes."]'::jsonb, 2, 'Commas separate each item in a list, with the last item usually joined by "and".', 'AC9E4LA07', null, null, true, null, null, null, null),
('4bd961ca-c77a-40b6-85dd-48a1e56447c0', 'grammar_punctuation', 'grade_5', 'developing', 'multiple_choice', 'Which sentence uses the correct homophone?', '["Their going to there house over they''re.","There going to their house over they''re.","They''re going to they''re house over their.","They''re going to their house over there."]'::jsonb, 3, '''They''re'' = they are, ''their'' = possession, ''there'' = a place. Only the first sentence uses all three correctly.', 'AC9E5LA08', null, null, true, null, null, null, null),
('6c1a9c18-df74-41d7-b403-81292d5c89d7', 'grammar_punctuation', 'grade_5', 'developing', 'multiple_choice', 'Which sentence correctly uses quotation marks for speech?', '["\"I am ready,\" said Maya","''I am ready,'' said Maya.\"","\"I am ready,\" said Maya.","I am ready, said Maya."]'::jsonb, 2, 'Quotation marks surround the exact words spoken, with punctuation inside the closing mark.', 'AC9E5LA09', null, null, true, null, null, null, null),
('1d3c4617-39fd-4fb7-8f70-b8327c5e6f1a', 'grammar_punctuation', 'grade_6', 'proficient', 'multiple_choice', 'Which sentence has correct subject-verb agreement?', '["The class has a test today.","The class have a test today.","The class having a test today.","The class have has a test today."]'::jsonb, 0, '''Class'' is a collective noun treated as singular in Australian English, so it takes ''has''.', 'AC9E6LA07', null, null, true, null, null, null, null),
('ed971577-6cda-4791-a618-1e206bd5d838', 'grammar_punctuation', 'grade_6', 'developing', 'multiple_choice', 'Which sentence uses the correct pronoun?', '["She gave the book to him and I.","She gave the book to he and I.","She gave the book to him and myself.","She gave the book to him and me."]'::jsonb, 3, '''Me'' is the correct object pronoun after a preposition like ''to'', not ''I''.', 'AC9E6LA08', null, null, true, null, null, null, null),
('415dc692-53e4-4e69-aeb7-7c0d6b71e90e', 'grammar_punctuation', 'year_7', 'developing', 'multiple_choice', 'Which word correctly completes: ''Each of the students ___ a locker.''', '["has","have","were","are"]'::jsonb, 0, '''Each'' is singular, so it takes the singular verb ''has'', even though ''students'' is plural.', 'AC9E7LA05', null, null, true, null, null, null, null),
('0980a6fc-b23f-4807-bbf0-a1c5f37b0323', 'grammar_punctuation', 'year_7', 'developing', 'multiple_choice', 'Which sentence avoids a comma splice?', '["I was tired I went to bed.","I was tired, and, I went to bed.","I was tired, I went to bed.","I was tired, so I went to bed."]'::jsonb, 3, 'A comma splice joins two independent clauses with only a comma; adding a conjunction like "so" fixes it.', 'AC9E7LA06', null, null, true, null, null, null, null),
('419ca4df-a461-4094-adb2-160c1ca07d86', 'grammar_punctuation', 'year_8', 'proficient', 'multiple_choice', 'Which sentence correctly uses a dash for emphasis?', '["The plan was perfect, until it wasn''t.","The plan was perfect until it wasn''t—","The plan was perfect—until it wasn''t.","The plan was perfect; until, it wasn''t."]'::jsonb, 2, 'A dash can be used to create a dramatic pause before an unexpected turn, placed directly between the two clauses.', 'AC9E8LA06', null, null, true, null, null, null, null),
('9f5794dc-cd81-46ca-966b-15ccf4b957d8', 'grammar_punctuation', 'year_8', 'developing', 'multiple_choice', 'Which sentence correctly uses "affect" or "effect"?', '["The weather will affect our plans.","The weather will effect our plans.","The weather will have an affect on our plans.","The weather will affects our plans."]'::jsonb, 0, '''Affect'' is usually a verb meaning to influence; ''effect'' is usually a noun meaning a result.', 'AC9E8LA07', null, null, true, null, null, null, null),
('eeaad202-185f-466d-9105-44350a102553', 'grammar_punctuation', 'year_9', 'proficient', 'multiple_choice', 'Which sentence correctly uses "which" to add extra, non-essential information?', '["The book which I borrowed last week is overdue.","The book, that I borrowed last week, is overdue.","The book, which I borrowed last week, is overdue.","The book who I borrowed last week is overdue."]'::jsonb, 2, '''Which'' introduces non-essential information and is set off with commas; ''that'' introduces essential information without commas.', 'AC9E9LA06', null, null, true, null, null, null, null),
('d441055b-36ae-46d3-bcf8-9f1339d19840', 'grammar_punctuation', 'year_9', 'proficient', 'multiple_choice', 'Identify the sentence written in the passive voice.', '["The window was broken by the storm.","The storm is breaking the window.","The storm will break the window.","The storm broke the window."]'::jsonb, 0, 'In the passive voice, the subject receives the action instead of performing it: "the window was broken" rather than "the storm broke".', 'AC9E9LA07', null, null, true, null, null, null, null),
('1a2b8b90-23cb-4a4c-ba56-e1f69eb5bf8b', 'grammar_punctuation', 'year_10', 'proficient', 'multiple_choice', 'Which sentence correctly uses the conditional tense?', '["If it would rain, I stay home.","If it rained, I would stay home.","If it rains, I would stay home.","If it rained, I will stay home."]'::jsonb, 1, 'A hypothetical condition in the past tense ("if it rained") pairs with "would" in the result clause.', 'AC9E10LA06', null, null, true, null, null, null, null),
('bdee6a98-b2c7-49e4-bca6-5437992f5bd8', 'grammar_punctuation', 'year_10', 'proficient', 'multiple_choice', 'Which sentence correctly uses "fewer" rather than "less"?', '["There are fewer students in this class.","There is less students in this class.","There are less students in this class.","There are fewer student in this class."]'::jsonb, 0, '''Fewer'' is used for countable nouns like ''students''; ''less'' is used for uncountable quantities.', 'AC9E10LA07', null, null, true, null, null, null, null),
('cb264ff5-f2a1-43f3-b425-4dd2a0e38312', 'grammar_punctuation', 'grade_3', 'foundation', 'multiple_choice', 'Which sentence is a complete sentence?', '["Barked loudly.","The dog barked loudly.","The dog.","Loudly barked."]'::jsonb, 1, 'A complete sentence needs both a subject (the dog) and a verb (barked).', 'AC9E3LA05', null, null, true, null, null, null, null),
('b5bf7939-662f-4e8f-b1f5-1bc9c46f887c', 'grammar_punctuation', 'grade_3', 'developing', 'multiple_choice', 'Which word is spelled correctly?', '["becouse","because","beacause","becuase"]'::jsonb, 1, '''Because'' is spelled b-e-c-a-u-s-e.', 'AC9E3LA07', null, null, true, null, null, null, null),
('37c278a6-c23c-4a4e-bff0-b5dcb0e081a6', 'grammar_punctuation', 'grade_4', 'developing', 'multiple_choice', 'Which sentence uses the correct plural?', '["The children played outside.","The child played outside.","The childs played outside.","The childrens played outside."]'::jsonb, 0, '''Children'' is the irregular plural of ''child''.', 'AC9E4LA06', null, null, true, null, null, null, null),
('82e123eb-29fc-4f08-a911-81dedb6de651', 'grammar_punctuation', 'grade_4', 'developing', 'multiple_choice', 'Which sentence correctly uses "a" or "an"?', '["She ate a apple.","She ate an banana.","She ate a orange.","She ate an apple."]'::jsonb, 3, '''An'' is used before words that start with a vowel sound, like ''apple''.', 'AC9E4LA06', null, null, true, null, null, null, null),
('994b6be4-e9dd-463c-ab01-911049316286', 'grammar_punctuation', 'grade_5', 'developing', 'multiple_choice', 'Which sentence uses the correct verb tense?', '["Yesterday, we walked to school.","Yesterday, we walk to school.","Yesterday, we walking to school.","Yesterday, we will walk to school."]'::jsonb, 0, '''Walked'' is the past tense, matching the word ''yesterday''.', 'AC9E5LA08', null, null, true, null, null, null, null),
('ab8b2ecc-38b1-4095-ac73-3147016fc59c', 'grammar_punctuation', 'grade_5', 'proficient', 'multiple_choice', 'Which sentence correctly uses an adverb?', '["She ran quickness to the bus.","She ran quicker to the bus fastly.","She ran quick to the bus.","She ran quickly to the bus."]'::jsonb, 3, '''Quickly'' is an adverb describing how she ran; adverbs often end in ''-ly''.', 'AC9E5LA09', null, null, true, null, null, null, null),
('63a99f0d-ce9c-4eb4-8b13-3bbdfd925ca4', 'grammar_punctuation', 'grade_6', 'developing', 'multiple_choice', 'Which sentence uses an apostrophe correctly to show possession?', '["The dog''s'' bone was buried in the yard.","The dog''s bone was buried in the yard.","The dogs'' bone was buried in the yard.","The dogs bone was buried in the yard."]'::jsonb, 1, 'For a single dog, the apostrophe goes before the s: dog''s.', 'AC9E6LA07', null, null, true, null, null, null, null),
('ca820a5b-2273-4657-9717-dc224d70719e', 'grammar_punctuation', 'grade_6', 'proficient', 'multiple_choice', 'Which sentence is written in the active voice?', '["The mouse was chased by the cat.","The cat chased the mouse.","The mouse is being chased.","The mouse had been chased."]'::jsonb, 1, 'In the active voice, the subject (the cat) performs the action directly.', 'AC9E6LA08', null, null, true, null, null, null, null),
('31bb0035-32e4-4cfa-91d2-261eeb8a89c2', 'grammar_punctuation', 'year_7', 'proficient', 'multiple_choice', 'Which sentence uses "who" correctly?', '["The woman whom called is my aunt.","The woman who called is my aunt.","The woman which called is my aunt.","The woman who called was my aunt yesterday still calling."]'::jsonb, 1, '''Who'' refers to the subject performing the action (called); ''whom'' refers to an object.', 'AC9E7LA05', null, null, true, null, null, null, null),
('b46b99a1-a469-45c4-b4da-bb8b35203cfd', 'grammar_punctuation', 'year_7', 'developing', 'multiple_choice', 'Which sentence shows correct parallel structure?', '["She likes to hike, swimming, and biking.","She likes hiking, swimming, and biking.","She likes hiking, to swim, and biking.","She likes hiking, swimming, and to bike."]'::jsonb, 1, 'Parallel structure keeps items in a list in the same grammatical form; all three should end in "-ing".', 'AC9E7LA06', null, null, true, null, null, null, null),
('c2565fdf-21b6-4047-870a-d1d5db76d492', 'grammar_punctuation', 'year_8', 'developing', 'multiple_choice', 'Which sentence avoids a dangling modifier?', '["Walking to school, the rainbow was seen by Ben.","Walking to school, a rainbow appeared to Ben.","A rainbow was walking to school, Ben saw.","Walking to school, Ben saw a rainbow."]'::jsonb, 3, 'The modifier "walking to school" should describe the person doing the walking, which is Ben.', 'AC9E8LA06', null, null, true, null, null, null, null),
('dba9784f-21e1-464c-ab61-976912fb6d00', 'grammar_punctuation', 'year_8', 'proficient', 'multiple_choice', 'Which sentence correctly uses a colon?', '["She packed: three things, a map, a torch, and water.","She packed three things: a map, a torch, and water.","She packed three things, a map, a torch, and water:","She packed three things a map: a torch, and water."]'::jsonb, 1, 'A colon introduces a list after a complete independent clause.', 'AC9E8LA07', null, null, true, null, null, null, null),
('04b86f71-cfed-40b6-9529-1116068da867', 'grammar_punctuation', 'year_9', 'proficient', 'multiple_choice', 'Identify the subordinate clause in this sentence: "Although it was raining, we went outside."', '["We went outside","It was raining outside","Although we went outside","Although it was raining"]'::jsonb, 3, 'A subordinate clause cannot stand alone; "although it was raining" depends on the main clause "we went outside".', 'AC9E9LA06', null, null, true, null, null, null, null),
('2eb29ebd-6a5a-4b1b-aefb-da04ca178d09', 'grammar_punctuation', 'year_9', 'developing', 'multiple_choice', 'Which sentence correctly uses "that" for essential information, without commas?', '["The book, which I borrowed is overdue.","The book that I borrowed is overdue.","The book that, I borrowed, is overdue.","The book, that I borrowed, is overdue."]'::jsonb, 1, '''That'' introduces essential information and is not set off by commas.', 'AC9E9LA07', null, null, true, null, null, null, null),
('52ec8f3e-bc8a-460b-a4be-6681e3f8604c', 'grammar_punctuation', 'year_10', 'advanced', 'multiple_choice', 'Which sentence uses parallel structure correctly?', '["Not only finishing the race, but she also broke the record.","Not only did she finish the race, but she also broke the record.","Not only she finished the race, but also breaking the record.","Not only did she finish the race, but also she broke the record differently."]'::jsonb, 1, 'Parallel structure requires matching grammatical forms after "not only" and "but also".', 'AC9E10LA06', null, null, true, null, null, null, null),
('ed01bd6d-9738-4f02-9096-481cac56cbd2', 'grammar_punctuation', 'year_10', 'proficient', 'multiple_choice', 'Which sentence is a complete sentence rather than a fragment?', '["Because the storm was approaching, the ship returned to port.","Because the storm was approaching.","The ship, because the storm was approaching.","Returning to port because of the storm."]'::jsonb, 0, 'A sentence fragment is missing an independent clause; only the first option has both a subordinate and a main clause.', 'AC9E10LA07', null, null, true, null, null, null, null),
('71447fea-2b90-447a-9c4a-4398dc460a93', 'vocabulary', 'grade_3', 'foundation', 'multiple_choice', 'Which word means the same as ''small''?', '["Tiny","Wide","Tall","Heavy"]'::jsonb, 0, '''Tiny'' is a synonym for ''small''; both carry a similar meaning.', 'AC9E3LA09', null, null, true, null, null, null, null),
