('bd87032a-2119-4bd9-8312-d0c1bed22f8a', 'life_science', 'grade_3', 'foundation', 'multiple_choice', 'What do all living things need to survive?', '["Only sunlight","Only water","Only shelter","Food, water, and air"]'::jsonb, 3, 'Living things need food, water, and air to survive and grow.', 'AC9S3U01', null, null, true, null, null, null, null),
