('4d07eec0-dba8-4807-9da0-1829decb6cd3', 'life_science', 'grade_4', 'foundation', 'multiple_choice', 'What is the first stage of a butterfly''s life cycle?', '["Egg","Caterpillar","Chrysalis","Adult butterfly"]'::jsonb, 0, 'A butterfly''s life cycle begins as an egg, then caterpillar, chrysalis, and finally adult.', 'AC9S4U02', null, null, true, null, null, null, null),
('540f251a-a7fb-4da4-972a-1a23a376e6a3', 'life_science', 'grade_4', 'developing', 'multiple_choice', 'An animal''s natural home and surroundings are called its:', '["Species","Predator","Diet","Habitat"]'::jsonb, 3, 'A habitat is the natural environment where an animal lives and finds what it needs to survive.', 'AC9S4U02', null, null, true, null, null, null, null),
('0e5d077c-9a7b-4428-8cad-0cad99342c9e', 'life_science', 'grade_4', 'developing', 'multiple_choice', 'Animals with a backbone are called:', '["Mammals","Amphibians","Vertebrates","Invertebrates"]'::jsonb, 2, 'Vertebrates are animals that have a backbone, such as fish, birds, and mammals.', 'AC9S4U02', null, null, true, null, null, null, null),
('be4a6bdf-c30b-4c64-899f-1b932858ef2b', 'life_science', 'grade_5', 'developing', 'multiple_choice', 'What is the process called when pollen moves from one flower to another, helping plants reproduce?', '["Respiration","Pollination","Germination","Photosynthesis"]'::jsonb, 1, 'Pollination is the transfer of pollen between flowers, which allows plants to produce seeds.', 'AC9S5U01', null, null, true, null, null, null, null),
('7de1f0b5-e8b1-4eaa-abc1-3caa76f5045a', 'life_science', 'grade_5', 'developing', 'multiple_choice', 'In a food chain, what do we call an animal that eats other animals?', '["Consumer","Producer","Decomposer","Photosynthesiser"]'::jsonb, 0, 'Consumers are organisms that eat other organisms to get energy, unlike producers, which make their own food.', 'AC9S5U01', null, null, true, null, null, null, null),
('64e3c69b-3f63-4b40-bebd-34488fe25a0d', 'life_science', 'grade_5', 'proficient', 'multiple_choice', 'What role do decomposers play in an ecosystem?', '["They produce their own food from sunlight","They hunt other animals for food","They only live in water","They break down dead plants and animals"]'::jsonb, 3, 'Decomposers, like fungi and bacteria, break down dead organisms and recycle nutrients back into the ecosystem.', 'AC9S5U01', null, null, true, null, null, null, null),
('90416ab9-5e63-4b2b-bc46-d71d4dd1f2a8', 'life_science', 'grade_6', 'developing', 'multiple_choice', 'What is the basic unit of life that makes up all living things?', '["Organ","Atom","Cell","Tissue"]'::jsonb, 2, 'The cell is the smallest basic unit of structure and function in all living organisms.', 'AC9S6U02', null, null, true, null, null, null, null),
