('06148d85-95f5-46c1-8bcc-bf0a878a9346', 'life_science', 'year_9', 'proficient', 'multiple_choice', 'A community of living organisms interacting with their non-living environment is called a:', '["A habitat only","An ecosystem","A population","A species"]'::jsonb, 1, 'An ecosystem includes all living organisms in an area, along with the non-living parts of their environment, like water and soil.', 'AC9S9U03', null, null, true, null, null, null, null),
('6f519d8e-2989-447a-a806-94cb2189dac8', 'life_science', 'year_10', 'developing', 'multiple_choice', 'What is the term for an organism''s complete set of genetic material?', '["Genotype only","Genome","Phenotype","Chromosome"]'::jsonb, 1, 'The genome is the complete set of genetic material, or DNA, found in an organism.', 'AC9S10U01', null, null, true, null, null, null, null),
('69e15a87-caf3-4abf-b42c-79428dda33ed', 'life_science', 'year_10', 'proficient', 'multiple_choice', 'Selective breeding is best described as:', '["Random mating between any organisms","Choosing organisms with desired traits to breed together","Genetically modifying DNA directly","Cloning an organism exactly"]'::jsonb, 1, 'Selective breeding involves choosing parent organisms with desirable traits, over generations, to produce offspring with those traits.', 'AC9S10U01', null, null, true, null, null, null, null),
('d2188057-80d6-4a36-b71d-c14a8cb34619', 'physical_science', 'grade_3', 'foundation', 'multiple_choice', 'Which of these is a solid?', '["Air","Steam","A rock","Water"]'::jsonb, 2, 'A rock keeps its own shape and does not flow, which makes it a solid.', 'AC9S3U03', null, null, true, null, null, null, null),
('a3c33f6b-62a0-4c9a-b60a-142f65f87ad9', 'physical_science', 'grade_3', 'developing', 'multiple_choice', 'What happens when two magnets have opposite poles facing each other?', '["They attract (pull together)","They both become non-magnetic","They repel (push apart)","Nothing happens"]'::jsonb, 0, 'Opposite magnetic poles (north and south) attract each other, while like poles repel.', 'AC9S3U03', null, null, true, null, null, null, null),
('2a257334-197b-4b2f-9c94-dcc95344a84c', 'physical_science', 'grade_3', 'developing', 'multiple_choice', 'A push or a pull on an object is called a:', '["Mass","Energy source","Material","Force"]'::jsonb, 3, 'A force is a push or a pull that can change an object''s motion or shape.', 'AC9S3U03', null, null, true, null, null, null, null),
('e1537fee-6551-4a53-8b51-48b3c07db65b', 'physical_science', 'grade_4', 'developing', 'multiple_choice', 'What is needed for sound to travel from one place to another?', '["A medium, such as air or water, to vibrate through","Complete silence","Darkness","A magnet"]'::jsonb, 0, 'Sound travels as vibrations through a medium like air, water, or solids; it cannot travel through a vacuum.', 'AC9S4U01', null, null, true, null, null, null, null),
('516f74df-0e2c-4a3d-a2f7-491482a76075', 'physical_science', 'grade_4', 'developing', 'multiple_choice', 'What causes a shadow to form?', '["An object being heavy","An object being magnetic","An object making sound","An object blocking light"]'::jsonb, 3, 'A shadow forms when an object blocks light from reaching a surface behind it.', 'AC9S4U01', null, null, true, null, null, null, null),
('f285d11d-fdea-4178-b623-162113760bc9', 'physical_science', 'grade_5', 'developing', 'multiple_choice', 'A simple machine that uses a rope over a wheel to lift objects is called a:', '["Screw","Lever","Pulley","Wedge"]'::jsonb, 2, 'A pulley uses a wheel and rope to change the direction of a force, making it easier to lift objects.', 'AC9S5U03', null, null, true, null, null, null, null),
('aafd55a4-fb09-4404-a213-541d1ce1d360', 'physical_science', 'grade_5', 'developing', 'multiple_choice', 'Heat moving through a solid material, such as a metal spoon in hot soup, is called:', '["Conduction","Convection","Radiation","Evaporation"]'::jsonb, 0, 'Conduction is the transfer of heat through direct contact within a solid material.', 'AC9S5U03', null, null, true, null, null, null, null),
('81b17d0e-ebba-49bb-86a9-59d06f8cb4aa', 'physical_science', 'grade_5', 'proficient', 'multiple_choice', 'What is needed to make a simple electric circuit work?', '["A magnet only","Sunlight only","A gap in the wire","A closed, unbroken loop for current to flow"]'::jsonb, 3, 'An electric circuit needs a complete, unbroken loop for electric current to flow through it.', 'AC9S5U03', null, null, true, null, null, null, null),
('4af16baf-7024-4f17-8028-f6d77f8d5e43', 'physical_science', 'grade_6', 'developing', 'multiple_choice', 'Which of these is a form of energy stored due to an object''s position, such as a ball held high?', '["Potential energy","Sound energy","Chemical energy","Kinetic energy"]'::jsonb, 0, 'Potential energy is stored energy based on an object''s position, such as height above the ground.', 'AC9S6U01', null, null, true, null, null, null, null),
('43265bbe-19e9-4c0a-aa8e-48ad4b778295', 'physical_science', 'grade_6', 'developing', 'multiple_choice', 'What is the energy of movement called?', '["Nuclear energy","Potential energy","Thermal energy","Kinetic energy"]'::jsonb, 3, 'Kinetic energy is the energy an object has because it is moving.', 'AC9S6U01', null, null, true, null, null, null, null),
('a66279c6-c848-40e0-abc5-ed8825b64a38', 'physical_science', 'grade_6', 'proficient', 'multiple_choice', 'A higher-pitched sound generally has a:', '["Lower frequency","Higher frequency","Louder volume","Longer wavelength only"]'::jsonb, 1, 'Pitch is related to frequency: higher frequency vibrations produce higher-pitched sounds.', 'AC9S6U01', null, null, true, null, null, null, null),
('43a9e33d-9bc6-4225-9f0a-e53f2d98f407', 'physical_science', 'year_7', 'developing', 'multiple_choice', 'When water changes from a liquid to a gas, this process is called:', '["Evaporation","Condensation","Freezing","Melting"]'::jsonb, 0, 'Evaporation is the change of state from liquid to gas, usually caused by heating.', 'AC9S7U01', null, null, true, null, null, null, null),
('34548b0f-1ceb-46d0-af4a-d7be95b21631', 'physical_science', 'year_7', 'developing', 'multiple_choice', 'Density is best described as:', '["Volume of an object only","Temperature of a substance","Weight of an object only","Mass per unit of volume"]'::jsonb, 3, 'Density measures how much mass is packed into a given volume of a substance.', 'AC9S7U01', null, null, true, null, null, null, null),
('37d5ba84-b1b0-49de-b88e-3c6483a406b2', 'physical_science', 'year_7', 'proficient', 'multiple_choice', 'In a series circuit, if one globe burns out, what happens to the rest of the circuit?', '["Nothing changes","All the globes turn off","Only that globe turns off, the rest stay on","The circuit gets brighter"]'::jsonb, 1, 'In a series circuit there is only one path for current, so a break anywhere stops current everywhere in the loop.', 'AC9S7U01', null, null, true, null, null, null, null),
('909dd0e9-4828-487e-a54b-8ec7a5d54dc1', 'physical_science', 'year_8', 'developing', 'multiple_choice', 'According to Newton''s first law, an object at rest will stay at rest unless:', '["Acted on by an unbalanced force","It is very heavy","It is made of metal","It is left alone for a long time"]'::jsonb, 0, 'Newton''s first law states that an object remains at rest, or in uniform motion, unless acted on by an unbalanced force.', 'AC9S8U01', null, null, true, null, null, null, null),
('dfbeb1bd-0e2c-402b-b1ce-861fd91e9b1b', 'physical_science', 'year_8', 'developing', 'multiple_choice', 'Sound waves and water waves are both examples of which type of wave, since they need a medium to travel through?', '["Electromagnetic waves","Light waves","Radio waves","Mechanical waves"]'::jsonb, 3, 'Mechanical waves, like sound and water waves, require a medium (such as air or water) to travel through.', 'AC9S8U01', null, null, true, null, null, null, null),
('5f48e025-4c14-42e8-89b5-aaed3be746ab', 'physical_science', 'year_8', 'proficient', 'multiple_choice', 'What is the process called when a substance changes state without a chemical reaction occurring, such as ice melting?', '["A nuclear reaction","Combustion","A physical change","A chemical change"]'::jsonb, 2, 'A physical change, like melting or freezing, alters a substance''s state without changing its chemical makeup.', 'AC9S8U01', null, null, true, null, null, null, null),
('a00cf390-03e0-4aac-b21d-710de91af173', 'physical_science', 'year_9', 'developing', 'multiple_choice', 'What is the formula for calculating average speed?', '["Distance + time","Distance × time","Distance ÷ time","Time ÷ distance"]'::jsonb, 2, 'Average speed is calculated as the distance travelled divided by the time taken.', 'AC9S9U01', null, null, true, null, null, null, null),
('8a7bb997-6650-4ac7-b1b4-22fe56eadaf7', 'physical_science', 'year_9', 'developing', 'multiple_choice', 'According to the law of conservation of energy, energy can:', '["Not be created or destroyed, only transformed","Be created but not destroyed","Be destroyed but not created","Only exist as heat"]'::jsonb, 0, 'The law of conservation of energy states that energy cannot be created or destroyed, only transformed from one form to another.', 'AC9S9U01', null, null, true, null, null, null, null),
('bf7ae28f-322b-459e-a179-dcda96748857', 'physical_science', 'year_9', 'proficient', 'multiple_choice', 'Rusting of iron is an example of a:', '["Physical change","Change of state","Nuclear change","Chemical change"]'::jsonb, 3, 'Rusting involves a chemical reaction between iron, oxygen, and water, forming a new substance (iron oxide).', 'AC9S9U01', null, null, true, null, null, null, null),
('a8fb4908-f37c-4d12-ab5b-19a39cc5a542', 'physical_science', 'year_10', 'developing', 'multiple_choice', 'What unit is used to measure electrical resistance?', '["Ohm","Watt","Ampere","Volt"]'::jsonb, 0, 'Electrical resistance is measured in ohms, symbol Ω.', 'AC9S10U03', null, null, true, null, null, null, null),
('38b503b8-fa93-4962-8eca-f38417780e67', 'physical_science', 'year_10', 'developing', 'multiple_choice', 'The number of wave crests passing a point each second is called the wave''s:', '["Speed","Amplitude","Wavelength","Frequency"]'::jsonb, 3, 'Frequency measures how many complete waves pass a point per second, measured in hertz (Hz).', 'AC9S10U03', null, null, true, null, null, null, null),
('6de0e8f2-1778-4048-b023-ea41fe126300', 'physical_science', 'year_10', 'proficient', 'multiple_choice', 'What is the relationship between voltage, current, and resistance, according to Ohm''s law?', '["Voltage = current ÷ resistance","Voltage = current × resistance","Voltage = current + resistance","Voltage = resistance ÷ current"]'::jsonb, 1, 'Ohm''s law states V = I × R, where V is voltage, I is current, and R is resistance.', 'AC9S10U03', null, null, true, null, null, null, null),
('edb4d129-3d00-4472-a241-56443bf94ba2', 'physical_science', 'grade_3', 'developing', 'multiple_choice', 'Which of these is a liquid?', '["A rock","Milk","Air","A block of wood"]'::jsonb, 1, 'Milk flows and takes the shape of its container, which makes it a liquid.', 'AC9S3U03', null, null, true, null, null, null, null),
('8c40cd49-1fe5-48f0-a28d-b4e5b19ac88f', 'physical_science', 'grade_3', 'foundation', 'multiple_choice', 'What is it called when an object is pulled toward the Earth?', '["Magnetism","Gravity","Electricity","Friction"]'::jsonb, 1, 'Gravity is the force that pulls objects toward the Earth.', 'AC9S3U03', null, null, true, null, null, null, null),
('959eb318-91f4-4a63-9915-ce32b628024f', 'physical_science', 'grade_4', 'developing', 'multiple_choice', 'Which of these materials is a good conductor of electricity?', '["Wood","Copper","Rubber","Plastic"]'::jsonb, 1, 'Copper is a metal, and metals are generally good conductors of electricity.', 'AC9S4U01', null, null, true, null, null, null, null),
('a2808b56-6156-42f2-91e0-3e83609ad71c', 'physical_science', 'grade_4', 'developing', 'multiple_choice', 'What happens to most materials when they are heated?', '["They always shrink","They expand","They become magnetic","They disappear"]'::jsonb, 1, 'Most materials expand slightly when heated, as their particles move faster and spread apart.', 'AC9S4U01', null, null, true, null, null, null, null),
('277455a3-4ac3-4b36-9818-1ebffbfaea19', 'physical_science', 'grade_5', 'developing', 'multiple_choice', 'Which simple machine is a ramp that makes it easier to move objects to a higher place?', '["Lever","Inclined plane","Wheel and axle","Pulley"]'::jsonb, 1, 'An inclined plane, or ramp, reduces the force needed to raise an object by spreading the work over a longer distance.', 'AC9S5U03', null, null, true, null, null, null, null),
('d4d288c0-6575-470b-9e0b-16f7ea04dcbb', 'physical_science', 'grade_5', 'proficient', 'multiple_choice', 'What is the transfer of heat through empty space, such as heat from the sun, called?', '["Convection","Radiation","Insulation","Conduction"]'::jsonb, 1, 'Radiation transfers heat as electromagnetic waves and can travel through empty space, unlike conduction or convection.', 'AC9S5U03', null, null, true, null, null, null, null),
('a9fe29a8-16cc-48d8-b572-54bac049c42d', 'physical_science', 'grade_6', 'developing', 'multiple_choice', 'Which of these is an example of stored chemical energy?', '["A stretched rubber band","A battery","A moving car","Sunlight"]'::jsonb, 1, 'A battery stores energy in chemical form, which is converted to electrical energy when used.', 'AC9S6U01', null, null, true, null, null, null, null),
('a41fe943-bd18-448b-96f8-673807a07814', 'physical_science', 'grade_6', 'developing', 'multiple_choice', 'What happens to the pitch of a sound as the frequency of vibration decreases?', '["The pitch gets higher","The pitch stays the same","The sound becomes silent","The pitch gets lower"]'::jsonb, 3, 'Lower frequency vibrations produce a lower-pitched sound.', 'AC9S6U01', null, null, true, null, null, null, null),
('3fcb0332-ed03-4968-a37c-15c313ebfda1', 'physical_science', 'year_7', 'developing', 'multiple_choice', 'Which state of matter has a definite shape and volume?', '["Liquid","Solid","Gas","Plasma"]'::jsonb, 1, 'A solid keeps both its shape and volume, unlike liquids and gases.', 'AC9S7U01', null, null, true, null, null, null, null),
('64403791-d6de-4978-bd47-6e5c4419b935', 'physical_science', 'year_7', 'proficient', 'multiple_choice', 'In a parallel circuit, if one globe burns out, what happens to the other globes?', '["They get dimmer and turn off","The circuit stops working entirely","They all turn off","They stay on"]'::jsonb, 3, 'In a parallel circuit, each globe has its own separate path, so the others keep working if one fails.', 'AC9S7U01', null, null, true, null, null, null, null),
('dbade988-155b-4c69-88ed-e54e37faf6ca', 'physical_science', 'year_8', 'developing', 'multiple_choice', 'Which of Newton''s laws states that for every action there is an equal and opposite reaction?', '["The law of gravity","The third law","The first law","The second law"]'::jsonb, 1, 'Newton''s third law states that every action force has an equal and opposite reaction force.', 'AC9S8U01', null, null, true, null, null, null, null),
('971fde25-bc5c-4406-92f1-864f18465d7b', 'physical_science', 'year_8', 'proficient', 'multiple_choice', 'What type of wave requires no medium and can travel through the vacuum of space?', '["Electromagnetic wave","Sound wave","Water wave","Seismic wave"]'::jsonb, 0, 'Electromagnetic waves, like light, can travel through the vacuum of space without needing a medium.', 'AC9S8U01', null, null, true, null, null, null, null),
('5522aa73-cdbe-4be7-91c0-68ef6b63b563', 'physical_science', 'year_9', 'developing', 'multiple_choice', 'Freezing water into ice is an example of a:', '["Chemical change","Physical change","Nuclear change","Combustion reaction"]'::jsonb, 1, 'Freezing changes water''s state without forming a new substance, making it a physical change.', 'AC9S9U01', null, null, true, null, null, null, null),
('8f9593bb-1192-4729-b332-2cde6ae433fb', 'physical_science', 'year_9', 'proficient', 'multiple_choice', 'If a car travels 150 km in 3 hours, what is its average speed?', '["50 m/s","50 km/h","3 km/h","450 km/h"]'::jsonb, 1, 'Average speed = distance ÷ time = 150 km ÷ 3 h = 50 km/h.', 'AC9S9U01', null, null, true, null, null, null, null),
('9f679146-255a-419f-a8b7-35a0ea856654', 'physical_science', 'year_10', 'developing', 'multiple_choice', 'What is the SI unit used to measure electric current?', '["Watt","Ampere","Volt","Ohm"]'::jsonb, 1, 'Electric current is measured in amperes (amps), symbol A.', 'AC9S10U03', null, null, true, null, null, null, null),
('1826d930-a611-4415-89da-1a8f78b3d561', 'physical_science', 'year_10', 'proficient', 'multiple_choice', 'A wave with a short wavelength has a:', '["Low frequency","Low speed only","No energy","High frequency"]'::jsonb, 3, 'Wavelength and frequency are inversely related for waves travelling at the same speed, so a short wavelength means a high frequency.', 'AC9S10U03', null, null, true, null, null, null, null),
('03431a77-0f9e-4291-9f77-fdeafb4055f9', 'earth_space', 'grade_3', 'developing', 'multiple_choice', 'What are the four seasons, in order, starting from summer?', '["Winter, spring, summer, autumn","Spring, summer, autumn, winter","Autumn, winter, spring, summer","Summer, autumn, winter, spring"]'::jsonb, 3, 'Starting from summer, the seasons follow the order: summer, autumn, winter, spring.', 'AC9S3U02', null, null, true, null, null, null, null),
('93b93e73-e0ea-42a4-95df-d42b43c227d2', 'earth_space', 'grade_3', 'foundation', 'multiple_choice', 'What is the difference between weather and climate?', '["Climate changes daily; weather does not","Weather only happens in winter","Weather is day-to-day conditions; climate is the pattern over many years","Weather and climate mean exactly the same thing"]'::jsonb, 2, 'Weather describes short-term daily conditions, while climate describes long-term average weather patterns in a region.', 'AC9S3U02', null, null, true, null, null, null, null),
('8787955e-c833-4dc6-9396-740220634954', 'earth_space', 'grade_4', 'developing', 'multiple_choice', 'Which type of rock is formed from layers of sediment pressed together over time?', '["Volcanic rock","Sedimentary rock","Igneous rock","Metamorphic rock"]'::jsonb, 1, 'Sedimentary rock forms when layers of sediment, like sand or mud, are compressed together over long periods.', 'AC9S4U03', null, null, true, null, null, null, null),
('c16e18dc-53e6-4149-9af7-2d4890fa4a80', 'earth_space', 'grade_4', 'developing', 'multiple_choice', 'What is the continuous movement of water between the sky, land, and oceans called?', '["The water cycle","The rock cycle","The carbon cycle","The food cycle"]'::jsonb, 0, 'The water cycle describes how water evaporates, condenses into clouds, and falls as precipitation, again and again.', 'AC9S4U03', null, null, true, null, null, null, null),
('673a1ef3-1191-4d49-a14d-59533db7a825', 'earth_space', 'grade_5', 'developing', 'multiple_choice', 'Which planet is known as the "Red Planet"?', '["Venus","Jupiter","Mercury","Mars"]'::jsonb, 3, 'Mars appears red due to iron oxide (rust) on its surface, earning it the nickname "the Red Planet".', 'AC9S5U02', null, null, true, null, null, null, null),
('4beff8bd-1407-45df-964c-3e21327980f2', 'earth_space', 'grade_5', 'developing', 'multiple_choice', 'Put these planets in order from closest to the Sun: Earth, Mercury, Venus.', '["Venus, Mercury, Earth","Mercury, Earth, Venus","Mercury, Venus, Earth","Earth, Venus, Mercury"]'::jsonb, 2, 'The order of the closest planets to the Sun is Mercury, then Venus, then Earth.', 'AC9S5U02', null, null, true, null, null, null, null),
('0d12466d-92ce-49d8-8b9f-0f5a8c689f10', 'earth_space', 'grade_6', 'developing', 'multiple_choice', 'The gradual wearing away of rock and soil by wind, water, or ice is called:', '["Erosion","Combustion","Evaporation","Condensation"]'::jsonb, 0, 'Erosion is the process by which wind, water, or ice gradually wear away and move rock and soil.', 'AC9S6U03', null, null, true, null, null, null, null),
('1ca087db-5e18-43fe-8712-99c191ccbfd3', 'earth_space', 'grade_6', 'developing', 'multiple_choice', 'Which of these is a renewable energy resource?', '["Coal","Natural gas","Oil","Solar power"]'::jsonb, 3, 'Solar power comes from the sun, a resource that naturally replenishes and will not run out, unlike fossil fuels.', 'AC9S6U03', null, null, true, null, null, null, null),
('793f6542-4f26-4ed5-adc6-df887b2fbcd1', 'earth_space', 'year_7', 'developing', 'multiple_choice', 'The continuous process by which rocks are formed, broken down, and reformed over millions of years is called the:', '["Water cycle","Carbon cycle","Nitrogen cycle","Rock cycle"]'::jsonb, 3, 'The rock cycle describes how igneous, sedimentary, and metamorphic rocks transform into one another over geological time.', 'AC9S7U02', null, null, true, null, null, null, null),
('cdb4a7f2-76d9-4eae-a60f-05c1eeebcaf3', 'earth_space', 'year_7', 'developing', 'multiple_choice', 'A fossil is most likely to form when an organism is:', '["Burned in a fire","Frozen only briefly","Buried quickly in sediment after death","Left exposed to air for a long time"]'::jsonb, 2, 'Fossils typically form when an organism is buried quickly in sediment, protecting it from decay while it mineralises over time.', 'AC9S7U02', null, null, true, null, null, null, null),
('7feb0878-7350-4c28-8663-5297fac0d6a2', 'earth_space', 'year_8', 'developing', 'multiple_choice', 'Volcanic eruptions and earthquakes most commonly occur along:', '["Areas with no rock layers","Tectonic plate boundaries","The centre of continents only","The equator only"]'::jsonb, 1, 'Most volcanic and earthquake activity occurs where tectonic plates meet, due to the movement and pressure at these boundaries.', 'AC9S8U02', null, null, true, null, null, null, null),
('6a9c251d-f7a0-4373-9a05-3dc6a5213439', 'earth_space', 'year_8', 'developing', 'multiple_choice', 'Which layer of the atmosphere is closest to Earth''s surface, where weather occurs?', '["Troposphere","Stratosphere","Mesosphere","Thermosphere"]'::jsonb, 0, 'The troposphere is the lowest layer of the atmosphere, where almost all weather takes place.', 'AC9S8U02', null, null, true, null, null, null, null),
('2e29ec3d-4463-4367-a993-cefb6ebddc1d', 'earth_space', 'year_9', 'developing', 'multiple_choice', 'The natural process by which gases trap heat in Earth''s atmosphere is called the:', '["Water cycle","Rock cycle","Carbon capture","Greenhouse effect"]'::jsonb, 3, 'The greenhouse effect occurs when gases like carbon dioxide trap heat from the sun in the atmosphere, warming the planet.', 'AC9S9U04', null, null, true, null, null, null, null),
('aed732ac-94ce-4597-ae8f-3bf5969da433', 'earth_space', 'year_9', 'proficient', 'multiple_choice', 'A resource that can be replenished naturally within a human lifetime, such as wind or timber, is called:', '["A fossil fuel","A mineral resource only","A renewable resource","A non-renewable resource"]'::jsonb, 2, 'Renewable resources, like wind and timber, can be naturally replenished within a relatively short time.', 'AC9S9U04', null, null, true, null, null, null, null),
('e311c7e4-79b4-4227-af8b-dce8925952dc', 'earth_space', 'year_10', 'developing', 'multiple_choice', 'The Earth is estimated to be approximately how old?', '["100 million years","4.5 billion years","4.5 million years","10,000 years"]'::jsonb, 1, 'Scientific evidence, including radiometric dating, estimates Earth''s age at approximately 4.5 billion years.', 'AC9S10U02', null, null, true, null, null, null, null),
('6b39fe15-ae4e-45ac-a8e4-69323992403b', 'earth_space', 'year_10', 'proficient', 'multiple_choice', 'A sudden, violent shaking of the ground caused by the movement of tectonic plates is called a:', '["Earthquake","Tsunami","Landslide","Volcano"]'::jsonb, 0, 'An earthquake is caused by the sudden release of energy as tectonic plates shift, causing the ground to shake.', 'AC9S10U02', null, null, true, null, null, null, null),
('81f0d130-14f5-44c4-8482-421d2be96cbf', 'earth_space', 'year_10', 'developing', 'multiple_choice', 'Which of these is considered a renewable source of electricity generation?', '["Coal-fired power stations","Natural gas plants","Oil-fired power stations","Wind turbines"]'::jsonb, 3, 'Wind turbines generate electricity from wind, a naturally replenishing resource, unlike fossil fuels.', 'AC9S10U02', null, null, true, null, null, null, null),
('e4097d3e-fb18-42f1-9b01-eff03e271b19', 'earth_space', 'grade_3', 'developing', 'multiple_choice', 'What causes the different phases of the Moon that we see from Earth?', '["Clouds covering the Moon","The Moon moving closer and farther from Earth","The changing amount of sunlit Moon visible from Earth as it orbits","The Moon changing shape"]'::jsonb, 2, 'As the Moon orbits Earth, we see different amounts of its sunlit half, creating the phases we observe.', 'AC9S3U02', null, null, true, null, null, null, null),
('75a2addb-9ebe-4b17-8e91-3d25a3bc88ff', 'earth_space', 'grade_4', 'developing', 'multiple_choice', 'Which of these is a source of fresh water?', '["Sea water","A river","The ocean","A salt lake"]'::jsonb, 1, 'Rivers are a common source of fresh water, unlike oceans and salt lakes, which contain salt water.', 'AC9S4U03', null, null, true, null, null, null, null),
('a25d74d4-cece-4b6b-a48c-e6f14137f07c', 'earth_space', 'grade_4', 'foundation', 'multiple_choice', 'What is the star at the centre of our solar system called?', '["The Sun","The Moon","Earth","Mars"]'::jsonb, 0, 'The Sun is the star at the centre of our solar system, and all the planets orbit around it.', 'AC9S4U03', null, null, true, null, null, null, null),
('40488c0d-1663-4350-a322-97d5c6bc197e', 'earth_space', 'grade_5', 'developing', 'multiple_choice', 'Which of these best describes the shape of Earth''s orbit around the Sun?', '["A perfect square","A straight line","A perfect triangle","An ellipse (a slightly stretched circle)"]'::jsonb, 3, 'Earth orbits the Sun in a slightly elongated circle known as an ellipse.', 'AC9S5U02', null, null, true, null, null, null, null),
('fbd0c82a-fed7-4658-961c-e2da033f2a6d', 'earth_space', 'grade_6', 'developing', 'multiple_choice', 'Which of these is an example of a non-renewable resource?', '["Wind","Coal","Timber from a managed forest","Solar energy"]'::jsonb, 1, 'Coal takes millions of years to form and cannot be replenished within a human lifetime, making it non-renewable.', 'AC9S6U03', null, null, true, null, null, null, null),
('bac08012-8cfa-4d1e-98f0-dc143bb9f6d2', 'earth_space', 'grade_6', 'proficient', 'multiple_choice', 'What is the layer of the Earth that we live on, made of solid rock, called?', '["The inner core","The crust","The mantle","The outer core"]'::jsonb, 1, 'The crust is the thin, solid outer layer of the Earth where we live.', 'AC9S6U03', null, null, true, null, null, null, null),
('46ef8104-e8cb-4306-b347-3c7be356109d', 'earth_space', 'year_7', 'developing', 'multiple_choice', 'Which type of rock forms when heat and pressure change an existing rock, without it melting?', '["Metamorphic rock","Igneous rock","Sedimentary rock","Volcanic rock"]'::jsonb, 0, 'Metamorphic rock forms when existing rock is changed by intense heat and pressure, without fully melting.', 'AC9S7U02', null, null, true, null, null, null, null),
('4d66b7b7-d370-410a-b0fd-427ca9a423b1', 'earth_space', 'year_8', 'developing', 'multiple_choice', 'Which layer of the atmosphere contains the ozone layer that absorbs harmful UV radiation?', '["Troposphere","Mesosphere","Exosphere","Stratosphere"]'::jsonb, 3, 'The ozone layer, which absorbs most of the sun''s harmful UV radiation, is located in the stratosphere.', 'AC9S8U02', null, null, true, null, null, null, null),
('14e20853-9c3f-48cc-90e3-cfedaa366d27', 'earth_space', 'year_9', 'developing', 'multiple_choice', 'Which human activity most contributes to an increase in atmospheric carbon dioxide?', '["Recycling paper","Using solar panels","Burning fossil fuels","Planting trees"]'::jsonb, 2, 'Burning fossil fuels, such as coal and oil, releases large amounts of carbon dioxide into the atmosphere.', 'AC9S9U04', null, null, true, null, null, null, null),
('e0f81a76-aa5e-4c87-90de-947d080b0fb5', 'earth_space', 'year_10', 'developing', 'multiple_choice', 'A large-scale wave, often caused by an underwater earthquake, is called a:', '["Drought","Tsunami","Hurricane","Blizzard"]'::jsonb, 1, 'A tsunami is a large ocean wave, most commonly triggered by an underwater earthquake or volcanic eruption.', 'AC9S10U02', null, null, true, null, null, null, null),
('148a2ead-f194-4f6b-9bd6-5cc9d82a08b2', 'chem_atomic_structure', 'year_11', 'foundation', 'multiple_choice', 'How many electrons can the second electron shell (n = 2) hold at maximum?', '["2","18","6","8"]'::jsonb, 3, 'The second shell (n = 2) holds a maximum of 8 electrons (2n² = 2×2² = 8).', null, null, null, true, null, null, null, null),
('13847855-2d4f-4490-b87d-26fcbb47be5f', 'chem_atomic_structure', 'year_11', 'developing', 'multiple_choice', 'An atom of carbon has atomic number 6. How many protons does it have?', '["8","14","6","12"]'::jsonb, 2, 'The atomic number equals the number of protons, so carbon has 6 protons.', null, null, null, true, null, null, null, null),
('a92eede6-c83d-4e2b-9332-da81f7464b43', 'chem_atomic_structure', 'year_11', 'developing', 'multiple_choice', 'What is the term for atoms of the same element with different numbers of neutrons?', '["Isotopes","Molecules","Ions","Isomers"]'::jsonb, 0, 'Isotopes are atoms of the same element (same protons) with a different number of neutrons.', null, null, null, true, null, null, null, null),
('ec2e421f-7d5d-440a-8388-dd0d7a13c772', 'chem_atomic_structure', 'year_11', 'developing', 'multiple_choice', 'What charge does a neutron carry?', '["Positive charge","Negative charge","Variable charge","No charge (neutral)"]'::jsonb, 3, 'A neutron has no electric charge, unlike protons (positive) and electrons (negative).', null, null, null, true, null, null, null, null),
('d8c1ef5c-5ec7-4685-963a-697e60a7a0be', 'chem_atomic_structure', 'year_11', 'proficient', 'multiple_choice', 'An atom that has lost an electron becomes a:', '["Negative ion (anion)","Positive ion (cation)","Neutral atom","Isotope"]'::jsonb, 1, 'Losing a negatively charged electron leaves the atom with a net positive charge, forming a cation.', null, null, null, true, null, null, null, null),
('b53694b4-19e3-4392-801f-716046d4746a', 'chem_atomic_structure', 'year_11', 'developing', 'multiple_choice', 'Elements in the same column (group) of the periodic table generally have the same number of:', '["Protons","Valence (outer shell) electrons","Total electron shells","Neutrons"]'::jsonb, 1, 'Elements in the same group share the same number of valence electrons, giving them similar chemical properties.', null, null, null, true, null, null, null, null),
('e1d34880-ea89-4a48-a8e6-e2963f88e52a', 'chem_reactions', 'year_11', 'developing', 'multiple_choice', 'What type of reaction releases heat energy to the surroundings?', '["Exothermic reaction","Reduction reaction only","Endothermic reaction","Neutral reaction"]'::jsonb, 0, 'An exothermic reaction releases energy, usually as heat, to its surroundings.', null, null, null, true, null, null, null, null),
('086fbfc9-dc42-4767-9ae6-0faed1e02d95', 'chem_reactions', 'year_11', 'developing', 'multiple_choice', 'What is produced when an acid reacts with a base?', '["Only a gas","Only a salt","Oxygen and hydrogen","A salt and water"]'::jsonb, 3, 'A neutralisation reaction between an acid and a base produces a salt and water.', null, null, null, true, null, null, null, null),
('fc7f0a6a-7046-44cd-9719-8743c94b6570', 'chem_reactions', 'year_11', 'proficient', 'multiple_choice', 'Balance the equation: __N2 + __H2 → __NH3', '["1, 2, 1","2, 3, 1","1, 3, 3","1, 3, 2"]'::jsonb, 3, 'N2 + 3H2 → 2NH3 balances nitrogen (2 atoms each side) and hydrogen (6 atoms each side).', null, null, null, true, null, null, null, null),
('8bcf73d5-f780-46c8-b6d1-97ee5d021b5f', 'chem_reactions', 'year_11', 'developing', 'multiple_choice', 'What is the correct chemical formula for water?', '["HO2","H2O","H3O","H2O2"]'::jsonb, 1, 'Water is made of two hydrogen atoms and one oxygen atom, giving the formula H2O.', null, null, null, true, null, null, null, null),
('a9bb8b8f-6e43-45a1-8134-27480896bfa5', 'chem_reactions', 'year_11', 'proficient', 'multiple_choice', 'In the reaction Zn + CuSO4 → ZnSO4 + Cu, zinc displaces copper. What type of reaction is this?', '["A decomposition reaction","A single displacement reaction","A combustion reaction","A neutralisation reaction"]'::jsonb, 1, 'Zinc, a more reactive metal, displaces copper from the compound, which is a single displacement reaction.', null, null, null, true, null, null, null, null),
('8ab671dd-8d31-4c98-9b08-81e60d6b3eb5', 'phys_mechanics', 'year_11', 'developing', 'multiple_choice', 'An object travels 20 m in 4 seconds at a constant speed. What is its speed?', '["5 m/s","7 m/s","3 m/s","10 m/s"]'::jsonb, 0, 'Speed = distance ÷ time = 20 ÷ 4 = 5 m/s.', null, null, null, true, null, null, null, null),
('0c58d296-9287-47ac-8c91-aa056cfb45b3', 'phys_mechanics', 'year_11', 'developing', 'multiple_choice', 'An object travels 30 m in 5 seconds at a constant speed. What is its speed?', '["8 m/s","4 m/s","12 m/s","6 m/s"]'::jsonb, 3, 'Speed = distance ÷ time = 30 ÷ 5 = 6 m/s.', null, null, null, true, null, null, null, null),
('4da5641b-f95a-4cbf-b291-691fc6dd8b6c', 'phys_mechanics', 'year_11', 'developing', 'multiple_choice', 'An object travels 15 m in 3 seconds at a constant speed. What is its speed?', '["3 m/s","10 m/s","5 m/s","7 m/s"]'::jsonb, 2, 'Speed = distance ÷ time = 15 ÷ 3 = 5 m/s.', null, null, null, true, null, null, null, null),
('67bd79ea-d1f4-4e36-b3f0-b460773f5a5c', 'phys_mechanics', 'year_11', 'developing', 'multiple_choice', 'Using F = ma, what is the force on an object with mass 5 kg accelerating at 3 m/s²?', '["8 N","15 N","20 N","12 N"]'::jsonb, 1, 'F = m × a = 5 × 3 = 15 N.', null, null, null, true, null, null, null, null),
('ab8ee86c-9db0-40ab-a18a-a690d757a16c', 'phys_mechanics', 'year_11', 'developing', 'multiple_choice', 'Using F = ma, what is the force on an object with mass 10 kg accelerating at 2 m/s²?', '["20 N","30 N","18 N","12 N"]'::jsonb, 0, 'F = m × a = 10 × 2 = 20 N.', null, null, null, true, null, null, null, null),
('8235976f-ed56-4801-9f47-565b3e4d14d3', 'phys_mechanics', 'year_11', 'developing', 'multiple_choice', 'Using F = ma, what is the force on an object with mass 4 kg accelerating at 6 m/s²?', '["28 N","18 N","10 N","24 N"]'::jsonb, 3, 'F = m × a = 4 × 6 = 24 N.', null, null, null, true, null, null, null, null),
('cbca9365-056c-4a3b-9052-35c732aa4cd1', 'phys_mechanics', 'year_11', 'foundation', 'multiple_choice', 'What quantity measures how fast an object''s velocity is changing?', '["Displacement","Momentum","Acceleration","Speed"]'::jsonb, 2, 'Acceleration measures the rate of change of velocity over time.', null, null, null, true, null, null, null, null),
('ff0469a5-bbfe-4e11-822f-d5bf750b3f29', 'phys_mechanics', 'year_11', 'proficient', 'multiple_choice', 'What is the momentum of an object with mass 4 kg moving at 5 m/s?', '["45 kg·m/s","20 kg·m/s","9 kg·m/s","1.25 kg·m/s"]'::jsonb, 1, 'Momentum = mass × velocity = 4 × 5 = 20 kg·m/s.', null, null, null, true, null, null, null, null),
('6eb6f7c9-bb6f-4d0f-9c5c-3b5a6e009842', 'phys_mechanics', 'year_11', 'proficient', 'multiple_choice', 'Using Ep = mgh with m = 1 kg, g ≈ 10 m/s², and h = 80 m, what is the gravitational potential energy?', '["800 J","810 J","720 J","400 J"]'::jsonb, 0, 'Ep = mgh = 1 × 10 × 80 = 800 J.', null, null, null, true, null, null, null, null),
('4d40d0a3-5392-45aa-ad5a-5673d389e427', 'phys_mechanics', 'year_11', 'proficient', 'multiple_choice', 'Using Ep = mgh with m = 1 kg, g ≈ 9.8 m/s², and h = 50 m, what is the gravitational potential energy?', '["500 J","440 J","245 J","490 J"]'::jsonb, 3, 'Ep = mgh = 1 × 9.8 × 50 = 490 J.', null, null, null, true, null, null, null, null),
('b9bf1e8b-c7c4-4461-affa-3f7e9567c146', 'phys_electricity', 'year_11', 'developing', 'multiple_choice', 'Using Ohm''s law, what is the current through a 4 Ω resistor with 12 V across it?', '["6 A","5 A","4 A","3 A"]'::jsonb, 3, 'I = V ÷ R = 12 ÷ 4 = 3 A.', null, null, null, true, null, null, null, null),
('d0a88c5f-f107-41bb-923c-3146b027450d', 'phys_electricity', 'year_11', 'developing', 'multiple_choice', 'Using Ohm''s law, what is the current through a 4 Ω resistor with 20 V across it?', '["4 A","5 A","6 A","10 A"]'::jsonb, 1, 'I = V ÷ R = 20 ÷ 4 = 5 A.', null, null, null, true, null, null, null, null),
('205afd4c-b25d-4c6c-99dc-73e945ada9ce', 'phys_electricity', 'year_11', 'developing', 'multiple_choice', 'Using Ohm''s law, what is the current through a 3 Ω resistor with 18 V across it?', '["7 A","6 A","12 A","3 A"]'::jsonb, 1, 'I = V ÷ R = 18 ÷ 3 = 6 A.', null, null, null, true, null, null, null, null),
('0f655e13-5eef-49d4-bd5e-a99c9658a07a', 'phys_electricity', 'year_11', 'foundation', 'multiple_choice', 'What is the unit of electrical charge?', '["Ampere","Volt","Watt","Coulomb"]'::jsonb, 3, 'Electrical charge is measured in coulombs, symbol C.', null, null, null, true, null, null, null, null),
('0d6a5df5-385e-4833-8784-818535cc176b', 'phys_electricity', 'year_11', 'developing', 'multiple_choice', 'In a series circuit, how does the total resistance relate to the individual resistances?', '["It is the sum of all the resistances","It is always less than any individual resistance","It is the difference between the resistances","It is the average of the resistances"]'::jsonb, 0, 'In a series circuit, total resistance equals the sum of each individual resistance.', null, null, null, true, null, null, null, null),
('16e04cc5-be59-4405-8ae8-d6eebda267c4', 'phys_electricity', 'year_11', 'proficient', 'multiple_choice', 'What is the power used by a device with voltage 12 V and current 2 A? (P = VI)', '["10 W","14 W","24 W","6 W"]'::jsonb, 2, 'Power = voltage × current = 12 × 2 = 24 W.', null, null, null, true, null, null, null, null),
('1bc89c1b-aaa7-4887-997e-29c0ab65973f', 'phys_electricity', 'year_11', 'developing', 'multiple_choice', 'Which material is generally the best electrical insulator?', '["Copper","Silver","Aluminium","Rubber"]'::jsonb, 3, 'Rubber does not allow electric current to flow easily through it, making it a good insulator, unlike metals.', null, null, null, true, null, null, null, null),
('d017ee6a-6aea-48f0-b97d-a441052976e6', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'Differentiate: f(x) = 4x^3 + 2x', '["f''(x) = 12x^2","f''(x) = 4x^2 + 2","f''(x) = 12x^3 + 2","f''(x) = 12x^2 + 2"]'::jsonb, 3, 'Using the power rule, d/dx(4x^3) = 12x^2, and d/dx(2x) = 2.', null, null, null, true, null, null, null, null),
('26973d1f-693b-469d-9f0e-46e7dce7676a', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'Differentiate: f(x) = 5x^2 + 3x', '["f''(x) = 5x^1 + 3","f''(x) = 10x^1 + 3","f''(x) = 10x^2 + 3","f''(x) = 10x^1"]'::jsonb, 1, 'Using the power rule, d/dx(5x^2) = 10x^1, and d/dx(3x) = 3.', null, null, null, true, null, null, null, null),
('e0f8577c-c08d-411c-9783-1a80f09313fa', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'Differentiate: f(x) = 3x^4 + 4x', '["f''(x) = 3x^3 + 4","f''(x) = 12x^3 + 4","f''(x) = 12x^4 + 4","f''(x) = 12x^3"]'::jsonb, 1, 'Using the power rule, d/dx(3x^4) = 12x^3, and d/dx(4x) = 4.', null, null, null, true, null, null, null, null),
('b1074d16-1caa-4075-bff3-38d64c5273c0', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'Differentiate: f(x) = 6x^2 + 5x', '["f''(x) = 12x^2 + 5","f''(x) = 12x^1","f''(x) = 6x^1 + 5","f''(x) = 12x^1 + 5"]'::jsonb, 3, 'Using the power rule, d/dx(6x^2) = 12x^1, and d/dx(5x) = 5.', null, null, null, true, null, null, null, null),
('ae1dca68-d197-4d15-8766-80bf59e38448', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'Differentiate: f(x) = 2x^5 + 3x', '["f''(x) = 10x^4 + 3","f''(x) = 10x^4","f''(x) = 2x^4 + 3","f''(x) = 10x^5 + 3"]'::jsonb, 0, 'Using the power rule, d/dx(2x^5) = 10x^4, and d/dx(3x) = 3.', null, null, null, true, null, null, null, null),
('0b939f58-e4c9-4c94-8234-5171b533274e', 'mm_calculus', 'year_11', 'proficient', 'multiple_choice', 'If f(x) = 3x² + 2x, what is f''(1)?', '["8","11","6","5"]'::jsonb, 0, 'f''(x) = 6x + 2. At x = 1: 6 × 1 + 2 = 8.', null, null, null, true, null, null, null, null),
('e552d368-f94c-4168-9052-e16b4d8a8da2', 'mm_calculus', 'year_11', 'proficient', 'multiple_choice', 'If f(x) = 2x² − 3x, what is f''(4)?', '["15","16","5","13"]'::jsonb, 3, 'f''(x) = 4x − 3. At x = 4: 4 × 4 − 3 = 13.', null, null, null, true, null, null, null, null),
('9d22b63a-057f-470b-b725-e50c310ebafb', 'mm_calculus', 'year_11', 'proficient', 'multiple_choice', 'If f(x) = 5x² + 4x, what is f''(−2)?', '["−20","−6","−16","−11"]'::jsonb, 2, 'f''(x) = 10x + 4. At x = −2: 10 × −2 + 4 = −16.', null, null, null, true, null, null, null, null),
('0a522667-4d68-42f6-95f6-2882f3a1b45a', 'mm_calculus', 'year_11', 'foundation', 'multiple_choice', 'What does the derivative of a function represent at a point?', '["The maximum value of the function","The area under the curve","The gradient (slope) of the tangent at that point","The y-intercept of the function"]'::jsonb, 2, 'The derivative gives the instantaneous rate of change, which is the gradient of the tangent line at that point.', null, null, null, true, null, null, null, null),
('ca8ceb94-0802-4794-adfb-53d9f438a48c', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'What is the derivative of f(x) = x³?', '["f''(x) = x²","f''(x) = 3x³","f''(x) = x²/3","f''(x) = 3x²"]'::jsonb, 3, 'Using the power rule: d/dx(x³) = 3x².', null, null, null, true, null, null, null, null),
('06620d3e-4b86-4327-959a-7e841c7dc2b4', 'mm_calculus', 'year_11', 'proficient', 'multiple_choice', 'A function has a local maximum where its derivative is:', '["Always positive","Zero and changing from positive to negative","Always negative","Undefined"]'::jsonb, 1, 'At a local maximum, the gradient is momentarily zero as the function changes from increasing to decreasing.', null, null, null, true, null, null, null, null),
('8ca1f6ef-055f-4a21-966a-da0b5269bde4', 'mm_calculus', 'year_11', 'developing', 'multiple_choice', 'What is the derivative of f(x) = 5 (a constant)?', '["f''(x) = 1","f''(x) = x","f''(x) = 0","f''(x) = 5"]'::jsonb, 2, 'The derivative of any constant is zero, since a constant does not change.', null, null, null, true, null, null, null, null),
('eb4123c2-ff2a-414c-bb10-6ccf32138624', 'mm_calculus', 'year_11', 'proficient', 'multiple_choice', 'What is the gradient of the tangent to f(x) = x² at x = 3?', '["12","6","9","3"]'::jsonb, 1, 'f''(x) = 2x, so at x = 3, the gradient is 2 × 3 = 6.', null, null, null, true, null, null, null, null),
('51625179-29a0-4c54-bf30-6dd4dd6051ca', 'mm_probability', 'year_11', 'developing', 'multiple_choice', 'If P(A) = 0.5 and P(B) = 0.5 are independent events, what is P(A and B)?', '["0.25","1","0.5","1.5"]'::jsonb, 0, 'For independent events, P(A and B) = P(A) × P(B) = 0.5 × 0.5 = 0.25.', null, null, null, true, null, null, null, null),
('e4680419-4c16-42fb-8033-b5a904db0d96', 'mm_probability', 'year_11', 'developing', 'multiple_choice', 'If P(A) = 0.3 and P(B) = 0.7 are independent events, what is P(A and B)?', '["1","0.3","0.7","0.21"]'::jsonb, 3, 'For independent events, P(A and B) = P(A) × P(B) = 0.3 × 0.7 = 0.21.', null, null, null, true, null, null, null, null),
('2be47a67-edd5-4810-82e4-bc7b5aaf9c42', 'mm_probability', 'year_11', 'developing', 'multiple_choice', 'If P(A) = 0.6 and P(B) = 0.4 are independent events, what is P(A and B)?', '["0.6","0.4","0.24","1"]'::jsonb, 2, 'For independent events, P(A and B) = P(A) × P(B) = 0.6 × 0.4 = 0.24.', null, null, null, true, null, null, null, null),
('ca91e652-8d09-4ef2-b9f0-bf90f44eb30f', 'mm_probability', 'year_11', 'proficient', 'multiple_choice', 'If P(A) = 0.4, P(B) = 0.3, and P(A and B) = 0.1, what is P(A or B)?', '["0.4","0.6","0.7","0.1"]'::jsonb, 1, 'P(A or B) = P(A) + P(B) − P(A and B) = 0.4 + 0.3 − 0.1 = 0.6.', null, null, null, true, null, null, null, null),
('82da0061-47a2-48c1-9c21-5412952cb06a', 'mm_probability', 'year_11', 'proficient', 'multiple_choice', 'If P(A) = 0.5, P(B) = 0.2, and P(A and B) = 0.1, what is P(A or B)?', '["0.6","0.7","0.1","0.5"]'::jsonb, 0, 'P(A or B) = P(A) + P(B) − P(A and B) = 0.5 + 0.2 − 0.1 = 0.6.', null, null, null, true, null, null, null, null),
('cb27677f-ad98-478d-aa92-e3e98c0203ee', 'mm_probability', 'year_11', 'foundation', 'multiple_choice', 'Two events are described as independent when:', '["They always happen together","They can never happen together","They have equal probabilities","The outcome of one does not affect the probability of the other"]'::jsonb, 3, 'Independent events do not influence each other; the outcome of one has no effect on the probability of the other.', null, null, null, true, null, null, null, null),
('75a4d06a-d128-4815-b778-404a973c0d50', 'mm_probability', 'year_11', 'developing', 'multiple_choice', 'A fair six-sided die is rolled. What is the probability of rolling an even number?', '["1/6","2/3","1/2","1/3"]'::jsonb, 2, 'There are 3 even numbers (2, 4, 6) out of 6 possible outcomes, giving a probability of 3/6 = 1/2.', null, null, null, true, null, null, null, null),
('2f0cff1b-3684-4be1-ad81-3acaa5ba4d6b', 'mm_probability', 'year_11', 'proficient', 'multiple_choice', 'What is the probability of drawing a king from a standard 52-card deck?', '["1/52","1/13","1/4","4/13"]'::jsonb, 1, 'There are 4 kings in a deck of 52 cards, giving a probability of 4/52 = 1/13.', null, null, null, true, null, null, null, null),
('cbf48c4f-a3fd-4a1a-becd-459eeffe8173', 'mm_probability', 'year_11', 'developing', 'multiple_choice', 'A discrete random variable is best described as one that:', '["Can take only specific, countable values","Can take any value in a range","Is always equal to 1","Cannot be measured"]'::jsonb, 0, 'A discrete random variable takes distinct, countable values, unlike a continuous variable which can take any value in an interval.', null, null, null, true, null, null, null, null),
('73a49a89-6843-4d14-826d-1c31b8f32dab', 'mm_probability', 'year_11', 'proficient', 'multiple_choice', 'For a binomial distribution with n trials and success probability p, the expected value (mean) is given by:', '["n + p","np(1−p)","p/n","np"]'::jsonb, 3, 'The mean of a binomial distribution is calculated as the number of trials multiplied by the probability of success, np.', null, null, null, true, null, null, null, null),
('8ed2b902-989d-40e5-ba80-173237f28e3e', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'What is the mean of: 4, 7, 9, 10, 5, 12?', '["6.83","12","7.83","8.83"]'::jsonb, 2, 'Sum = 47. Mean = 47 ÷ 6 = 7.83.', null, null, null, true, null, null, null, null),
('5be8f566-09ce-4593-b7a9-fd4a5114342b', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'What is the mean of: 6, 8, 10, 12, 4, 14?', '["14","9","10","8"]'::jsonb, 1, 'Sum = 54. Mean = 54 ÷ 6 = 9.', null, null, null, true, null, null, null, null),
('5d29cc6e-aafb-435a-b1ba-f0e770a2b2bb', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'What is the range of: 3, 7, 4, 9, 2, 15?', '["13","15","2","16"]'::jsonb, 0, 'Range = max − min = 15 − 2 = 13.', null, null, null, true, null, null, null, null),
('d908d7a3-c5fc-4ef7-9d08-bbdfce5615ba', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'What is the range of: 10, 4, 12, 6, 8?', '["12","4","10","8"]'::jsonb, 3, 'Range = max − min = 12 − 4 = 8.', null, null, null, true, null, null, null, null),
('23ab2720-a108-4115-8abe-8580d6fd8f32', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'A data set has Q1 = 5 and Q3 = 20. What is the interquartile range?', '["5","21","15","20"]'::jsonb, 2, 'IQR = Q3 − Q1 = 20 − 5 = 15.', null, null, null, true, null, null, null, null),
('3ba40142-6bfe-4319-a80a-079977eb8e72', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'A data set has Q1 = 10 and Q3 = 30. What is the interquartile range?', '["31","20","30","10"]'::jsonb, 1, 'IQR = Q3 − Q1 = 30 − 10 = 20.', null, null, null, true, null, null, null, null),
('e276b18a-a60e-49ad-a8ab-c21fbf920163', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'A data set has Q1 = 8 and Q3 = 24. What is the interquartile range?', '["16","24","8","25"]'::jsonb, 0, 'IQR = Q3 − Q1 = 24 − 8 = 16.', null, null, null, true, null, null, null, null),
('ef6437b8-827a-4ca0-9c35-1d8a5c2e6f2b', 'gm_data_analysis', 'year_11', 'foundation', 'multiple_choice', 'Which measure of centre is most affected by an extreme outlier in a data set?', '["The mean","The median","The mode","The range"]'::jsonb, 0, 'The mean is calculated using every value, so a single extreme outlier can pull it strongly in one direction, unlike the median.', null, null, null, true, null, null, null, null),
('400cdc68-f4ac-443b-988f-acda1fe55ea7', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'In a box plot, what does the line inside the box represent?', '["The mode","The range","The mean","The median"]'::jsonb, 3, 'The line inside a box plot marks the median (the middle value) of the data set.', null, null, null, true, null, null, null, null),
('3f232a72-0e11-4f28-b1bf-49133d438cd3', 'gm_data_analysis', 'year_11', 'proficient', 'multiple_choice', 'A data set is described as positively skewed when:', '["It has no outliers","It has a long tail extending to the right","It has a long tail extending to the left","It is perfectly symmetric"]'::jsonb, 1, 'A positively skewed distribution has a longer tail on the right side, with the mean typically greater than the median.', null, null, null, true, null, null, null, null),
('eec6117a-44bf-433d-a3cf-931940534924', 'gm_data_analysis', 'year_11', 'developing', 'multiple_choice', 'What does the standard deviation of a data set measure?', '["The middle value of the data","The spread of data around the mean","The most frequent value","The total of all values"]'::jsonb, 1, 'Standard deviation measures how spread out data values are from the mean.', null, null, null, true, null, null, null, null),
('6e1b5b35-e265-4737-b5d7-58a0dcaffb34', 'gm_financial', 'year_11', 'developing', 'multiple_choice', 'How much simple interest is earned on $1000 invested at 4% per year, over 3 years?', '["$130","$1000","$60","$120"]'::jsonb, 3, 'Simple interest = P × r × t = 1000 × 0.04 × 3 = $120.', null, null, null, true, null, null, null, null),
('521a3740-8510-4217-b96d-798a3c8c4ee3', 'gm_financial', 'year_11', 'developing', 'multiple_choice', 'How much simple interest is earned on $2000 invested at 5% per year, over 2 years?', '["$2000","$100","$200","$220"]'::jsonb, 2, 'Simple interest = P × r × t = 2000 × 0.05 × 2 = $200.', null, null, null, true, null, null, null, null),
('5c635027-be5a-4f76-9429-8b2d2d004e15', 'gm_financial', 'year_11', 'developing', 'multiple_choice', 'How much simple interest is earned on $1500 invested at 3% per year, over 4 years?', '["$90","$180","$195","$1500"]'::jsonb, 1, 'Simple interest = P × r × t = 1500 × 0.03 × 4 = $180.', null, null, null, true, null, null, null, null),
('573f379f-1c60-4633-8f67-b1c06e04f0a2', 'gm_financial', 'year_11', 'proficient', 'multiple_choice', 'Using compound interest, what is the value of $1000 invested at 5% per year (compounded annually) after 2 years?', '["$1103","$1100","$1000","$1153"]'::jsonb, 0, 'A = P(1 + r)^t = 1000 × (1 + 0.05)^2 = $1103.', null, null, null, true, null, null, null, null),
('6a0880f6-97cb-4c2e-9107-4d6dc92ad737', 'gm_financial', 'year_11', 'proficient', 'multiple_choice', 'Using compound interest, what is the value of $2000 invested at 4% per year (compounded annually) after 2 years?', '["$2160","$2000","$2213","$2163"]'::jsonb, 3, 'A = P(1 + r)^t = 2000 × (1 + 0.04)^2 = $2163.', null, null, null, true, null, null, null, null),
('ce8b7f9e-994e-404a-9e5e-a6f54acaa71a', 'gm_financial', 'year_11', 'foundation', 'multiple_choice', 'What term describes the original amount of money borrowed or invested, before interest?', '["Principal","Balance","Rate","Interest"]'::jsonb, 0, 'The principal is the original sum of money, before any interest is added.', null, null, null, true, null, null, null, null),
('9302a2b8-ec8b-4781-8373-e6ef99835c75', 'gm_financial', 'year_11', 'developing', 'multiple_choice', 'What is the main difference between simple and compound interest?', '["Simple interest changes every year","Simple interest is always higher","Compound interest is only used for loans","Compound interest is calculated on the principal plus previously earned interest"]'::jsonb, 3, 'Compound interest grows faster because it is calculated on the accumulated total, not just the original principal.', null, null, null, true, null, null, null, null),
('226873d3-9000-49cb-8af6-f99362a202d1', 'gm_financial', 'year_11', 'proficient', 'multiple_choice', 'A car valued at $20,000 depreciates by 15% in its first year. What is its value after one year?', '["$17,000","$3,000","$18,500","$15,000"]'::jsonb, 0, 'Depreciation of 15% means the car loses 0.15 × $20,000 = $3,000, leaving $20,000 − $3,000 = $17,000.', null, null, null, true, null, null, null, null),
('7ec6a61e-a615-464c-b923-ccc785640dc5', 'gm_financial', 'year_11', 'developing', 'multiple_choice', 'A loan repayment plan where equal amounts are paid at regular intervals is called:', '["A dividend","An annuity","A principal","A deposit"]'::jsonb, 1, 'An annuity is a series of equal payments made at regular intervals, commonly used to repay loans.', null, null, null, true, null, null, null, null),
('9c3b5c45-25f0-4f1f-851d-6847d5057a91', 'gm_financial', 'year_11', 'foundation', 'multiple_choice', 'Which of these best describes "flat rate" interest on a loan?', '["An interest rate of exactly 0%","A fixed percentage charged on the original amount borrowed for the full term","A rate charged only in the final year","An interest rate that changes daily"]'::jsonb, 1, 'Flat rate interest is calculated as a fixed percentage of the original principal, applied for the entire loan term, similar to simple interest.', null, null, null, true, null, null, null, null),
('0d928591-2223-4479-ac5b-2e88369d32ff', 'sm_complex_numbers', 'year_11', 'developing', 'multiple_choice', 'What is the modulus of the complex number 5 − 12i?', '["7","13","17","169"]'::jsonb, 1, '|a + bi| = √(a² + b²) = √(5² + (−12)²) = √(25 + 144) = √169 = 13.', 'VCE-SM-U1', null, null, true, null, null, null, null),
('bcc3aef1-1fcc-48eb-9e21-3120ecc54a52', 'sm_complex_numbers', 'year_11', 'developing', 'multiple_choice', 'What is the modulus of the complex number 5 + 12i?', '["12","17","13","15"]'::jsonb, 2, 'Modulus = √(5² + 12²) = √169 = 13.', null, null, null, true, null, null, null, null),
('32ee668b-2615-4e4c-a153-93f90f2c3289', 'sm_complex_numbers', 'year_11', 'developing', 'multiple_choice', 'What is the modulus of the complex number 8 + 6i?', '["14","10","12","9"]'::jsonb, 1, 'Modulus = √(8² + 6²) = √100 = 10.', null, null, null, true, null, null, null, null),
('6c139960-7a4e-4b3b-8686-f7ed84cc2bae', 'sm_complex_numbers', 'year_11', 'developing', 'multiple_choice', 'What is (2 + 3i) + (1 − 4i)?', '["3 − 1i","3 + 1i","3 − 7i","1 − 1i"]'::jsonb, 0, 'Add the real parts: 2 + 1 = 3. Add the imaginary parts: 3 + (−4) = −1, giving 3 − 1i.', null, null, null, true, null, null, null, null),
('b09765ca-7a25-4f4e-84c9-df4510e8ff17', 'sm_complex_numbers', 'year_11', 'developing', 'multiple_choice', 'What is (4 − 2i) − (1 + 3i)?', '["3 + 5i","5 − 5i","3 − 1i","3 − 5i"]'::jsonb, 3, 'Subtract the real parts: 4 − 1 = 3. Subtract the imaginary parts: −2 − 3 = −5, giving 3 − 5i.', null, null, null, true, null, null, null, null),
('aa542fe0-441f-4407-9de1-1d3e875057a7', 'sm_complex_numbers', 'year_11', 'foundation', 'multiple_choice', 'What is i³ (where i is the imaginary unit)?', '["1","−i","−1","i"]'::jsonb, 1, 'i³ = i² × i = (−1) × i = −i.', null, null, null, true, null, null, null, null),
('fbcaaace-58a7-4af4-b31c-77eb6e16fb65', 'sm_complex_numbers', 'year_11', 'proficient', 'multiple_choice', 'What is the complex conjugate of 5 − 3i?', '["3 − 5i","5 + 3i","−5 − 3i","−5 + 3i"]'::jsonb, 1, 'The complex conjugate flips the sign of the imaginary part: 5 − 3i becomes 5 + 3i.', null, null, null, true, null, null, null, null),
('7c9f7c4d-4231-4ee2-ad0e-700dcf63956f', 'sm_complex_numbers', 'year_11', 'developing', 'multiple_choice', 'In the complex plane, the real part of a complex number is plotted on the:', '["Vertical axis","Diagonal axis","Origin only","Horizontal axis"]'::jsonb, 3, 'By convention, the real part is plotted on the horizontal axis and the imaginary part on the vertical axis.', null, null, null, true, null, null, null, null),
('26e96f10-dfd5-4ba0-a320-44c414cc32ac', 'sm_vectors', 'year_11', 'developing', 'multiple_choice', 'What is the magnitude of the vector (3, 4)?', '["7","4","8","5"]'::jsonb, 3, 'Magnitude = √(3² + 4²) = √25 = 5.', null, null, null, true, null, null, null, null),
('57e7d811-de54-4c0c-a3fc-ea6f65ed8b1e', 'sm_vectors', 'year_11', 'developing', 'multiple_choice', 'What is the magnitude of the vector (9, 40)?', '["31","41","49","1681"]'::jsonb, 1, '|v| = √(9² + 40²) = √(81 + 1600) = √1681 = 41.', 'VCE-SM-U1', null, null, true, null, null, null, null),
('fb85968c-97c0-45a6-a459-94e8f3783354', 'sm_vectors', 'year_11', 'developing', 'multiple_choice', 'What is the magnitude of the vector (5, 12)?', '["17","13","15","12"]'::jsonb, 1, 'Magnitude = √(5² + 12²) = √169 = 13.', null, null, null, true, null, null, null, null),
('dc79b6d3-25cb-4e63-b710-3367a3d10807', 'sm_vectors', 'year_11', 'foundation', 'multiple_choice', 'Two vectors are parallel. What can be said about the angle between them?', '["It is 0° or 180°","It is always 90°","It is always 45°","It cannot be determined"]'::jsonb, 0, 'Parallel vectors point in the same direction (0°) or exactly opposite directions (180°).', null, null, null, true, null, null, null, null),
('e51e94b6-73a9-4e93-82d9-c99b6aed828a', 'sm_vectors', 'year_11', 'proficient', 'multiple_choice', 'What is the dot product of vectors (2, 3) and (4, 1)?', '["9","6","14","11"]'::jsonb, 3, 'Dot product = (2×4) + (3×1) = 8 + 3 = 11.', null, null, null, true, null, null, null, null),
('ecfb8afc-896b-4c15-9da7-9d96e2a95797', 'sm_vectors', 'year_11', 'developing', 'multiple_choice', 'A vector with magnitude 1 is called a:', '["Position vector","Scalar","Zero vector","Unit vector"]'::jsonb, 3, 'A unit vector has a magnitude of exactly 1 and is often used to indicate direction.', null, null, null, true, null, null, null, null),
('d29f6f71-e1a6-4f34-bace-2048ffff3cb7', 'number_operations', 'year_7', 'foundation', 'multiple_choice', 'Zoe''s savings tracker shows −8 points from a missed goal, then she earns back 3 points for a completed chore. What is her total now (−8 + 3)?', '["11","−5","−11","5"]'::jsonb, 1, 'Starting at −8 and moving 3 units up the number line gives −5.', 'AC9M7N02', null, null, true, null, null, null, null),
('8deca51a-ea5b-435d-bef7-d954d53f664b', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'A water tank''s level was dropping by 4 cm each hour. Looking back at the reading from 6 hours ago, how does that past level compare to now, calculated as −4 × −6?', '["−24","24","−10","10"]'::jsonb, 1, 'A negative times a negative gives a positive: 4 × 6 = 24 cm.', 'AC9M7N02', null, null, true, null, null, null, null),
('e6842764-aeae-4a1c-a64c-7c6aa6dcafe9', 'number_operations', 'year_7', 'proficient', 'short_answer', 'A phone plan charges a $3 flat fee plus $4 per hour of overage, and Priya used 2 hours of overage this month. Using 3 + 4 × 2, what is her total charge?', null, null, 'Order of operations: multiply first (4 × 2 = 8), then add: 3 + 8 = 11.', 'AC9M7N04', null, null, true, '11', null, null, null),
('37db7f1b-9e7c-4b35-897d-40e71172fe98', 'number_operations', 'year_7', 'proficient', 'short_answer', 'A survey of 640 students found that 0.45 of them own a pet. How many students own a pet?', null, null, '0.45 × 640 = 288 students.', 'AC9M7N03', null, true, true, '288', null, null, null),
('519ffa79-43b2-4f66-8d1b-623a80140cc5', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'The bar chart shows how many cans of food each class collected for a food drive. What is the total number of cans collected by all four classes?', '["118","128","138","148"]'::jsonb, 1, 'Add all four bars: 34 + 28 + 41 + 25 = 128 cans.', 'AC9M7N06', null, null, true, null, null, null, null),
('6c06f0b1-ff59-4f57-b638-eae535e7f516', 'number_operations', 'year_7', 'proficient', 'short_answer', 'The bar chart shows how much pocket money a student saved each week. What was the average (mean) amount saved per week, in dollars?', null, null, 'Total saved = 12 + 18 + 15 + 21 = 66. Mean = 66 ÷ 4 = $16.50.', 'AC9M7N06', null, true, true, '16.5', ARRAY['$16.50', '16.50', '$16.5']::text[], null, null),
('062f0fce-00a6-48a7-b6ff-3e3fd35430e5', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'The bar chart shows how many books four students read this term. How many more books did Zoe read than Kai?', '["3","4","5","6"]'::jsonb, 2, 'Zoe read 9 books and Kai read 4: 9 − 4 = 5.', 'AC9M7N02', null, null, true, null, null, null, null),
('58b446c8-a4dc-459b-a90a-0864836f904e', 'statistics_probability', 'year_7', 'proficient', 'short_answer', 'The bar chart shows cars sold each month. What is the range of the number of cars sold?', null, null, 'Range = highest − lowest = 18 − 9 = 9.', 'AC9M7ST01', null, null, true, '9', null, null, null),
('bb5b9410-ad9c-475f-846a-d22523932ae0', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'A submarine starts at −6 m (relative to sea level) and rises to the position shown as ''End''. What is the total change in the submarine''s height?', '["3 m","6 m","9 m","15 m"]'::jsonb, 2, 'Change = end − start = 3 − (−6) = 9 m.', 'AC9M7N02', null, null, true, null, null, null, null),
('9ac0e8d1-fda4-4ddf-ae9a-718ba4b0ea42', 'algebra_equations', 'year_7', 'proficient', 'short_answer', 'The number line shows the first three terms of a pattern that increases by the same amount each time. What is the value of Term 5?', null, null, 'Each term increases by 4 (7 − 3 = 4, 11 − 7 = 4). Term 4 = 15, Term 5 = 19.', 'AC9M7A01', null, null, true, '19', null, null, null),
('9092ce41-8c93-4c41-92f2-e7c628026385', 'statistics_probability', 'year_7', 'proficient', 'multiple_choice', 'The dot plot shows the number of siblings for 12 students. What is the mode?', '["0","1","2","3"]'::jsonb, 2, '2 siblings occurs most often (5 times), so the mode is 2.', 'AC9M7ST02', null, null, true, null, null, null, null),
('c2135fd9-60b0-4703-9b04-e88e0509e162', 'statistics_probability', 'year_7', 'proficient', 'short_answer', 'The dot plot shows test scores for 9 students. What is the median score?', null, null, 'With 9 ordered values, the median is the 5th value: 8.', 'AC9M7ST02', null, null, true, '8', null, null, null),
('63de1c3d-dc33-428b-b0e1-ec17d36e3898', 'geometry_measurement', 'year_7', 'developing', 'multiple_choice', 'Sam starts at the Library shown on the map and walks 2 cells east and 1 cell north. Which cell does Sam end up in?', '["C3","D4","D3","E3"]'::jsonb, 2, 'From B2, moving 2 cells east reaches D2, then 1 cell north reaches D3.', 'AC9M7SP01', null, null, true, null, null, null, null),
('b8a32cba-1810-49c4-8f38-bc45870adf48', 'geometry_measurement', 'year_7', 'proficient', 'short_answer', 'Each cell on the map represents 1 km. Using the shortest path along grid lines (not diagonally), how many kilometres is it from Home to School?', null, null, 'Horizontal distance = 3 km (A to D), vertical distance = 4 km (row 1 to row 5). Total = 3 + 4 = 7 km.', 'AC9M7SP01', null, null, true, '7', ARRAY['7 km']::text[], null, null),
('2882bff1-ff0a-42d2-8ea2-8afe195cdaaa', 'geometry_measurement', 'year_7', 'developing', 'short_answer', 'A rectangular garden bed has the dimensions shown. What is its perimeter, in centimetres?', null, null, 'Perimeter = 2 × (length + width) = 2 × (12 + 5) = 34 cm.', 'AC9M7M02', null, null, true, '34', ARRAY['34 cm']::text[], null, null),
('e10823cd-e53f-4a8c-bf27-11eedc7765df', 'geometry_measurement', 'year_7', 'developing', 'multiple_choice', 'What is the area of the rectangle shown?', '["36 m²","13 m²","26 m²","40 m²"]'::jsonb, 0, 'Area = length × width = 9 × 4 = 36 m².', 'AC9M7M03', null, null, true, null, null, null, null),
('584b2fe1-fe6c-44f7-ab79-fc08afd389b0', 'geometry_measurement', 'year_7', 'proficient', 'short_answer', 'What is the area of the right-angled triangle shown?', null, null, 'Area of a right triangle = ½ × base × height = ½ × 8 × 6 = 24 cm².', 'AC9M7M03', null, null, true, '24', ARRAY['24 cm²', '24cm2']::text[], null, null),
('f3d7198a-a761-45e0-82ac-6043e1fc88bc', 'number_operations', 'year_7', 'developing', 'multiple_choice', 'What is the total number of steps (in thousands) walked over the four days shown?', '["28","29","30","31"]'::jsonb, 3, '8 + 6 + 10 + 7 = 31 thousand steps.', 'AC9M7N02', null, null, true, null, null, null, null),
('e884cb68-2f76-4a6c-b458-4ddc0aaf7488', 'algebra_equations', 'year_7', 'proficient', 'short_answer', 'The number line shows a temperature pattern over three days, increasing by the same amount each day. If the pattern continues, what temperature (°C) would Day 5 be?', null, null, 'Each day increases by 3°C (5 − 2 = 3, 8 − 5 = 3). Day 4 = 11°C, Day 5 = 14°C.', 'AC9M7A01', null, null, true, '14', ARRAY['14°C', '14 degrees']::text[], null, null),
