('b34774ad-bda8-4d14-bb8b-46bda8b818fb', 'geometry_measurement', 'year_7', 'proficient', 'short_answer', 'Each cell on the map represents 1.5 km. Using the shortest path along grid lines, how many kilometres is it from the Depot to the Warehouse?', null, null, 'Horizontal + vertical distance = 4 + 4 = 8 grid cells. 8 × 1.5 km = 12 km.', 'AC9M7SP01', null, true, true, '12', ARRAY['12 km']::text[], null, null),
