('21a21805-fc4d-406f-a349-e6d120408e27', 'grammar_punctuation', 'grade_3', 'foundation', 'multiple_choice', 'Which sentence needs a question mark at the end?', '["I found my hat","The hat is blue","My hat is lost","Where is my hat"]'::jsonb, 3, 'Only the first is asking something, so it needs a question mark. The others are statements and take full stops.', 'AC9E3LA03', null, null, true, null, null, null, null),
('ef08a76f-1dc5-47c2-923d-ade78012fbac', 'grammar_punctuation', 'grade_3', 'foundation', 'multiple_choice', 'Which word completes this sentence correctly? The children ___ playing in the yard.', '["is","are","was","am"]'::jsonb, 1, '"Children" is plural, so it takes the plural verb "are".', 'AC9E3LA03', null, null, true, null, null, null, null),
('1890acac-3763-4d7a-8674-a75da8c85fc1', 'grammar_punctuation', 'grade_3', 'foundation', 'multiple_choice', 'Which sentence uses capital letters correctly?', '["we went to sydney in july.","we Went to Sydney in july.","We went to Sydney in July.","We went to sydney in July."]'::jsonb, 2, 'A sentence starts with a capital letter, and names of places and months take capitals too.', 'AC9E3LA03', null, null, true, null, null, null, null),
('8dcb4564-c2fb-4f3f-8200-9d2a49f44721', 'grammar_punctuation', 'grade_3', 'foundation', 'multiple_choice', 'What is the plural of "box"?', '["boxes","boxs","boxies","boxen"]'::jsonb, 0, 'Words ending in x add "es" to become plural: box becomes boxes.', 'AC9E3LA03', null, null, true, null, null, null, null),
('dba1c916-ca63-4144-91de-4010f94935fc', 'grammar_punctuation', 'grade_3', 'foundation', 'multiple_choice', 'Which word in this sentence is a noun? The dog barked loudly.', '["dog","barked","loudly","the"]'::jsonb, 0, 'A noun names a person, place or thing. "Dog" is the thing; "barked" is the verb and "loudly" describes how.', 'AC9E3LA03', null, null, true, null, null, null, null),
('c258b41d-2b5c-470a-81b3-fc15626d0a91', 'grammar_punctuation', 'grade_3', 'foundation', 'multiple_choice', 'Which sentence is written in the past tense?', '["I walk to school.","I will walk to school.","I walked to school.","I am walking to school."]'::jsonb, 2, '"Walked" shows the action already happened.', 'AC9E3LA03', null, null, true, null, null, null, null),
('71fd465a-d578-4861-957e-19bf1e8d0ff3', 'grammar_punctuation', 'grade_3', 'foundation', 'multiple_choice', 'Which sentence uses "a" and "an" correctly?', '["I ate a apple.","I ate an apple.","I ate an banana.","I ate a orange."]'::jsonb, 1, 'Use "an" before a word starting with a vowel sound: an apple.', 'AC9E3LA03', null, null, true, null, null, null, null),
('1f5d3d46-d551-4d1f-8a86-eb87fd6408de', 'grammar_punctuation', 'grade_3', 'foundation', 'multiple_choice', 'Which punctuation mark should end this sentence? What a huge wave that was', '["a full stop","a question mark","a comma","an exclamation mark"]'::jsonb, 3, 'The sentence expresses surprise rather than asking or simply stating, so it takes an exclamation mark.', 'AC9E3LA03', null, null, true, null, null, null, null),
('3dc0bc1b-dd35-4fa4-9cc1-6993ac836b37', 'grammar_punctuation', 'grade_5', 'developing', 'multiple_choice', 'Which sentence uses an apostrophe correctly in a contraction?', '["It''s going to rain.","Its going to rain.","Its'' going to rain.","Itis going to rain."]'::jsonb, 0, '"It’s" is short for "it is", so the apostrophe replaces the missing letter.', 'AC9E5LA03', null, null, true, null, null, null, null),
('0ced3e92-0aa4-490a-8306-31f6fc13afb7', 'grammar_punctuation', 'grade_5', 'developing', 'multiple_choice', 'Which word is an adjective in this sentence? The enormous truck blocked the narrow road.', '["truck","blocked","enormous","road"]'::jsonb, 2, 'An adjective describes a noun. "Enormous" describes the truck.', 'AC9E5LA03', null, null, true, null, null, null, null),
('8bca8af6-867b-4849-8e03-de2444fbf125', 'grammar_punctuation', 'grade_5', 'developing', 'multiple_choice', 'Which word completes this sentence correctly? The group of students ___ late for the bus.', '["were","are","being","was"]'::jsonb, 3, 'The subject of the sentence is "group", which is singular, so it takes the singular verb "was" — not "were", even though "students" sits next to it.', 'AC9E5LA03', null, null, true, null, null, null, null),
('98cdc7be-9ab7-40ce-97ff-64ab822bd073', 'grammar_punctuation', 'grade_5', 'developing', 'multiple_choice', 'Where should the comma go? After the storm passed we went outside.', '["After the, storm passed we went outside.","After the storm passed, we went outside.","After the storm, passed we went outside.","After the storm passed we, went outside."]'::jsonb, 1, 'A comma goes after the introductory phrase, before the main clause begins.', 'AC9E5LA03', null, null, true, null, null, null, null),
('96d0a0ec-5dc0-4f30-936f-c802c9beb2a4', 'grammar_punctuation', 'grade_5', 'developing', 'multiple_choice', 'Which word completes this sentence correctly? The dog wagged ___ tail.', '["it''s","its''","its","it is"]'::jsonb, 2, '"Its" shows possession. "It’s" would mean "it is", which does not fit.', 'AC9E5LA03', null, null, true, null, null, null, null),
('142f0883-2583-4a89-99a1-102d98eb2b67', 'grammar_punctuation', 'grade_5', 'developing', 'multiple_choice', 'Which of these is a compound sentence?', '["The rain stopped and the sun came out.","The rain stopped.","After the rain stopped.","Stopping the rain."]'::jsonb, 0, 'A compound sentence joins two complete ideas with a conjunction such as "and".', 'AC9E5LA03', null, null, true, null, null, null, null),
('f31043af-1709-4027-80a9-5aa2fc9f1da5', 'grammar_punctuation', 'grade_5', 'developing', 'multiple_choice', 'Which sentence punctuates the list correctly?', '["We packed apples, oranges and pears.","We packed apples oranges and pears.","We packed, apples oranges and pears.","We packed apples, oranges, and, pears."]'::jsonb, 0, 'Items in a list are separated by commas, with "and" before the final item.', 'AC9E5LA03', null, null, true, null, null, null, null),
('f99fb06e-2586-45c7-8f71-af7293b03bef', 'grammar_punctuation', 'grade_5', 'developing', 'multiple_choice', 'Which word is a conjunction in this sentence? She wanted to swim, but the water was cold.', '["wanted","water","but","cold"]'::jsonb, 2, 'A conjunction joins two parts of a sentence. "But" joins the two ideas here.', 'AC9E5LA03', null, null, true, null, null, null, null),
('43a57067-c781-485e-8dea-cc4cd47ec5c7', 'grammar_punctuation', 'year_7', 'proficient', 'multiple_choice', 'Which sentence correctly joins two complete clauses?', '["The bus was late, we walked.","The bus was late we walked.","The bus was late: we walked;","The bus was late; we walked."]'::jsonb, 3, 'Two independent clauses can be joined with a semicolon. A comma alone creates a comma splice.', 'AC9E7LA03', null, null, true, null, null, null, null),
('4826a98c-9bcf-4717-9a4c-76b22c716fb7', 'grammar_punctuation', 'year_7', 'proficient', 'multiple_choice', 'Which sentence contains a relative clause?', '["The book was long.","The book, which I borrowed from the library, was long.","I borrowed the book.","Borrowing the book from the library."]'::jsonb, 1, 'A relative clause begins with a relative pronoun such as "which" and adds information about a noun.', 'AC9E7LA03', null, null, true, null, null, null, null),
('4b7b08a8-3bf4-4b45-bf9e-cd70d199478f', 'grammar_punctuation', 'year_7', 'proficient', 'multiple_choice', 'In which sentence does the subject receive the action rather than perform it?', '["The council approved the plan.","The council is approving the plan.","The plan was approved by the council.","Approve the plan."]'::jsonb, 2, 'In the passive voice the subject receives the action: the plan was approved.', 'AC9E7LA03', null, null, true, null, null, null, null),
('21b79a64-7822-4bea-a24c-27d3f61196ab', 'grammar_punctuation', 'year_7', 'proficient', 'multiple_choice', 'Which sentence uses an apostrophe correctly for more than one owner?', '["The students'' books were left behind.","The students books were left behind.","The student''s books were left behind.","The students books'' were left behind."]'::jsonb, 0, 'For a plural noun already ending in s, the apostrophe goes after the s.', 'AC9E7LA03', null, null, true, null, null, null, null),
('fe75b042-ec82-4402-a06a-59d6d924b6ab', 'grammar_punctuation', 'year_7', 'proficient', 'multiple_choice', 'Which word is a preposition in this sentence? She slid the letter beneath the door.', '["beneath","slid","letter","door"]'::jsonb, 0, 'A preposition shows position or direction. "Beneath" shows where the letter went.', 'AC9E7LA03', null, null, true, null, null, null, null),
('391fdb05-5538-40ab-9a00-46f8d7af6aac', 'grammar_punctuation', 'year_7', 'proficient', 'multiple_choice', 'Which sentence uses a colon correctly?', '["We needed three things, rope, water and a map.","We needed: three things rope, water and a map.","We needed three things: rope, water and a map.","We needed three things rope: water and a map."]'::jsonb, 2, 'A colon introduces a list after a complete statement.', 'AC9E7LA03', null, null, true, null, null, null, null),
('0927e036-78fa-4e15-9a2c-bad375b50dbe', 'grammar_punctuation', 'year_7', 'proficient', 'multiple_choice', 'Which sentence avoids a double negative?', '["I didn''t see nothing.","I didn''t see anything.","I never saw nothing.","I haven''t got no time."]'::jsonb, 1, 'Using both "didn’t" and "nothing" cancels the meaning. "Didn’t see anything" is correct.', 'AC9E7LA03', null, null, true, null, null, null, null),
('e29c9695-6809-4371-8445-2927d1b6e5d5', 'grammar_punctuation', 'year_7', 'proficient', 'multiple_choice', 'Which sentence uses the correct pronoun after the preposition?', '["Between you and I, the plan is risky.","Between yourself and I, the plan is risky.","Between I and you, the plan is risky.","Between you and me, the plan is risky."]'::jsonb, 3, 'After a preposition such as "between", the object pronoun "me" is used.', 'AC9E7LA03', null, null, true, null, null, null, null),
('59f7d9b3-d366-4667-b67b-9c0a60aa1e33', 'grammar_punctuation', 'year_9', 'advanced', 'multiple_choice', 'Which sentence keeps all the items in its list in the same grammatical form?', '["She likes hiking, swimming and to cycle.","She likes to hike, swimming and cycling.","She likes hiking, swimming and cycling.","She likes hiking, to swim and cycling."]'::jsonb, 2, 'Items in a list should share the same grammatical form — here all three are "-ing" words.', 'AC9E9LA03', null, null, true, null, null, null, null),
('10d5022f-e3d8-4f49-a8e9-8adde078335d', 'grammar_punctuation', 'year_9', 'advanced', 'multiple_choice', 'Which sentence punctuates the non-defining clause correctly?', '["My brother who lives in Perth is visiting.","My brother, who lives in Perth is visiting.","My brother who lives in Perth, is visiting.","My brother, who lives in Perth, is visiting."]'::jsonb, 3, 'A non-defining clause adds extra information and is enclosed by a pair of commas.', 'AC9E9LA03', null, null, true, null, null, null, null),
('640affa6-46e0-4c96-8537-eb8397ac154b', 'grammar_punctuation', 'year_9', 'advanced', 'multiple_choice', 'Which sentence uses the subjunctive correctly?', '["If I was you, I would apologise.","If I were you, I would apologise.","If I am you, I would apologise.","If I be you, I would apologise."]'::jsonb, 1, 'The subjunctive "were" is used for a hypothetical situation that is not real.', 'AC9E9LA03', null, null, true, null, null, null, null),
('5907e6f3-dae8-4353-b5e4-4d510193d262', 'grammar_punctuation', 'year_9', 'advanced', 'multiple_choice', 'Which sentence uses semicolons correctly to separate items that already contain commas?', '["The tour visits Rome, Italy, Lyon, France, and Bern, Switzerland.","The tour visits Rome; Italy, Lyon; France, and Bern; Switzerland.","The tour visits Rome, Italy; Lyon, France; and Bern, Switzerland.","The tour visits Rome, Italy: Lyon, France: and Bern, Switzerland."]'::jsonb, 2, 'When list items contain their own commas, semicolons separate the items so the groupings stay clear.', 'AC9E9LA03', null, null, true, null, null, null, null),
('66428f7d-2e6b-41a5-91d2-0fe39e8caee4', 'grammar_punctuation', 'year_9', 'advanced', 'multiple_choice', 'In which sentence does the subject perform the action?', '["The committee wrote the report.","The report was written by the committee.","The report had been written.","It was decided that the report be written."]'::jsonb, 0, 'In the active voice the subject performs the action: the committee wrote.', 'AC9E9LA03', null, null, true, null, null, null, null),
('1e1383a4-0114-46e9-94c6-9f4e55808ec9', 'grammar_punctuation', 'year_9', 'advanced', 'multiple_choice', 'Which sentence uses "who" or "whom" correctly?', '["To whom should I address the letter?","To who should I address the letter?","Whom is at the door?","Who did you give it to him?"]'::jsonb, 0, '"Whom" is the object form, used after a preposition such as "to".', 'AC9E9LA03', null, null, true, null, null, null, null),
('27095e91-2eea-4362-bef8-b7f2d3e893e0', 'grammar_punctuation', 'year_9', 'advanced', 'multiple_choice', 'Which sentence correctly joins these two ideas without a comma splice?', '["The results were clear, we published them.","The results were clear we published them.","The results were clear, so we published them.","The results were clear, published them."]'::jsonb, 2, 'Two complete clauses cannot be joined by a comma alone; a conjunction such as "so" is needed.', 'AC9E9LA03', null, null, true, null, null, null, null),
('d695ce4d-d076-45b6-99d3-cf2d4bd7873e', 'grammar_punctuation', 'year_9', 'advanced', 'multiple_choice', 'Which sentence uses the apostrophe correctly?', '["The 1990''s were a decade of rapid change.","The 1990s were a decade of rapid change.","The 1990s'' were a decade of rapid change.","The 199''0s were a decade of rapid change."]'::jsonb, 1, 'A plural decade takes no apostrophe — an apostrophe would wrongly signal possession.', 'AC9E9LA03', null, null, true, null, null, null, null),
('ed3d46f2-fdee-4da1-8fe3-e5abd1309d42', 'reading_comprehension', 'grade_3', 'foundation', 'multiple_choice', 'How deep should the hole be?', '["About two metres","About two centimetres","About ten centimetres","As deep as your hand"]'::jsonb, 1, 'The text says to "dig a small hole about two centimetres deep".', 'AC9E3LY05', '3f256460-11da-489e-bfbf-3e135ec80686', null, true, null, null, null, null),
('aa96c610-1b88-4ad2-8b1b-8596f122f9a2', 'reading_comprehension', 'grade_3', 'foundation', 'multiple_choice', 'How many hours of sunlight do sunflowers need each day?', '["At least two","At least six","At least four","At least ten"]'::jsonb, 1, 'The text says they "need at least six hours of sunlight every day".', 'AC9E3LY05', '3f256460-11da-489e-bfbf-3e135ec80686', null, true, null, null, null, null),
('ccbad129-6039-4bfe-beed-13ef003b9747', 'reading_comprehension', 'grade_3', 'developing', 'multiple_choice', 'Why should you leave a hand’s width between seeds?', '["So the birds cannot reach them","So they get more water","So they flower at the same time","So the plants have room to grow"]'::jsonb, 3, 'The text explains this is "so the plants have room to grow".', 'AC9E3LY05', '3f256460-11da-489e-bfbf-3e135ec80686', null, true, null, null, null, null),
('41e094e9-3df3-4e8c-834b-cba72fdb2e42', 'reading_comprehension', 'grade_3', 'developing', 'multiple_choice', 'What is the purpose of this text?', '["To explain how to plant a sunflower","To tell a story about a sunflower","To persuade people to buy seeds","To describe what sunflowers look like"]'::jsonb, 0, 'The text gives ordered steps to follow, which makes it a set of instructions.', 'AC9E3LY05', '3f256460-11da-489e-bfbf-3e135ec80686', null, true, null, null, null, null),
('85cb8ba8-a911-465e-b6bd-d0d032523cd2', 'reading_comprehension', 'grade_3', 'proficient', 'multiple_choice', 'Why might you need to tie the stem to a stake?', '["To help it grow taller","To keep insects away","To stop it bending over in the wind","To hold the seeds in place"]'::jsonb, 2, 'The text says this stops the tall plant bending over in the wind.', 'AC9E3LY05', '3f256460-11da-489e-bfbf-3e135ec80686', null, true, null, null, null, null),
('38354fd5-7c69-4ace-a141-7eae4a033170', 'reading_comprehension', 'grade_3', 'proficient', 'multiple_choice', 'Which words help the reader follow the order of the steps?', '["Sunny, damp, green","Seed, soil, water","Deep, tall, small","First, Next, Then, Finally"]'::jsonb, 3, '"First", "Next", "Then" and "Finally" signal the order the steps happen in.', 'AC9E3LY05', '3f256460-11da-489e-bfbf-3e135ec80686', null, true, null, null, null, null),
('c60a4945-6f5a-4558-80fa-e53083dde317', 'reading_comprehension', 'grade_3', 'foundation', 'multiple_choice', 'Where does Milo hide during a storm?', '["In the garden","Under the kitchen table","In Ava’s bed","Behind the door"]'::jsonb, 1, 'The text says he "would hide under the kitchen table".', 'AC9E3LY05', '7867377c-4512-4aeb-86d9-f8178306590f', null, true, null, null, null, null),
('dfa4ae52-787f-4bb1-8f87-d5d1c1fc85ce', 'reading_comprehension', 'grade_3', 'foundation', 'multiple_choice', 'What is Milo?', '["A puppy","A cat","An old dog","A bird"]'::jsonb, 2, 'The text says "He was an old dog with grey hair around his nose."', 'AC9E3LY05', '7867377c-4512-4aeb-86d9-f8178306590f', null, true, null, null, null, null),
('70b64824-2345-4529-b071-a2a47c86fd5f', 'reading_comprehension', 'grade_3', 'developing', 'multiple_choice', 'What does Ava do to help Milo?', '["She lies beside him and talks quietly","She carries him outside","She closes all the windows","She gives him food"]'::jsonb, 0, 'Ava "would lie down on the cool floor beside him and talk in a quiet voice".', 'AC9E3LY05', '7867377c-4512-4aeb-86d9-f8178306590f', null, true, null, null, null, null),
('cf823177-ef21-414d-9603-fcad6f3a9980', 'reading_comprehension', 'grade_3', 'developing', 'multiple_choice', 'The words "his ears flat against his head" show that Milo is:', '["frightened","excited","sleepy","hungry"]'::jsonb, 0, 'Flattened ears are a sign of fear, which matches his hiding from the storm.', 'AC9E3LY05', '7867377c-4512-4aeb-86d9-f8178306590f', null, true, null, null, null, null),
('75e18f9f-31e9-4f3f-a18a-d713d94b8368', 'reading_comprehension', 'grade_3', 'proficient', 'multiple_choice', 'Why does Ava talk about lunch and her loose tooth?', '["She wants Milo to answer her.","She is trying to make him hungry.","The topic does not matter — her calm voice is what comforts him.","She has forgotten about the storm."]'::jsonb, 2, 'The text says she talks "about anything at all", so it is the quiet voice rather than the subject that helps.', 'AC9E3LY05', '7867377c-4512-4aeb-86d9-f8178306590f', null, true, null, null, null, null),
('27f94887-36db-4484-8cf3-abe8908b1eb5', 'reading_comprehension', 'grade_3', 'proficient', 'multiple_choice', 'What does Ava mean when she says "But it always stops"?', '["The rain never lasts long in summer.","Storms end, so the fear will pass too.","Milo should stop being noisy.","The thunder has already finished."]'::jsonb, 1, 'She is reassuring Milo that the storm, and his fear of it, will not last.', 'AC9E3LY05', '7867377c-4512-4aeb-86d9-f8178306590f', null, true, null, null, null, null),
('a6532c92-a844-4658-91e2-a810504a629e', 'reading_comprehension', 'grade_5', 'foundation', 'multiple_choice', 'How long had the power been out when Dad brought down the games?', '["One hour","Three hours","Nine hours","Six hours"]'::jsonb, 3, 'The text opens: "The power had been out for six hours".', 'AC9E5LY05', '1c2ebf23-b84f-4060-b175-468df568df52', null, true, null, null, null, null),
('f51024ce-6683-4f2b-be0c-4718f620a769', 'reading_comprehension', 'grade_5', 'developing', 'multiple_choice', 'What did Nadia do during the first hour?', '["Played Scrabble","Lit the candles","Complained","Read a book"]'::jsonb, 2, 'The text says "Nadia had complained for the first hour."', 'AC9E5LY05', '1c2ebf23-b84f-4060-b175-468df568df52', null, true, null, null, null, null),
('5adb340a-85dc-491b-acd0-0b4e15aeef77', 'reading_comprehension', 'grade_5', 'developing', 'multiple_choice', 'Why is running out of things to complain about "its own kind of problem"?', '["She had nothing left to do or say.","Her family had stopped listening.","The power was about to come back.","She had lost the game."]'::jsonb, 0, 'Complaining had been occupying her; without it she is left with nothing to fill the time.', 'AC9E5LY05', '1c2ebf23-b84f-4060-b175-468df568df52', null, true, null, null, null, null),
('ddc267dd-838c-45f7-be55-f640e7b25b03', 'reading_comprehension', 'grade_5', 'proficient', 'multiple_choice', 'What does the description of Dad’s laugh tell the reader?', '["He was pretending to enjoy himself.","He laughed like this often.","He was laughing at Nadia.","He was more relaxed than he had been for some time."]'::jsonb, 3, 'It is contrasted with "the polite laugh he used on the phone" and described as one Nadia "had not heard for a while".', 'AC9E5LY05', '1c2ebf23-b84f-4060-b175-468df568df52', null, true, null, null, null, null),
('8f05a28b-5463-4164-8f19-e3c08485e5ba', 'reading_comprehension', 'grade_5', 'proficient', 'multiple_choice', 'Why does nobody move when the lights come back on?', '["They are asleep.","They are enjoying the evening as it is.","They cannot see the switch.","The game is not finished."]'::jsonb, 1, 'The evening has become enjoyable, so Reza suggests leaving the lights off and "Nobody argued".', 'AC9E5LY05', '1c2ebf23-b84f-4060-b175-468df568df52', null, true, null, null, null, null),
('0a776fd7-5de2-44fa-92bf-7be27654cee9', 'reading_comprehension', 'grade_5', 'proficient', 'multiple_choice', 'Which statement best describes how Nadia changes during the story?', '["She becomes more annoyed as the night goes on.","She moves from complaining to quietly enjoying the evening.","She decides she prefers her tablet.","She becomes frightened of the storm."]'::jsonb, 1, 'She begins by complaining about everything and ends by not wanting the evening to end.', 'AC9E5LY05', '1c2ebf23-b84f-4060-b175-468df568df52', null, true, null, null, null, null),
('54512cfd-65e3-413d-a65d-1eca604f829e', 'reading_comprehension', 'grade_5', 'foundation', 'multiple_choice', 'According to the text, what is the most important thing bees do?', '["Make honey","Build hives","Produce wax","Pollinate plants"]'::jsonb, 3, 'The text opens by saying honey "is the least important thing bees give us" and then explains pollination.', 'AC9E5LY05', '16ee5def-8c3d-4ec3-b80b-d4f026f452ee', null, true, null, null, null, null),
('869178ca-7dc0-41e8-850b-b095d8140745', 'reading_comprehension', 'grade_5', 'developing', 'multiple_choice', 'How does pollen move from one flower to another?', '["It sticks to a bee’s body and rubs off on the next flower.","It is blown by the wind.","It falls into the soil.","It is carried in the bee’s honey."]'::jsonb, 0, 'The text says "grains of pollen stick to its body and rub off on the next flower it visits".', 'AC9E5LY05', '16ee5def-8c3d-4ec3-b80b-d4f026f452ee', null, true, null, null, null, null),
('3f2e99d2-2f8c-4a62-93e8-1312b732c11b', 'reading_comprehension', 'grade_5', 'developing', 'multiple_choice', 'How much of our food depends on a pollinator?', '["About half","Almost all of it","About one mouthful in three","Only honey"]'::jsonb, 2, 'The text says "roughly one in every three mouthfuls of food we eat depends on a pollinator".', 'AC9E5LY05', '16ee5def-8c3d-4ec3-b80b-d4f026f452ee', null, true, null, null, null, null),
('15206f82-aa4d-4953-8046-b89da9c2d46a', 'reading_comprehension', 'grade_5', 'proficient', 'multiple_choice', 'Why does the writer mention almond trees?', '["To show almonds are expensive","To explain how almonds are harvested","To suggest planting almond trees","To give a clear example of a crop that fails without bees"]'::jsonb, 3, 'It is used as evidence: "A field of almond trees without bees produces almost no almonds at all."', 'AC9E5LY05', '16ee5def-8c3d-4ec3-b80b-d4f026f452ee', null, true, null, null, null, null),
('3949e2dd-1d39-4049-80f2-120136aab3e3', 'reading_comprehension', 'grade_5', 'proficient', 'multiple_choice', 'Which of these is NOT given as a cause of falling bee numbers?', '["Loss of wildflower habitat","Too much rainfall","Certain pesticides","Disease spread by mites"]'::jsonb, 1, 'The text lists habitat loss, pesticides and mite-borne disease. Rainfall is not mentioned.', 'AC9E5LY05', '16ee5def-8c3d-4ec3-b80b-d4f026f452ee', null, true, null, null, null, null),
('98020513-4cad-4dde-99c3-346854e34de8', 'reading_comprehension', 'grade_5', 'proficient', 'multiple_choice', 'Why does the writer suggest planting flowers that bloom at different times?', '["So the garden looks colourful all year","So the flowers do not compete","So bees have food across more of the season","So the plants need less water"]'::jsonb, 2, 'The text says this "gives bees food across more of the season".', 'AC9E5LY05', '16ee5def-8c3d-4ec3-b80b-d4f026f452ee', null, true, null, null, null, null),
('437a8f6f-2538-4cba-b1fb-e6de1408722d', 'reading_literary_analysis', 'year_7', 'developing', 'multiple_choice', 'How long has it been since Tam last swam?', '["Eleven days","Eleven weeks","Eleven months","Eleven years"]'::jsonb, 2, 'The text opens: "Tam had not been in the water for eleven months".', 'AC9E7LY05', '0cf4fc4d-619a-43a9-b63e-b5547d0cc999', null, true, null, null, null, null),
('e1bd59e0-2eb4-4c41-8806-6a5768fc8bfe', 'reading_literary_analysis', 'year_7', 'proficient', 'multiple_choice', 'What does the sentence "the pool did not care" suggest?', '["Nothing about the pool had changed to match what Tam had been through.","The pool was badly maintained.","Tam no longer enjoyed swimming.","The other swimmers ignored her."]'::jsonb, 0, 'It sets up the following paragraph: everything is as she left it, and "She was the only thing that had changed."', 'AC9E7LY05', '0cf4fc4d-619a-43a9-b63e-b5547d0cc999', null, true, null, null, null, null),
('d0ad5e98-fa05-47be-ada7-d572d9a4dada', 'reading_literary_analysis', 'year_7', 'proficient', 'multiple_choice', 'What is the effect of comparing the first fifty metres to "stepping into a room she knew in the dark"?', '["It shows she was frightened.","It shows the pool was poorly lit.","It shows she had forgotten how to swim.","It shows her body moved from memory, without thinking."]'::jsonb, 3, 'Moving confidently through a familiar dark room is done from memory rather than sight — as her stroke is at first.', 'AC9E7LY05', '0cf4fc4d-619a-43a9-b63e-b5547d0cc999', null, true, null, null, null, null),
('60dc248f-cb5c-4769-bc59-bca8b4491f6c', 'reading_literary_analysis', 'year_7', 'proficient', 'multiple_choice', 'Why does the writer describe the coach as "not writing anything down"?', '["The coach had lost interest.","It signals that this swim was not being assessed on time.","The coach had forgotten her notebook.","The coach was angry with Tam."]'::jsonb, 1, 'The text calls it "its own kind of message" — the session is not about the numbers.', 'AC9E7LY05', '0cf4fc4d-619a-43a9-b63e-b5547d0cc999', null, true, null, null, null, null),
('364a0d18-1599-41f7-a291-21ca2bc3d45e', 'reading_literary_analysis', 'year_7', 'advanced', 'multiple_choice', 'Why is the phrase "worn smooth from use" effective in describing Tam’s old answer?', '["It suggests Tam is a dishonest person.","It suggests the answer is comfortable and polished from being repeated so often.","It suggests the answer is difficult to say.","It suggests Tam has forgotten the answer."]'::jsonb, 1, 'Something worn smooth has been handled repeatedly — like a reply given so many times it comes automatically.', 'AC9E7LY05', '0cf4fc4d-619a-43a9-b63e-b5547d0cc999', null, true, null, null, null, null),
('05830790-f1fb-4089-8d41-39b3909a48cb', 'reading_literary_analysis', 'year_7', 'advanced', 'multiple_choice', 'Why does the coach respond with "Good" when Tam says the swim was slow?', '["She is being sarcastic.","She thinks Tam swam well.","She had expected a worse result.","She values the honest answer more than a fast time."]'::jsonb, 3, 'Her face eases at the honesty — "the answer she had been waiting eleven months to hear" — because it gives them "something to work with".', 'AC9E7LY05', '0cf4fc4d-619a-43a9-b63e-b5547d0cc999', null, true, null, null, null, null),
('90d962c5-a88b-44f4-9841-ebaf343948df', 'reading_literary_analysis', 'year_7', 'developing', 'multiple_choice', 'According to the text, what happens to melatonin release during adolescence?', '["It begins later in the evening.","It stops completely.","It begins earlier in the evening.","It doubles in quantity."]'::jsonb, 0, 'The text says melatonin "begins to be released later in the evening than it does in childhood or adulthood".', 'AC9E7LY05', '10c6cfac-60bf-4782-b260-bf848910eba1', null, true, null, null, null, null),
('dc2d1a3a-8200-4c46-9d07-9111f2aa9540', 'reading_literary_analysis', 'year_7', 'proficient', 'multiple_choice', 'Why does the writer say this is "not a matter of willpower or screen time"?', '["To blame parents for the problem","To argue that screens are harmless","To establish that the shift is biological and not a choice","To suggest teenagers should try harder"]'::jsonb, 2, 'The point is that the change is physiological, so it cannot be fixed by discipline.', 'AC9E7LY05', '10c6cfac-60bf-4782-b260-bf848910eba1', null, true, null, null, null, null),
('2330f5f4-e86c-40f3-b196-c50c5dc2ea77', 'reading_literary_analysis', 'year_7', 'proficient', 'multiple_choice', 'What does the writer mean by "straightforward arithmetic"?', '["The maths taught in schools is simple.","Schools should teach more maths.","The research involves complex calculations.","Adding up sleep need and bedtime shows the shortfall clearly."]'::jsonb, 3, 'Teenagers need 8-10 hours; sleep starting at eleven and a 7 am alarm gives eight at best.', 'AC9E7LY05', '10c6cfac-60bf-4782-b260-bf848910eba1', null, true, null, null, null, null),
('eb09770e-c95d-4278-98ac-006bd4d3885f', 'reading_literary_analysis', 'year_7', 'proficient', 'multiple_choice', 'Which piece of evidence does the writer use about teenage drivers?', '["Teenagers drive more often when tired.","A district that started later recorded fewer car accidents.","Teenage drivers cause most accidents.","Driving tests should start later."]'::jsonb, 1, 'The text cites a district moving its start from 7.30 to 8.45 and recording "a measurable drop in car accidents involving teenage drivers".', 'AC9E7LY05', '10c6cfac-60bf-4782-b260-bf848910eba1', null, true, null, null, null, null),
('b3f09748-e0d3-48ff-83b8-a1d7c7328c32', 'reading_literary_analysis', 'year_7', 'advanced', 'multiple_choice', 'How does the writer treat the objections to later start times?', '["They are dismissed as unimportant.","They are ignored entirely.","They are acknowledged as real but described as solvable.","They are shown to be scientifically wrong."]'::jsonb, 2, 'The text calls them "real difficulties" but then argues "logistical problems can be solved".', 'AC9E7LY05', '10c6cfac-60bf-4782-b260-bf848910eba1', null, true, null, null, null, null),
('3e40619c-b218-44a5-b3ff-ce1e90654e09', 'reading_literary_analysis', 'year_7', 'advanced', 'multiple_choice', 'What is the effect of the final sentence?', '["It reframes the issue as one of fairness — adults benefiting at students’ expense.","It softens the argument with a compromise.","It introduces new scientific evidence.","It admits the writer may be wrong."]'::jsonb, 0, 'It shifts from practicality to fairness: the day suits "the convenience of adults" while adolescents "absorb the cost".', 'AC9E7LY05', '10c6cfac-60bf-4782-b260-bf848910eba1', null, true, null, null, null, null),
('00a0264e-ccf1-431e-9786-0f71f4db9ccc', 'reading_literary_analysis', 'year_9', 'developing', 'multiple_choice', 'What did the narrator’s siblings take from the house?', '["The buttons and the string","The Christmas cards","The photographs and the tools","Nothing at all"]'::jsonb, 2, 'The text states: "My sister took the photographs. My brother took the tools."', 'AC9E9LY05', '6b8cc8f3-d4da-4540-89d3-a8179f35f430', null, true, null, null, null, null),
('5c1dde5f-47bc-49b2-9cdf-cf5e4a92eca6', 'reading_literary_analysis', 'year_9', 'proficient', 'multiple_choice', 'Why does the narrator describe what their mother left as "not valuable and not junk"?', '["Because that category is hardest to make decisions about","Because the items were damaged","Because the items belonged to someone else","Because the agent had already sorted them"]'::jsonb, 0, 'The narrator calls it "the hardest category" — items that resist both keeping and discarding.', 'AC9E9LY05', '6b8cc8f3-d4da-4540-89d3-a8179f35f430', null, true, null, null, null, null),
('0eb1bdba-385f-4f9a-a8fe-9210b4e87dca', 'reading_literary_analysis', 'year_9', 'proficient', 'multiple_choice', 'What does the narrator suggest by saying the habit "had outlasted the conditions that produced it by fifty years"?', '["The mother was forgetful.","The mother had lived through fifty years of scarcity.","The habit was learned from television.","The behaviour made sense originally but continued after the need had passed."]'::jsonb, 3, 'The saving made sense in a period "when nothing arrived twice"; it persisted long after those conditions ended.', 'AC9E9LY05', '6b8cc8f3-d4da-4540-89d3-a8179f35f430', null, true, null, null, null, null),
('517e9b0c-9b95-4ca1-b2d2-77e0c7c1f40d', 'reading_literary_analysis', 'year_9', 'advanced', 'multiple_choice', 'What is the narrator’s attitude to the television programmes mentioned?', '["Approving — they provide a useful service.","Critical — they treat the behaviour as a symptom without understanding its origin.","Indifferent — the narrator has never seen one.","Amused — the narrator finds them entertaining."]'::jsonb, 1, 'The narrator notes they speak of clutter "as though it were a symptom" and that none "quite addresses" that the string was not irrational.', 'AC9E9LY05', '6b8cc8f3-d4da-4540-89d3-a8179f35f430', null, true, null, null, null, null),
('dd52e21c-e64c-4eee-85cb-5f36b6a4453a', 'reading_literary_analysis', 'year_9', 'advanced', 'multiple_choice', 'Why does the narrator state plainly, "I did not keep the string"?', '["To show the narrator disliked their mother.","To refuse a neater, more sentimental ending.","To explain what happened to the box.","To suggest the string had no value."]'::jsonb, 1, 'The narrator says so directly "because it would be a tidier ending if I had" — resisting sentimentality.', 'AC9E9LY05', '6b8cc8f3-d4da-4540-89d3-a8179f35f430', null, true, null, null, null, null),
('92dd4384-36ef-419a-9987-50919828886f', 'reading_literary_analysis', 'year_9', 'advanced', 'multiple_choice', 'What does the phrase "understanding, slightly too late" contribute to the ending?', '["It suggests the narrator has forgiven their mother.","It suggests the narrator misread the situation.","It suggests the narrator will return to the house.","It suggests the insight arrived only after the chance to act on it had gone."]'::jsonb, 3, 'The understanding comes after the mother’s death and after the house is sold — too late to change anything.', 'AC9E9LY05', '6b8cc8f3-d4da-4540-89d3-a8179f35f430', null, true, null, null, null, null),
('651173e8-28b0-4186-80cc-863133c94736', 'reading_literary_analysis', 'year_9', 'developing', 'multiple_choice', 'What is the "familiar argument" the writer describes in the opening paragraph?', '["That since reading is declining, what people read does not matter","That difficult books should be taught in schools","That reading is no longer in decline","That literary critics should choose what people read"]'::jsonb, 0, 'The opening summarises the argument that "anything that gets people reading is good, therefore we should stop worrying about what they read".', 'AC9E9LY05', '9f8cf3c2-c413-465b-b107-5c193b2c7fab', null, true, null, null, null, null),
('76076063-6220-4a4a-bd3e-48e1dd73d6a4', 'reading_literary_analysis', 'year_9', 'proficient', 'multiple_choice', 'How does the writer describe that argument?', '["Entirely wrong","Dishonest and self-serving","Generous, widely held, and incomplete","Old-fashioned and irrelevant"]'::jsonb, 2, 'The writer uses exactly those three words at the end of the first paragraph.', 'AC9E9LY05', '9f8cf3c2-c413-465b-b107-5c193b2c7fab', null, true, null, null, null, null),
('5680cb3b-69ba-4840-8c2d-c6e6484d13fc', 'reading_literary_analysis', 'year_9', 'proficient', 'multiple_choice', 'Why does the writer concede that "reading anything is better than reading nothing"?', '["To abandon their own argument","To show they rarely read","To criticise people who read for entertainment","To establish common ground before complicating it"]'::jsonb, 3, 'Granting the strongest version of the opposing case first makes the later distinction more persuasive.', 'AC9E9LY05', '9f8cf3c2-c413-465b-b107-5c193b2c7fab', null, true, null, null, null, null),
('7e2011bd-24f5-4380-9070-2cf909d56020', 'reading_literary_analysis', 'year_9', 'advanced', 'multiple_choice', 'According to the writer, what is a structure that withholds information doing?', '["Confusing the reader unnecessarily","Training the reader to tolerate not knowing","Hiding a weak plot","Making the book longer"]'::jsonb, 1, 'The text states it is "training you to tolerate not knowing".', 'AC9E9LY05', '9f8cf3c2-c413-465b-b107-5c193b2c7fab', null, true, null, null, null, null),
('e5453a42-fe8b-4dc5-9d2a-0cb06a0d53ca', 'reading_literary_analysis', 'year_9', 'advanced', 'multiple_choice', 'What does the writer mean by "we are currently living through a period in which almost every other force acting on our attention is training the opposite reflex"?', '["Most modern books are too difficult.","People have less free time than before.","Other media encourage quick agreement or dismissal rather than sustained engagement.","Attention spans cannot be trained."]'::jsonb, 2, 'The "opposite reflex" is the opposite of sitting with a complicated argument — that is, accepting or dismissing it immediately.', 'AC9E9LY05', '9f8cf3c2-c413-465b-b107-5c193b2c7fab', null, true, null, null, null, null),
('38e2ae16-12d1-4b82-92f1-4ab4b0d55dc4', 'reading_literary_analysis', 'year_9', 'advanced', 'multiple_choice', 'What distinction does the writer draw in the final paragraph?', '["Between finding a book dull and treating difficulty as the book’s failure","Between good books and bad books","Between reading and not reading","Between fiction and non-fiction"]'::jsonb, 0, 'The writer allows readers to find a book dull, but asks that difficulty not be described as "a failure of the book".', 'AC9E9LY05', '9f8cf3c2-c413-465b-b107-5c193b2c7fab', null, true, null, null, null, null),
('b37601dd-82f7-40b7-bca1-4a34217bb281', 'mm_calculus', 'year_12', 'proficient', 'extended_response', 'This question is about differentiation and antidifferentiation.', null, null, 'See the per-part marking guidance.', 'VCE-MM-U34-AOS3', null, false, true, null, null, '[{"label":"a","prompt":"Let y = x²e³ˣ. Find dy/dx.","marks":2,"expected_answer":"dy/dx = xe³ˣ(2 + 3x)","explanation":"Product rule with u = x² and v = e³ˣ: dy/dx = 2xe³ˣ + 3x²e³ˣ. One mark for applying the product rule, one for the simplified factorised form xe³ˣ(2 + 3x)."},{"label":"b","prompt":"Let f′(x) = (2x − 3)⁴. Find f(x), given that f(2) = 1.","marks":2,"expected_answer":"f(x) = (2x − 3)⁵/10 + 9/10","explanation":"Antidifferentiate: f(x) = (2x − 3)⁵/10 + c (one mark). Substituting f(2) = 1 gives 1/10 + c = 1, so c = 9/10 (one mark)."}]'::jsonb, null),
('1c5cdf4e-ff0a-41c2-b549-838e7cd93226', 'mm_functions', 'year_12', 'proficient', 'extended_response', 'The graph of y = m/(x − a) + c has a vertical asymptote at x = 2, a y-intercept at (0, 3) and an x-intercept at (−1, 0), where a, c and m are integers.', null, null, 'See the per-part marking guidance.', 'VCE-MM-U34-AOS1', null, false, true, null, null, '[{"label":"a","prompt":"State the value of a.","marks":1,"expected_answer":"a = 2","explanation":"The vertical asymptote of y = m/(x − a) + c is x = a, and the asymptote is given as x = 2."},{"label":"b","prompt":"Find the values of m and c.","marks":2,"expected_answer":"m = −18 and c = −6","explanation":"The y-intercept gives −m/2 + c = 3 and the x-intercept gives m/(−3) + c = 0, so c = m/3. Substituting: −m/2 + m/3 = 3, so −m/6 = 3 and m = −18, giving c = −6. One mark for setting up both equations, one for solving."}]'::jsonb, null),
('b42e7597-1321-478d-b2b8-44419f82d673', 'mm_probability', 'year_12', 'proficient', 'extended_response', 'The discrete random variable X has the probability distribution shown below.
x:        0     1     2     3
Pr(X = x): 0.1   0.3    k    0.2', null, null, 'See the per-part marking guidance.', 'VCE-MM-U34-AOS4', null, false, true, null, null, '[{"label":"a","prompt":"Find the value of k.","marks":1,"expected_answer":"k = 0.4","explanation":"The probabilities must sum to 1: 0.1 + 0.3 + k + 0.2 = 1, so k = 0.4."},{"label":"b","prompt":"Find E(X).","marks":2,"expected_answer":"E(X) = 1.7","explanation":"E(X) = 0(0.1) + 1(0.3) + 2(0.4) + 3(0.2) = 0.3 + 0.8 + 0.6 = 1.7. One mark for the correct sum of products, one for the value."},{"label":"c","prompt":"Find Pr(X ≥ 2 | X ≥ 1).","marks":2,"expected_answer":"2/3","explanation":"Pr(X ≥ 2) = 0.4 + 0.2 = 0.6 and Pr(X ≥ 1) = 0.3 + 0.4 + 0.2 = 0.9. Since {X ≥ 2} is contained in {X ≥ 1}, the conditional probability is 0.6/0.9 = 2/3. One mark for each probability, or one for the correct quotient set up."}]'::jsonb, null),
('7a715ae4-bee8-4ceb-ae6d-d874b5f775b3', 'mm_functions', 'year_12', 'proficient', 'extended_response', 'Consider the function with rule y = 2sin(3x).', null, null, 'See the per-part marking guidance.', 'VCE-MM-U34-AOS1', null, false, true, null, null, '[{"label":"a","prompt":"State the period of the function.","marks":1,"expected_answer":"2π/3","explanation":"The period of y = a·sin(nx) is 2π/n, and here n = 3."},{"label":"b","prompt":"Solve 2sin(3x) = √3 for x, where x ∈ [0, π].","marks":3,"expected_answer":"x = π/9, 2π/9, 7π/9, 8π/9","explanation":"sin(3x) = √3/2. For x ∈ [0, π] the argument 3x ranges over [0, 3π], where sin θ = √3/2 has solutions θ = π/3, 2π/3, 7π/3 and 8π/3. Dividing each by 3 gives the four values. One mark for sin(3x) = √3/2, one for the correct domain for 3x, one for all four solutions."}]'::jsonb, null),
('a11b9cff-d9e9-4828-9a05-ab1981fc01ab', 'mm_calculus', 'year_12', 'proficient', 'extended_response', 'Let f(x) = 3x² − 6x.', null, null, 'See the per-part marking guidance.', 'VCE-MM-U34-AOS3', null, false, true, null, null, '[{"label":"a","prompt":"Find the x-intercepts of the graph of f.","marks":2,"expected_answer":"x = 0 and x = 2","explanation":"Factorise: 3x(x − 2) = 0. One mark for the factorisation, one for both intercepts."},{"label":"b","prompt":"Find the area of the region enclosed by the graph of f and the x-axis.","marks":3,"expected_answer":"4 square units","explanation":"The graph lies below the axis between the intercepts, so the area is the absolute value of the integral. ∫₀²(3x² − 6x)dx = [x³ − 3x²]₀² = (8 − 12) − 0 = −4, giving an area of 4. One mark for the correct integral and terminals, one for evaluating it, one for taking the absolute value."}]'::jsonb, null),
('41f22583-fa27-44fd-be38-4942d516d804', 'mm_functions', 'year_12', 'advanced', 'extended_response', 'Let f: (1, ∞) → R, f(x) = 2logₑ(x − 1).', null, null, 'See the per-part marking guidance.', 'VCE-MM-U34-AOS1', null, false, true, null, null, '[{"label":"a","prompt":"Find the rule for f⁻¹.","marks":2,"expected_answer":"f⁻¹(x) = e^(x/2) + 1","explanation":"Swap and solve: x = 2logₑ(y − 1), so x/2 = logₑ(y − 1) and y = e^(x/2) + 1. One mark for isolating the logarithm, one for the correct rule."},{"label":"b","prompt":"State the domain and range of f⁻¹.","marks":2,"expected_answer":"Domain R, range (1, ∞)","explanation":"The domain of the inverse is the range of f, which is R, and the range of the inverse is the domain of f, which is (1, ∞). One mark each."}]'::jsonb, null),
('e03c8612-e047-483b-b344-785ff461aded', 'mm_calculus', 'year_12', 'advanced', 'extended_response', 'Let f(x) = x³ − 4x.', null, null, 'See the per-part marking guidance.', 'VCE-MM-U34-AOS3', null, false, true, null, null, '[{"label":"a","prompt":"Find the equation of the tangent to the graph of f at x = 1.","marks":2,"expected_answer":"y = −x − 2","explanation":"f(1) = −3 and f′(x) = 3x² − 4, so f′(1) = −1. The tangent is y + 3 = −1(x − 1), that is y = −x − 2. One mark for the gradient, one for the equation."},{"label":"b","prompt":"Find the coordinates of the other point where this tangent meets the graph of f.","marks":3,"expected_answer":"(−2, 0)","explanation":"Solve x³ − 4x = −x − 2, giving x³ − 3x + 2 = 0. Since x = 1 is a known solution it factorises as (x − 1)²(x + 2) = 0, so the other solution is x = −2, where y = 0. One mark for forming the equation, one for the factorisation, one for the coordinates."}]'::jsonb, null),
('e2382b12-c1da-43f2-907e-50d6812932e9', 'mm_algebra', 'year_12', 'advanced', 'extended_response', 'This question concerns exponential and logarithmic equations.', null, null, 'See the per-part marking guidance.', 'VCE-MM-U34-AOS2', null, false, true, null, null, '[{"label":"a","prompt":"Solve 2²ˣ − 5(2ˣ) + 4 = 0 for x.","marks":2,"expected_answer":"x = 0 and x = 2","explanation":"Let u = 2ˣ, giving u² − 5u + 4 = 0 and (u − 1)(u − 4) = 0, so u = 1 or u = 4. Then 2ˣ = 1 gives x = 0 and 2ˣ = 4 gives x = 2. One mark for the substitution, one for both solutions."},{"label":"b","prompt":"Solve logₑ(x) + logₑ(x − 3) = logₑ(4) for x.","marks":3,"expected_answer":"x = 4","explanation":"Combine to logₑ(x(x − 3)) = logₑ(4), so x² − 3x − 4 = 0 and (x − 4)(x + 1) = 0. Both logarithms require x > 3, so x = −1 is rejected and x = 4 is the only solution. One mark for combining, one for solving the quadratic, one for rejecting x = −1 on domain grounds."}]'::jsonb, null),
('83ade8ca-9359-473d-8184-7c8ec080f440', 'mm_probability', 'year_12', 'advanced', 'extended_response', 'The continuous random variable X has probability density function f(x) = kx for 0 ≤ x ≤ 4, and f(x) = 0 elsewhere.', null, null, 'See the per-part marking guidance.', 'VCE-MM-U34-AOS4', null, false, true, null, null, '[{"label":"a","prompt":"Find the value of k.","marks":2,"expected_answer":"k = 1/8","explanation":"The total area under a probability density function is 1: ∫₀⁴ kx dx = k[x²/2]₀⁴ = 8k = 1, so k = 1/8. One mark for setting the integral equal to 1, one for the value."},{"label":"b","prompt":"Find Pr(X ≤ 2).","marks":3,"expected_answer":"1/4","explanation":"Pr(X ≤ 2) = ∫₀² (1/8)x dx = (1/8)[x²/2]₀² = (1/8)(2) = 1/4. One mark for the correct integral, one for the terminals, one for the value."}]'::jsonb, null),
('6d5fb2fa-1c54-4508-b5ca-f106eadb12fa', 'mm_functions', 'year_12', 'proficient', 'multiple_choice', 'The period of the function with rule y = −3tan(2x/3) + 1 is', '["2π/3","π/3","3π/2","3π","π/2"]'::jsonb, 2, 'The period of tan(kx) is π/|k|. Here k = 2/3, so the period is π ÷ (2/3) = 3π/2. The dilation factor −3 and the translation of 1 unit up do not affect the period.', 'VCE-MM-U34-AOS1', null, true, true, null, null, null, 1),
('9b29536f-b939-4b9b-9188-60e2cceb05fc', 'mm_functions', 'year_12', 'proficient', 'multiple_choice', 'Let f(x) = 1/(x − 3) + 2. The range of f is', '["R \\ {2}","R \\ {3}","(2, ∞)","R \\ {−2}","R"]'::jsonb, 0, 'The graph of y = 1/x has range R \ {0}. Translating 3 units right does not change the range; translating 2 units up shifts it to R \ {2}. The horizontal asymptote y = 2 is the excluded value.', 'VCE-MM-U34-AOS1', null, true, true, null, null, null, 1),
('534a9248-8e87-4ed9-bf89-d763705c2fed', 'mm_algebra', 'year_12', 'proficient', 'multiple_choice', 'The solution of 2log₃(x) − log₃(x + 4) = 1 is', '["(3 − √57)/2","4","both (3 − √57)/2 and (3 + √57)/2","there is no real solution","(3 + √57)/2"]'::jsonb, 4, 'Combining the logarithms gives log₃(x²/(x + 4)) = 1, so x² = 3(x + 4), giving x² − 3x − 12 = 0 and x = (3 ± √57)/2. The logarithm log₃(x) requires x > 0, and (3 − √57)/2 is negative, so only x = (3 + √57)/2 is a solution.', 'VCE-MM-U34-AOS2', null, true, true, null, null, null, 1),
('6e74f584-ca26-4028-90a3-cf198116dbdc', 'mm_algebra', 'year_12', 'advanced', 'multiple_choice', 'Consider the system of simultaneous linear equations kx + 4y = 8 and 3x + (k − 1)y = k, where k is a real constant. The system has no solution when', '["k = 4 only","k ∈ {−3, 4}","k = −3 only","k ∈ R \\ {−3, 4}","no value of k"]'::jsonb, 1, 'A unique solution exists when the determinant k(k − 1) − 12 is non-zero. Setting it to zero gives k² − k − 12 = 0, so k = 4 or k = −3. Substituting k = 4 gives x + y = 2 and x + y = 4/3, which are inconsistent; k = −3 gives −3x + 4y = 8 and −3x + 4y = 3, also inconsistent. Both values give no solution.', 'VCE-MM-U34-AOS2', null, true, true, null, null, null, 1),
('c66d65d3-6012-4ad7-a370-e698e88f2f9b', 'mm_calculus', 'year_12', 'proficient', 'multiple_choice', 'If f(x) = xlogₑ(x), where x > 0, then f′(e²) is equal to', '["1","2","e²","3","2e²"]'::jsonb, 3, 'By the product rule, f′(x) = logₑ(x) + x × (1/x) = logₑ(x) + 1. So f′(e²) = 2 + 1 = 3.', 'VCE-MM-U34-AOS3', null, true, true, null, null, null, 1),
('3d94b57d-947f-4bac-83c5-5c1df1fa095b', 'mm_calculus', 'year_12', 'proficient', 'multiple_choice', 'The average value of the function f(x) = 4x − x² over the interval [0, 3] is', '["3","9","4","27","1"]'::jsonb, 0, 'The average value is (1/3)∫(4x − x²)dx from 0 to 3. The antiderivative is 2x² − x³/3, which gives 18 − 9 = 9 over the interval, and 9 ÷ 3 = 3.', 'VCE-MM-U34-AOS3', null, true, true, null, null, null, 1),
('71bc6802-7458-400b-a695-bc6f8606bca4', 'mm_probability', 'year_12', 'proficient', 'multiple_choice', 'The random variable X has a binomial distribution with n = 10 and p = 0.3. Correct to four decimal places, Pr(X ≥ 2) is', '["0.1493","0.2335","0.3828","0.6172","0.8507"]'::jsonb, 4, 'Pr(X ≥ 2) = 1 − Pr(X = 0) − Pr(X = 1) = 1 − 0.0282 − 0.1211 = 0.8507. The other options are Pr(X ≤ 1), Pr(X = 2), Pr(X ≤ 2) and Pr(X ≥ 3).', 'VCE-MM-U34-AOS4', null, true, true, null, null, null, 1),
('67dad046-4b2f-46ba-bf52-27b727558203', 'mm_functions', 'year_12', 'proficient', 'multiple_choice', 'Part of the graph of a cubic function y = f(x) is shown below. A possible rule for f is', '["y = (x − 1)(x + 2)²","y = (x + 1)²(x − 2)","y = (x + 1)(x − 2)²","y = −(x + 1)(x − 2)²","y = (x + 1)(x + 2)²"]'::jsonb, 2, 'The graph crosses the x-axis at x = −1 and touches it at x = 2, so the factors are (x + 1) and (x − 2)². The y-intercept is 4, and (0 + 1)(0 − 2)² = 4, which confirms the leading coefficient is 1.', 'VCE-MM-U34-AOS1', null, true, true, null, null, null, 1),
('d2260e25-83c0-4584-9191-94587e5c00a1', 'mm_calculus', 'year_12', 'advanced', 'multiple_choice', 'The graph below shows y = f′(x), the derivative of a function f. The graph of y = f(x) has a local maximum at', '["x = −3","x = −1","x = 1","x = 3","f has no local maximum"]'::jsonb, 1, 'A local maximum of f occurs where f′ changes from positive to negative. The graph of f′ is above the axis for x < −1 and below it for −1 < x < 3, so the change happens at x = −1. At x = 3 the derivative changes from negative to positive, which gives a local minimum.', 'VCE-MM-U34-AOS3', null, true, true, null, null, null, 1),
('aa91d514-6c8e-4cb4-8d8e-b33da807949b', 'mm_probability', 'year_12', 'advanced', 'multiple_choice', 'The random variable X is normally distributed with a mean of 72 and a standard deviation of 8. Correct to four decimal places, Pr(X > 80 | X > 64) is', '["0.1587","0.3173","0.6827","0.1886","0.8413"]'::jsonb, 3, 'Because the event X > 80 lies inside the event X > 64, the conditional probability is Pr(X > 80) ÷ Pr(X > 64). Standardising gives Pr(Z > 1) = 0.1587 and Pr(Z > −1) = 0.8413, and 0.1587 ÷ 0.8413 = 0.1886.', 'VCE-MM-U34-AOS4', null, true, true, null, null, null, 1),
('18148677-e6ab-4743-b277-9baa12e8a208', 'mm_probability', 'year_12', 'proficient', 'multiple_choice', 'A population proportion is p = 0.4. Random samples of size 25 are taken from this population. Correct to three decimal places, the standard deviation of the distribution of the sample proportion is', '["0.0096","0.049","0.24","0.4","0.098"]'::jsonb, 4, 'The standard deviation of the sample proportion is the square root of p(1 − p)/n. Here p(1 − p)/n = 0.4 × 0.6 ÷ 25 = 0.0096, and the square root of 0.0096 is 0.098.', 'VCE-MM-U34-AOS4', null, true, true, null, null, null, 1),
('2cf8bb95-59ae-485d-955d-7240d972e3a2', 'mm_functions', 'year_12', 'proficient', 'multiple_choice', 'Let f: [2, ∞) → R, f(x) = (x − 2)² + 3. The rule for the inverse function f⁻¹ is', '["f⁻¹(x) = 2 + √(x − 3)","f⁻¹(x) = 2 − √(x − 3)","f⁻¹(x) = √(x − 2) + 3","f⁻¹(x) = (x − 3)² + 2","f⁻¹(x) = 1/((x − 2)² + 3)"]'::jsonb, 0, 'Swapping x and y gives x = (y − 2)² + 3, so y = 2 ± √(x − 3). The domain of f is [2, ∞), which is the range of f⁻¹, so the positive square root is taken: f⁻¹(x) = 2 + √(x − 3).', 'VCE-MM-U34-AOS1', null, true, true, null, null, null, 1),
('c2bb15dd-8f40-4b99-b18b-ca9a5ee85b4c', 'mm_functions', 'year_12', 'proficient', 'multiple_choice', 'The graph of y = e^x is dilated by a factor of 1/2 from the y-axis and then translated 3 units in the positive direction of the y-axis. The rule of the image is', '["y = e^(x/2) + 3","y = 2e^x + 3","y = e^(2x + 3)","y = e^(2x) + 3","y = e^(2(x + 3))"]'::jsonb, 3, 'A dilation of factor 1/2 from the y-axis replaces x with 2x, giving y = e^(2x). Translating 3 units up adds 3, giving y = e^(2x) + 3. Option A applies a dilation of factor 2 instead, and option C translates in the x-direction.', 'VCE-MM-U34-AOS1', null, true, true, null, null, null, 1),
('d063bb81-dae8-4d82-9873-bf3152ea620b', 'mm_calculus', 'year_12', 'proficient', 'multiple_choice', 'The equation of the tangent to the curve y = x³ − 3x² + 2 at the point where x = 1 is', '["y = 3x − 3","y = −3x + 3","y = −3x","y = −3x − 3","y = −x + 1"]'::jsonb, 1, 'At x = 1, y = 1 − 3 + 2 = 0, so the point is (1, 0). The derivative is 3x² − 6x, which is 3 − 6 = −3 at x = 1. The tangent is y − 0 = −3(x − 1), that is y = −3x + 3.', 'VCE-MM-U34-AOS3', null, true, true, null, null, null, 1),
('487dcb2c-afdc-47dd-a492-e6166c0c2550', 'mm_calculus', 'year_12', 'proficient', 'multiple_choice', 'The area of the region enclosed by the graphs of y = x² and y = 2x is', '["2/3","2","4/3","8/3","4"]'::jsonb, 2, 'The graphs meet where x² = 2x, that is at x = 0 and x = 2. Between these values the line lies above the parabola, so the area is the integral of 2x − x² from 0 to 2, which is 4 − 8/3 = 4/3.', 'VCE-MM-U34-AOS3', null, true, true, null, null, null, 1),
('65223e09-c630-4354-a695-c19045cc7026', 'mm_functions', 'year_12', 'proficient', 'multiple_choice', 'Let f(x) = √x, where x ≥ 0, and let g(x) = 4 − x². The maximal domain of the composite function f(g(x)) is', '["[0, 2]","[−2, 2]","R","[0, ∞)","[−4, 4]"]'::jsonb, 1, 'The composite f(g(x)) is defined only where the range of g lies in the domain of f, so 4 − x² ≥ 0. That gives x² ≤ 4, that is −2 ≤ x ≤ 2.', 'VCE-MM-U34-AOS1', null, true, true, null, null, null, 1),
('b2354060-14c0-463d-8923-0c18949ffb22', 'mm_probability', 'year_12', 'proficient', 'multiple_choice', 'The discrete random variable X takes the values 1, 2, 3 and 4 with probabilities k, 2k, 3k and 4k respectively. The expected value E(X) is', '["2","2.5","3.5","3","0.1"]'::jsonb, 3, 'The probabilities sum to 1, so 10k = 1 and k = 0.1. Then E(X) = 1 × 0.1 + 2 × 0.2 + 3 × 0.3 + 4 × 0.4 = 0.1 + 0.4 + 0.9 + 1.6 = 3.', 'VCE-MM-U34-AOS4', null, true, true, null, null, null, 1),
('98746c4e-05f7-4fe9-a7ee-bd758c39318c', 'mm_functions', 'year_12', 'proficient', 'multiple_choice', 'The number of solutions of the equation 2sin(2x) = 1 for x ∈ [0, 2π] is', '["4","2","3","6","8"]'::jsonb, 0, 'The equation becomes sin(2x) = 1/2. Writing u = 2x, u ranges over [0, 4π], which is two full periods of the sine function, and sin(u) = 1/2 has two solutions per period. So there are 4 solutions: x = π/12, 5π/12, 13π/12 and 17π/12.', 'VCE-MM-U34-AOS1', null, true, true, null, null, null, 1),
('13376ec0-08a6-4202-a679-42964bdc641e', 'mm_calculus', 'year_12', 'advanced', 'multiple_choice', 'A particle moves in a straight line so that its position, in metres, at time t seconds is x(t) = t³ − 6t² + 9t, t ≥ 0. The total distance travelled by the particle in the first 4 seconds is', '["4","8","16","20","12"]'::jsonb, 4, 'The velocity is 3t² − 12t + 9 = 3(t − 1)(t − 3), so the particle changes direction at t = 1 and t = 3. The positions are x(0) = 0, x(1) = 4, x(3) = 0 and x(4) = 4, so the distance travelled is 4 + 4 + 4 = 12 metres. The displacement is only 4 metres.', 'VCE-MM-U34-AOS3', null, true, true, null, null, null, 1),
('0bab3e8d-6d97-44f5-b06c-e165aea83e77', 'mm_probability', 'year_12', 'advanced', 'multiple_choice', 'In a random sample of 200 people, 70 preferred brand A. An approximate 95% confidence interval for the population proportion who prefer brand A, correct to four decimal places, is', '["(0.3163, 0.3837)","(0.2839, 0.3500)","(0.2839, 0.4161)","(0.3169, 0.3831)","(0.2185, 0.4815)"]'::jsonb, 2, 'The sample proportion is 70 ÷ 200 = 0.35. The standard error is the square root of 0.35 × 0.65 ÷ 200, which is 0.0337. The margin of error is 1.96 × 0.0337 = 0.0661, giving the interval (0.2839, 0.4161).', 'VCE-MM-U34-AOS4', null, true, true, null, null, null, 1),
('87190ce6-42e7-41aa-9f0d-b25bf595f169', 'mm_functions', 'year_12', 'proficient', 'extended_response', 'The depth of water in a harbour, in metres, t hours after midnight is modelled by the function d: [0, 24] → R, d(t) = 5 + 2.5sin(πt/6). The graph of y = d(t) is shown below.', null, null, 'See the per-part marking guidance.', 'VCE-MM-U34-AOS1', null, true, true, null, null, '[{"label":"a","prompt":"State the maximum and the minimum depth of water in the harbour, in metres.","marks":1,"expected_answer":"Maximum 7.5 m, minimum 2.5 m","explanation":"The sine function takes values between −1 and 1, so d ranges from 5 − 2.5 = 2.5 to 5 + 2.5 = 7.5. One mark for both values."},{"label":"b","prompt":"Find the period of d, in hours.","marks":1,"expected_answer":"12 hours","explanation":"The period of sin(kt) is 2π/k. Here k = π/6, so the period is 2π ÷ (π/6) = 12 hours."},{"label":"c","prompt":"Find the exact values of t in the interval [0, 12] for which the depth is 6.25 metres.","marks":2,"expected_answer":"t = 1 and t = 5","explanation":"Setting 5 + 2.5sin(πt/6) = 6.25 gives sin(πt/6) = 0.5, so πt/6 = π/6 or 5π/6, giving t = 1 and t = 5. One mark for reducing to sin(πt/6) = 0.5, one for both values."},{"label":"d","prompt":"A boat can only enter the harbour when the depth of water is at least 4 metres. Find the total number of hours during the 24-hour period for which the boat can enter the harbour. Give your answer correct to two decimal places.","marks":3,"expected_answer":"15.14 hours","explanation":"Solving d(t) ≥ 4 gives sin(πt/6) ≥ −0.4. Over one 12-hour period the depth is below 4 metres for 4.428 hours, so it is at least 4 metres for 7.572 hours. Over 24 hours this is 15.14 hours. One mark for the inequality, one for solving it over one period, one for doubling and rounding."},{"label":"e","prompt":"Find the exact rate of change of the depth, in metres per hour, when t = 2.","marks":2,"expected_answer":"5π/24 metres per hour","explanation":"Differentiating gives d′(t) = (5π/12)cos(πt/6). At t = 2, cos(π/3) = 0.5, so d′(2) = 5π/24, which is about 0.65 metres per hour. One mark for the derivative, one for the exact value."},{"label":"f","prompt":"Find the greatest rate, in metres per hour, at which the depth is decreasing, and the first time in the 24-hour period at which this occurs.","marks":2,"expected_answer":"5π/12 metres per hour (about 1.31 m/h), first at t = 6","explanation":"The derivative d′(t) = (5π/12)cos(πt/6) is most negative when cos(πt/6) = −1, that is when πt/6 = π and t = 6. The rate of decrease is then 5π/12, about 1.31 metres per hour. One mark for the rate, one for the time."},{"label":"g","prompt":"Find the average depth of water in the harbour over the first 12 hours, in metres.","marks":2,"expected_answer":"5 metres","explanation":"The average value is (1/12) times the integral of d(t) from 0 to 12. The integral of sin(πt/6) over one full period is zero, so only the constant term contributes, giving (1/12)(5 × 12) = 5 metres. One mark for setting up the average-value integral, one for the answer."}]'::jsonb, null),
('1f6b35b8-a269-4beb-917e-ca143e43fa4c', 'mm_calculus', 'year_12', 'proficient', 'extended_response', 'A cup of coffee is poured and left to cool in a room. Its temperature, in degrees Celsius, t minutes after it is poured is modelled by T: [0, ∞) → R, T(t) = 22 + 68e^(−0.05t). A second cup is poured at the same time into a thicker mug, and its temperature is modelled by S(t) = 22 + 68e^(−0.03t). Both graphs are shown below.', null, null, 'See the per-part marking guidance.', 'VCE-MM-U34-AOS3', null, true, true, null, null, '[{"label":"a","prompt":"State the temperature of the first cup of coffee at the moment it is poured.","marks":1,"expected_answer":"90 °C","explanation":"At t = 0, e⁰ = 1, so T(0) = 22 + 68 = 90 degrees Celsius."},{"label":"b","prompt":"State the equation of the horizontal asymptote of the graph of y = T(t), and interpret it in this context.","marks":2,"expected_answer":"T = 22; the coffee cools towards the room temperature of 22 °C but never reaches it","explanation":"As t increases, e^(−0.05t) approaches zero, so T approaches 22. One mark for the equation, one for the interpretation as the temperature of the room."},{"label":"c","prompt":"Find the temperature of the first cup after 10 minutes. Give your answer in degrees Celsius, correct to one decimal place.","marks":1,"expected_answer":"63.2 °C","explanation":"T(10) = 22 + 68e^(−0.5) = 22 + 41.24 = 63.24, which is 63.2 degrees Celsius correct to one decimal place."},{"label":"d","prompt":"Find how long it takes the first cup to cool to 50 °C. Give your answer in minutes, correct to one decimal place.","marks":2,"expected_answer":"17.7 minutes","explanation":"Solving 22 + 68e^(−0.05t) = 50 gives e^(−0.05t) = 28/68, so −0.05t = logₑ(28/68) and t = 17.746, which is 17.7 minutes. One mark for the equation, one for the value."},{"label":"e","prompt":"Show that T′(t) = −3.4e^(−0.05t), and hence find the rate at which the first cup is cooling after 10 minutes. Give your answer in degrees Celsius per minute, correct to two decimal places.","marks":2,"expected_answer":"Cooling at 2.06 °C per minute","explanation":"Differentiating gives T′(t) = 68 × (−0.05)e^(−0.05t) = −3.4e^(−0.05t). At t = 10, T′(10) = −3.4e^(−0.5) = −2.06, so the coffee is cooling at 2.06 degrees Celsius per minute. One mark for the derivation, one for the value."},{"label":"f","prompt":"Find the average rate of change of the temperature of the first cup over the first 10 minutes. Give your answer in degrees Celsius per minute, correct to two decimal places.","marks":2,"expected_answer":"−2.68 °C per minute","explanation":"The average rate of change is (T(10) − T(0))/10 = (63.24 − 90)/10 = −2.68 degrees Celsius per minute. One mark for the method, one for the value. Note this is steeper than the instantaneous rate at t = 10 found in part e, because the coffee cools fastest at the start."},{"label":"g","prompt":"Find the time at which the second cup reaches the temperature that the first cup had after 10 minutes. Give your answer in minutes, correct to one decimal place.","marks":2,"expected_answer":"16.7 minutes","explanation":"Setting 22 + 68e^(−0.03t) = 63.24 gives e^(−0.03t) = e^(−0.5), so −0.03t = −0.5 and t = 50/3 = 16.667, which is 16.7 minutes. One mark for the equation, one for the value."},{"label":"h","prompt":"Find the average temperature of the first cup over the first 30 minutes. Give your answer in degrees Celsius, correct to one decimal place.","marks":3,"expected_answer":"57.2 °C","explanation":"The average value is (1/30) times the integral of T(t) from 0 to 30. An antiderivative is 22t − 1360e^(−0.05t), which evaluates to (660 − 1360e^(−1.5)) − (−1360) = 1716.54. Dividing by 30 gives 57.2 degrees Celsius. One mark for the average-value setup, one for the antiderivative, one for the value."}]'::jsonb, null),
('af5f74e3-f8a1-4897-b41b-b7e328053e3f', 'mm_probability', 'year_12', 'advanced', 'extended_response', 'A factory makes glass jars. The mass of a jar, in grams, is a normally distributed random variable M with a mean of 210 grams and a standard deviation of 6 grams.', null, null, 'See the per-part marking guidance.', 'VCE-MM-U34-AOS4', null, true, true, null, null, '[{"label":"a","prompt":"Find Pr(M > 216). Give your answer correct to four decimal places.","marks":1,"expected_answer":"0.1587","explanation":"Standardising gives z = (216 − 210)/6 = 1, so Pr(M > 216) = Pr(Z > 1) = 0.1587."},{"label":"b","prompt":"Find Pr(200 < M < 220). Give your answer correct to four decimal places.","marks":2,"expected_answer":"0.9044","explanation":"The z-values are (200 − 210)/6 = −1.6667 and (220 − 210)/6 = 1.6667, so the probability is Pr(−1.6667 < Z < 1.6667) = 0.9044. One mark for standardising both endpoints, one for the value."},{"label":"c","prompt":"A jar is rejected if its mass is less than 198 grams. Find the proportion of jars that are rejected, correct to four decimal places.","marks":1,"expected_answer":"0.0228","explanation":"The z-value is (198 − 210)/6 = −2, so the proportion rejected is Pr(Z < −2) = 0.0228."},{"label":"d","prompt":"Find the value of m for which 90% of jars have a mass less than m grams. Give your answer correct to one decimal place.","marks":2,"expected_answer":"m = 217.7 grams","explanation":"The 90th percentile of the standard normal distribution is z = 1.2816, so m = 210 + 6 × 1.2816 = 217.69, which is 217.7 grams. One mark for the z-value, one for m."},{"label":"e","prompt":"A box holds 12 jars chosen at random. Find the probability that exactly 2 of them are rejected. Give your answer correct to four decimal places.","marks":2,"expected_answer":"0.0271","explanation":"The number rejected is binomial with n = 12 and p = 0.0228 from part c. Using the unrounded value of p, Pr(X = 2) = 0.0271. One mark for identifying the binomial distribution with the correct n and p, one for the value. Carry the unrounded value of p through the calculation."},{"label":"f","prompt":"Find the probability that at least one jar in a box of 12 is rejected. Give your answer correct to four decimal places.","marks":2,"expected_answer":"0.2413","explanation":"Pr(X ≥ 1) = 1 − Pr(X = 0) = 1 − 0.7587 = 0.2413. One mark for using the complement, one for the value."},{"label":"g","prompt":"The factory claims that 95% of its jars have a mass of at least 200 grams. Assuming this claim is correct, find the mean and the standard deviation of the distribution of the sample proportion of jars with a mass of at least 200 grams, for random samples of 150 jars. Give the standard deviation correct to four decimal places.","marks":2,"expected_answer":"Mean 0.95, standard deviation 0.0178","explanation":"The mean of the sample proportion equals the population proportion, 0.95. The standard deviation is the square root of 0.95 × 0.05 ÷ 150 = 0.00031667, which is 0.0178. One mark for the mean, one for the standard deviation."},{"label":"h","prompt":"In one random sample of 150 jars, 138 had a mass of at least 200 grams. Find an approximate 95% confidence interval for the population proportion, correct to four decimal places, and state whether this interval supports the factory claim.","marks":3,"expected_answer":"(0.8766, 0.9634); the interval contains 0.95, so it supports the claim","explanation":"The sample proportion is 138/150 = 0.92, with standard error the square root of 0.92 × 0.08 ÷ 150 = 0.0222. The margin of error is 1.96 × 0.0222 = 0.0434, giving (0.8766, 0.9634). One mark for the sample proportion and standard error, one for the interval, one for noting that 0.95 lies inside it so the sample does not contradict the claim."}]'::jsonb, null),
('f7953088-8bf2-41d2-a2ff-5749151af7e5', 'mm_algebra', 'year_12', 'advanced', 'extended_response', 'Let fₐ: R → R, fₐ(x) = x³ − ax, where a is a positive real constant. The graph of y = f₁₂(x), the member of this family with a = 12, is shown below.', null, null, 'See the per-part marking guidance.', 'VCE-MM-U34-AOS2', null, true, true, null, null, '[{"label":"a","prompt":"Find the x-intercepts of the graph of y = fₐ(x), in terms of a.","marks":1,"expected_answer":"x = 0, x = √a and x = −√a","explanation":"Factorising gives x(x² − a) = 0, so x = 0 or x² = a. Since a > 0 there are three intercepts: 0, √a and −√a."},{"label":"b","prompt":"Find, in terms of a, the coordinates of the stationary points of fₐ.","marks":3,"expected_answer":"Local maximum at (−√(3a)/3, 2a√(3a)/9) and local minimum at (√(3a)/3, −2a√(3a)/9)","explanation":"The derivative is 3x² − a, which is zero when x = ±√(a/3) = ±√(3a)/3. Substituting into fₐ gives y = ∓2a√(3a)/9. One mark for the derivative and solving it, one for the x-coordinates, one for the y-coordinates. The negative x-value gives the local maximum because the coefficient of x³ is positive."},{"label":"c","prompt":"Verify that the local minimum of f₁₂ is at the point (2, −16).","marks":1,"expected_answer":"x = √(36)/3 = 2 and f₁₂(2) = 8 − 24 = −16","explanation":"Substituting a = 12 into x = √(3a)/3 gives √36/3 = 2, and f₁₂(2) = 2³ − 12 × 2 = −16, as required."},{"label":"d","prompt":"Find the total area of the region enclosed between the graph of y = f₁₂(x) and the x-axis.","marks":3,"expected_answer":"72 square units","explanation":"The x-intercepts are 0 and ±√12 = ±2√3. By symmetry the total area is twice the integral of 12x − x³ from 0 to 2√3. An antiderivative is 6x² − x⁴/4, which gives 72 − 36 = 36, so the total area is 72 square units. One mark for the terminals, one for the integral, one for doubling."},{"label":"e","prompt":"A tangent to the graph of y = f₁₂(x) is drawn at the point (p, f₁₂(p)), where p > 0. This tangent passes through the point (0, −54). Find p and the equation of the tangent.","marks":3,"expected_answer":"p = 3, and the tangent is y = 15x − 54","explanation":"The tangent at x = p has gradient 3p² − 12 and passes through (p, p³ − 12p), so its y-intercept is p³ − 12p − p(3p² − 12) = −2p³. Setting −2p³ = −54 gives p³ = 27, so p = 3. Then the gradient is 15 and the tangent is y = 15x − 54. One mark for the general y-intercept, one for p, one for the equation."},{"label":"f","prompt":"Find the values of a for which the equation fₐ(x) = 4 has exactly one solution.","marks":3,"expected_answer":"0 < a < 3 × 4^(1/3), that is 0 < a < 4.762 correct to three decimal places","explanation":"The cubic meets the horizontal line y = 4 once when 4 is above the local maximum value 2a√(3a)/9. Solving 2a√(3a)/9 < 4 gives 3a³ < 324, so a³ < 108 and a < 108^(1/3) = 3 × 4^(1/3). Combined with a > 0 this gives 0 < a < 4.762. One mark for recognising the local maximum condition, one for the inequality, one for the value."},{"label":"g","prompt":"Find, in terms of a, the total area of the region enclosed between the graph of y = fₐ(x) and the x-axis.","marks":3,"expected_answer":"a²/2 square units","explanation":"By symmetry the total area is twice the integral of ax − x³ from 0 to √a. An antiderivative is ax²/2 − x⁴/4, which gives a²/2 − a²/4 = a²/4, so the total area is a²/2. Substituting a = 12 gives 72, matching part d. One mark for the terminals, one for the integral, one for doubling."}]'::jsonb, null),
('168b8cb4-6e4d-4e7a-af05-5b690d7d410d', 'gm_data_analysis', 'year_12', 'proficient', 'multiple_choice', 'The box plot below displays the time taken, in minutes, by a group of workers to complete a task. Any value greater than which of the following would be displayed as an outlier?', '["37.5","43.5","50.5","44","62"]'::jsonb, 2, 'The interquartile range is 31 − 18 = 13. The upper fence is Q3 + 1.5 × IQR = 31 + 19.5 = 50.5, so any value above 50.5 is an outlier.', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('1149c202-4da9-42d1-8ba2-c8c075148f51', 'gm_data_analysis', 'year_12', 'proficient', 'multiple_choice', 'The parallel box plots below display daily sales, in thousands of dollars, for two stores. The interquartile range for Store B is', '["14","12","23","40","2"]'::jsonb, 0, 'For Store B the interquartile range is Q3 − Q1 = 38 − 24 = 14. Store A has the smaller interquartile range, 40 − 28 = 12, so the middle 50% of Store A’s sales is less spread out.', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('a011285d-fcaa-4734-b392-5293e85c7f1c', 'gm_data_analysis', 'year_12', 'foundation', 'multiple_choice', 'In a study of housing, the variable postcode is best described as', '["numerical and discrete","numerical and continuous","categorical and ordinal","neither numerical nor categorical","categorical and nominal"]'::jsonb, 4, 'A postcode is written with digits, but the digits label an area rather than measure anything — postcode 3000 is not "less than" postcode 3121 in any useful sense, and averaging postcodes is meaningless. Because the categories have no natural order, the variable is nominal.', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('7ac94e73-2161-436e-a570-73d3b90dc3ca', 'gm_data_analysis', 'year_12', 'proficient', 'multiple_choice', 'The weights of a large group of adults are approximately normally distributed with a mean of 70 kg and a standard deviation of 4 kg. The percentage of these adults with a weight between 62 kg and 78 kg is closest to', '["34%","95%","68%","99.7%","47.5%"]'::jsonb, 1, 'The values 62 and 78 are each two standard deviations from the mean, because 70 − 2 × 4 = 62 and 70 + 2 × 4 = 78. By the 68–95–99.7% rule, 95% of values lie within two standard deviations of the mean.', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('460605c7-f575-40f7-93bd-a359610a8e35', 'gm_data_analysis', 'year_12', 'foundation', 'multiple_choice', 'A test has a mean of 72 and a standard deviation of 8. The standardised score (z-score) of a student who scored 60 is', '["−12","1.5","−0.67","−1.5","1"]'::jsonb, 3, 'The standardised score is z = (x − mean) ÷ standard deviation = (60 − 72) ÷ 8 = −1.5. The score is negative because 60 is below the mean.', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('baecd5be-10ec-4c0b-abda-c3a631c08e09', 'gm_data_analysis', 'year_12', 'proficient', 'multiple_choice', 'On a test with a mean of 64 and a standard deviation of 12, a student’s standardised score was 1.25. The student’s actual mark was', '["76","79","80","78","65.25"]'::jsonb, 1, 'Rearranging z = (x − mean) ÷ standard deviation gives x = mean + z × standard deviation = 64 + 1.25 × 12 = 79.', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('0403a4cc-5012-4001-afd4-c11c6dd93455', 'gm_data_analysis', 'year_12', 'proficient', 'multiple_choice', 'The dot plot below shows the number of pets owned by each of 13 households. The median number of pets owned is', '["4","4.5","5","6","7"]'::jsonb, 2, 'With 13 values, the median is the 7th value when they are ordered. Counting along the dot plot, the 7th value is 5. The mode is 6, which occurs four times, but the question asks for the median.', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('09ffb66c-72e6-4b47-85c5-d521a6b18281', 'gm_data_analysis', 'year_12', 'proficient', 'multiple_choice', 'The two-way frequency table below shows the responses of 140 people to a survey question. The percentage of females who answered Yes is closest to', '["43.8%","25.0%","45.5%","70.0%","24.8%"]'::jsonb, 0, 'There are 35 + 45 = 80 females, of whom 35 answered Yes. The percentage is 35 ÷ 80 = 0.4375, which is 43.8%. The value 45.5% is the percentage of Yes responses that came from females, a different question.', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('7d1cae51-96f2-4498-a1bc-a11b60940dda', 'gm_data_analysis', 'year_12', 'proficient', 'multiple_choice', 'The correlation coefficient between two numerical variables is r = −0.68. The percentage of the variation in one variable that is explained by the variation in the other is closest to', '["68%","82%","23%","54%","46%"]'::jsonb, 4, 'The coefficient of determination is r² = (−0.68)² = 0.4624, which is 46% correct to the nearest per cent. The sign of r says the association is negative but does not affect r².', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('993d89ab-5a61-4061-8e1c-23dfdfc7e06d', 'gm_data_analysis', 'year_12', 'proficient', 'multiple_choice', 'A least squares line fitted to data on delivery cost and distance has the equation cost = 12.5 + 3.2 × distance, where cost is in dollars and distance is in kilometres. The slope of this line tells us that, on average,', '["the cost of a delivery is $3.20","the cost of a delivery is $12.50","each extra kilometre adds $3.20 to the cost","each extra kilometre adds $12.50 to the cost","each extra dollar of cost adds 3.2 kilometres"]'::jsonb, 2, 'The slope is the change in the response variable for a one-unit increase in the explanatory variable. Here a one-kilometre increase in distance is associated with a $3.20 increase in cost, on average. The intercept, $12.50, is the fixed cost of a delivery of zero distance.', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('7843a2b1-8a14-4efd-868b-da268f4f7444', 'gm_data_analysis', 'year_12', 'proficient', 'multiple_choice', 'A least squares line has the equation y = 8.4 + 1.6x. When x = 12, the actual value of y was 25.1. The residual for this data point is', '["−2.5","2.5","27.6","25.1","−0.5"]'::jsonb, 0, 'The predicted value is y = 8.4 + 1.6 × 12 = 27.6. The residual is the actual value minus the predicted value: 25.1 − 27.6 = −2.5. The residual is negative because the line overpredicts at this point.', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('9a959f16-ceda-4134-a4e4-8f560e2afe21', 'gm_data_analysis', 'year_12', 'proficient', 'multiple_choice', 'A least squares line is fitted to a set of data, and the residual plot shows a clear curved pattern. This indicates that', '["the data contains an outlier","the correlation coefficient must be negative","the association is not linear, so a linear model is not appropriate","the least squares line has been calculated incorrectly","the two variables are not associated"]'::jsonb, 2, 'A residual plot is used to check the assumption of linearity. Random scatter about zero supports a linear model; a clear pattern such as a curve means the relationship is non-linear, and the data should be transformed or a different model used.', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('9e58fcac-bbe2-4062-a711-c6aad8220b94', 'gm_data_analysis', 'year_12', 'advanced', 'multiple_choice', 'A scatterplot of y against x shows an association that increases steadily but flattens out as x increases. Which transformation is most likely to linearise this association?', '["a y² transformation","a log₁₀(x) transformation","an x² transformation","a 1/y transformation","no transformation will linearise it"]'::jsonb, 1, 'The pattern rises but flattens, so the x-values need to be stretched at the low end and compressed at the high end. A log₁₀(x) transformation does exactly that. An x² transformation would exaggerate the curve rather than remove it.', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('cad1aac7-5344-44a5-b99a-55273b8e0e03', 'gm_data_analysis', 'year_12', 'proficient', 'multiple_choice', 'The table below shows visitor numbers, in hundreds, over seven months. The three-point moving average for month 4 is', '["26","28","29.3","30","32"]'::jsonb, 3, 'The three-point moving average for month 4 uses months 3, 4 and 5: (26 + 30 + 34) ÷ 3 = 90 ÷ 3 = 30. Only the value either side of the month is used, not the whole series.', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('dbbebdef-0552-44bf-b0be-524c2a839de2', 'gm_data_analysis', 'year_12', 'proficient', 'multiple_choice', 'The seasonal index for winter sales at a ski hire shop is 1.25. In one winter, actual sales were $8000. The deseasonalised sales figure for that winter is', '["$9600","$10 000","$8000","$6250","$6400"]'::jsonb, 4, 'Deseasonalised figure = actual figure ÷ seasonal index = 8000 ÷ 1.25 = 6400. An index above 1 means winter is a busier-than-average season, so the deseasonalised value is lower than the actual value.', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('735a921a-4ac0-4b14-90ba-796ea54fd498', 'gm_data_analysis', 'year_12', 'proficient', 'multiple_choice', 'The seasonal indices for summer, autumn and winter are 1.15, 0.92 and 1.08 respectively. The seasonal index for spring is', '["0.85","0.95","1.00","0.75","1.15"]'::jsonb, 0, 'Seasonal indices for a year must average 1, so for four seasons they sum to 4. The three given indices sum to 1.15 + 0.92 + 1.08 = 3.15, so the spring index is 4 − 3.15 = 0.85.', 'VCE-GM-U34-AOS1', null, true, true, null, null, null, 1),
('97550631-d033-4cc8-bd66-b0a2ade1818b', 'gm_financial', 'year_12', 'foundation', 'multiple_choice', 'A sequence is generated by the recurrence relation A₀ = 12, Aₙ₊₁ = 3Aₙ − 8. The value of A₂ is', '["28","44","100","76","220"]'::jsonb, 3, 'Applying the rule twice: A₁ = 3 × 12 − 8 = 28, then A₂ = 3 × 28 − 8 = 76. The value 28 is A₁, one step short.', 'VCE-GM-U34-AOS2', null, true, true, null, null, null, 1),
('5ca38437-7393-4d1c-be71-b197dfe39350', 'gm_financial', 'year_12', 'proficient', 'multiple_choice', 'A machine is purchased for $24 000 and depreciated using the flat rate method at 15% of the purchase price per annum. The value of the machine after four years is', '["$8400","$9600","$12 528","$14 400","$10 200"]'::jsonb, 1, 'Flat rate depreciation is a fixed amount each year, 0.15 × 24 000 = $3600. Over four years the machine loses 4 × 3600 = $14 400, leaving 24 000 − 14 400 = $9600. Reducing balance depreciation at the same rate would instead leave about $12 528.', 'VCE-GM-U34-AOS2', null, true, true, null, null, null, 1),
('03af7032-4a97-4873-8a78-7d1553e52d27', 'gm_financial', 'year_12', 'proficient', 'multiple_choice', 'A car purchased for $32 000 loses 12% of its value each year. A recurrence relation that models the value Vₙ, in dollars, of the car after n years is', '["V₀ = 32 000, Vₙ₊₁ = Vₙ − 0.12","V₀ = 32 000, Vₙ₊₁ = 1.12Vₙ","V₀ = 32 000, Vₙ₊₁ = Vₙ − 3840","V₀ = 32 000, Vₙ₊₁ = 0.12Vₙ","V₀ = 32 000, Vₙ₊₁ = 0.88Vₙ"]'::jsonb, 4, 'Losing 12% of its value each year leaves 88% of the previous year’s value, so Vₙ₊₁ = 0.88Vₙ. This is reducing balance depreciation. Subtracting a fixed $3840 each year would be flat rate depreciation instead.', 'VCE-GM-U34-AOS2', null, true, true, null, null, null, 1),
('6281a162-2a5a-4537-941e-df04d6054a43', 'gm_financial', 'year_12', 'proficient', 'multiple_choice', 'A delivery van is purchased for $45 000 and depreciated by the unit cost method at a rate of $0.25 per kilometre travelled. After the van has travelled 60 000 km, its value is', '["$28 000","$15 000","$33 750","$30 000","$44 750"]'::jsonb, 3, 'Unit cost depreciation charges a fixed amount per unit of use: 0.25 × 60 000 = $15 000 of depreciation. The value is 45 000 − 15 000 = $30 000.', 'VCE-GM-U34-AOS2', null, true, true, null, null, null, 1),
('62d731e9-2274-4887-9f7d-5fe7c9d8535f', 'gm_financial', 'year_12', 'advanced', 'multiple_choice', 'An amount of $6000 is invested at 4.8% per annum, compounding monthly. The value of the investment after three years is closest to', '["$6927.31","$6864.00","$6904.20","$7013.80","$6900.00"]'::jsonb, 0, 'The monthly interest rate is 4.8 ÷ 12 = 0.4%, and three years is 36 compounding periods. The value is 6000 × 1.004³⁶ = $6927.31. Simple interest at the same rate would give only $6864.00.', 'VCE-GM-U34-AOS2', null, true, true, null, null, null, 1),
('ea47ffdf-35b3-45ff-b735-c9a6f27c515e', 'gm_financial', 'year_12', 'proficient', 'multiple_choice', 'A reducing balance loan is modelled by the recurrence relation V₀ = 180 000, Vₙ₊₁ = 1.0035Vₙ − 1250, where Vₙ is the balance in dollars after n months. The annual interest rate for this loan is', '["0.35%","3.5%","4.28%","4.2%","42%"]'::jsonb, 3, 'The multiplier 1.0035 means 0.35% interest is charged each month. The annual rate is 12 × 0.35 = 4.2%. The monthly repayment of $1250 does not affect the interest rate.', 'VCE-GM-U34-AOS2', null, true, true, null, null, null, 1),
('af7863f1-89c3-42a7-a3a1-74f14ee91e8e', 'gm_financial', 'year_12', 'proficient', 'multiple_choice', 'A loan of $250 000 is charged interest at 5.4% per annum, compounding monthly, with monthly repayments of $1600. The amount by which the first repayment reduces the principal is', '["$350","$475","$1125","$1600","$2725"]'::jsonb, 1, 'The monthly interest rate is 5.4 ÷ 12 = 0.45%, so the first month’s interest is 250 000 × 0.0045 = $1125. The rest of the repayment reduces the principal: 1600 − 1125 = $475.', 'VCE-GM-U34-AOS2', null, true, true, null, null, null, 1),
('eb1c40f5-8cf7-42ea-8024-afeffd49aeb9', 'gm_financial', 'year_12', 'proficient', 'multiple_choice', 'A perpetuity pays $450 per month indefinitely from an investment of $120 000. The annual interest rate for this perpetuity is', '["0.375%","4.0%","5.4%","3.75%","4.5%"]'::jsonb, 4, 'A perpetuity pays out exactly the interest earned, leaving the principal untouched. The monthly rate is 450 ÷ 120 000 = 0.00375, which is 0.375% per month, so the annual rate is 12 × 0.375 = 4.5%.', 'VCE-GM-U34-AOS2', null, true, true, null, null, null, 1),
('4cc0ff9c-064e-4ac3-a956-984002621c73', 'gm_matrices', 'year_12', 'foundation', 'multiple_choice', 'For matrix M below, the element m₂₃ is', '["2","3","8","7","9"]'::jsonb, 2, 'The element mᵢⱼ is in row i and column j, so m₂₃ is in row 2, column 3. Reading across the second row, 9, 3, 8, the third entry is 8. The value 2 is m₁₃, from the wrong row.', 'VCE-GM-U34-AOS3', null, true, true, null, null, null, 1),
('18ee3ee7-cf2e-49f9-8ea4-d6b7f86380a9', 'gm_matrices', 'year_12', 'foundation', 'multiple_choice', 'Matrix A has order 3 × 2 and matrix B has order 2 × 4. The order of the product matrix AB is', '["3 × 4","2 × 2","4 × 3","3 × 2","the product AB is not defined"]'::jsonb, 0, 'A product is defined when the number of columns of the first matrix equals the number of rows of the second: A has 2 columns and B has 2 rows, so AB exists. The product takes the rows of A and the columns of B, giving order 3 × 4.', 'VCE-GM-U34-AOS3', null, true, true, null, null, null, 1),
('663f9054-56a9-418e-a85f-542c65192f1e', 'gm_matrices', 'year_12', 'proficient', 'multiple_choice', 'Let A be the matrix below and let B be the matrix with first row 5, 1 and second row 2, 6. The element in row 1, column 2 of the product AB is', '["11","13","16","25","20"]'::jsonb, 4, 'The element in row 1, column 2 of AB comes from row 1 of A and column 2 of B: 2 × 1 + 3 × 6 = 2 + 18 = 20. The value 16 is the element in row 1, column 1.', 'VCE-GM-U34-AOS3', null, true, true, null, null, null, 1),
('a03b4a18-521a-41ab-939b-0b046f0c4596', 'gm_matrices', 'year_12', 'proficient', 'multiple_choice', 'The determinant of matrix P below is', '["8","10","18","26","−10"]'::jsonb, 1, 'For a 2 × 2 matrix with first row a, b and second row c, d, the determinant is ad − bc. Here 6 × 3 − 4 × 2 = 18 − 8 = 10. Because the determinant is not zero, P has an inverse.', 'VCE-GM-U34-AOS3', null, true, true, null, null, null, 1),
('b0910fa8-85af-4e39-ba16-64bc82e99c1d', 'gm_matrices', 'year_12', 'proficient', 'multiple_choice', 'A population of 1000 is split evenly between states A and B, and moves between them each week according to the transition matrix T below. The number in state A after one week is', '["400","450","500","550","650"]'::jsonb, 3, 'Starting with 500 in each state, the number in state A after one week is 0.8 × 500 + 0.3 × 500 = 400 + 150 = 550. The remaining 450 are in state B, and the two still total 1000.', 'VCE-GM-U34-AOS3', null, true, true, null, null, null, 1),
('b5e4aeb0-a929-4406-858b-061d4d09e8f5', 'gm_matrices', 'year_12', 'advanced', 'multiple_choice', 'A population of 900 moves between states A and B each year according to the transition matrix T below. In the long run, the number in state A is closest to', '["450","540","600","675","300"]'::jsonb, 2, 'In the steady state the numbers stop changing, so 0.9a + 0.2b = a, which gives 0.2b = 0.1a and therefore a = 2b. Since a + b = 900, we get 3b = 900, so b = 300 and a = 600. The long-run split is two-thirds in state A.', 'VCE-GM-U34-AOS3', null, true, true, null, null, null, 1),
('8c829bb6-8efb-4250-b6a0-822b1dfb819c', 'gm_matrices', 'year_12', 'proficient', 'multiple_choice', 'A permutation matrix has exactly one 1 in each row and each column, with every other element 0. Multiplying a column matrix by a permutation matrix will', '["reorder the elements of the column matrix","add the elements of the column matrix together","leave the column matrix unchanged","replace every element with its reciprocal","change the order of the column matrix"]'::jsonb, 0, 'Each row of a permutation matrix picks out exactly one element of the column matrix and leaves the others out, so the result contains the same values rearranged. The order of the matrix is unchanged, and only the identity matrix leaves the values in place as well.', 'VCE-GM-U34-AOS3', null, true, true, null, null, null, 1),
('758f0812-d101-4b9b-b0a9-f8ffc8d8bccc', 'gm_matrices', 'year_12', 'advanced', 'multiple_choice', 'Matrix X satisfies 3X + C = D, where C has first row 2, 5 and second row 1, 4, and D has first row 11, 20 and second row 7, 16. The element in row 2, column 1 of X is', '["3","2","4","5","6"]'::jsonb, 1, 'Rearranging gives 3X = D − C. In row 2, column 1 that is 7 − 1 = 6, so the element of X is 6 ÷ 3 = 2. The value 6 is the corresponding element of 3X, before dividing.', 'VCE-GM-U34-AOS3', null, true, true, null, null, null, 1),
('b189e097-0839-49a8-875e-a39518b64983', 'gm_networks', 'year_12', 'foundation', 'multiple_choice', 'For the graph below, the sum of the degrees of the vertices is', '["10","11","12","6","24"]'::jsonb, 2, 'Every edge contributes 1 to the degree of each of its two endpoints, so the sum of the degrees is always twice the number of edges. This graph has 6 edges, so the sum of the degrees is 12.', 'VCE-GM-U34-AOS4', null, true, true, null, null, null, 1),
('61f47945-06c6-4b2b-a1ae-657aa2d69c60', 'gm_networks', 'year_12', 'proficient', 'multiple_choice', 'A connected planar graph has 6 vertices and 9 edges. Using Euler’s formula, the number of faces is', '["3","4","6","17","5"]'::jsonb, 4, 'Euler’s formula for a connected planar graph is v + f = e + 2. Substituting gives 6 + f = 9 + 2, so f = 5. The faces include the infinite region outside the graph.', 'VCE-GM-U34-AOS4', null, true, true, null, null, null, 1),
('8a362497-0788-4df0-9821-00d653a8fc0f', 'gm_networks', 'year_12', 'proficient', 'multiple_choice', 'For the weighted graph below, the total weight of the minimum spanning tree is', '["19","18","20","22","24"]'::jsonb, 0, 'Adding edges from lightest to heaviest and skipping any that would form a cycle gives BC (3), AB (4), CD (5) and then DE (7); AC (6) is skipped because it would close a cycle. A spanning tree on 5 vertices has 4 edges, and their total weight is 3 + 4 + 5 + 7 = 19.', 'VCE-GM-U34-AOS4', null, true, true, null, null, null, 1),
('2d49e5bc-f470-407b-a809-c77ea74ec968', 'gm_networks', 'year_12', 'proficient', 'multiple_choice', 'For the weighted graph below, the length of the shortest path from P to T is', '["13","15","16","14","17"]'::jsonb, 3, 'The path P–Q–R–S–T has length 5 + 3 + 2 + 4 = 14. Every other route is longer: P–R–S–T is 15, P–Q–S–T is 16 and P–R–T is 17.', 'VCE-GM-U34-AOS4', null, true, true, null, null, null, 1),
('7ef826c1-79c4-404c-8739-a4d06ee8085a', 'gm_networks', 'year_12', 'advanced', 'multiple_choice', 'Each of three workers is assigned a different task. The table below shows the time, in minutes, each worker takes on each task. The minimum total time to complete all three tasks is', '["17","18","19","20","21"]'::jsonb, 1, 'Assigning Wendy to Task 2, Xavier to Task 1 and Yuki to Task 3 gives 7 + 6 + 5 = 18 minutes. Every other allocation of one worker per task takes longer — the next best is 20 minutes.', 'VCE-GM-U34-AOS4', null, true, true, null, null, null, 1),
('f07719b4-2088-4ec1-87c8-6d9e2b21002e', 'gm_networks', 'year_12', 'advanced', 'multiple_choice', 'The table below shows the activities in a project, their durations and their immediate predecessors. The minimum time to complete the project is', '["13","14","15","18","16"]'::jsonb, 4, 'The project cannot finish before its longest path is complete. That path is A–C–F–G, taking 4 + 5 + 3 + 4 = 16 days. The other paths are shorter: A–D–F–G takes 13 days and B–E–G takes 13 days.', 'VCE-GM-U34-AOS4', null, true, true, null, null, null, 1),
('03d4676d-ddc2-4568-ab2f-0836524a63b1', 'gm_networks', 'year_12', 'advanced', 'multiple_choice', 'The directed network below shows the maximum flow along each path, in units per minute. The maximum flow from S to T is', '["15","17","16","18","19"]'::jsonb, 2, 'The cut separating T from the rest of the network has capacity 7 + 9 = 16, and no cut is smaller, so by the maximum-flow minimum-cut theorem the maximum flow is 16. This flow is achievable: send 7 along A to T and 9 along B to T, with B supplied by 6 from S and 3 from A.', 'VCE-GM-U34-AOS4', null, true, true, null, null, null, 1),
('c31fc559-6d29-4735-8e74-115dc1e681a5', 'gm_networks', 'year_12', 'foundation', 'multiple_choice', 'A connected graph with 7 vertices is a tree. The number of edges in this graph is', '["7","8","12","6","21"]'::jsonb, 3, 'A tree is a connected graph with no cycles, and a tree on n vertices always has exactly n − 1 edges. With 7 vertices that is 6 edges. Adding any further edge would create a cycle.', 'VCE-GM-U34-AOS4', null, true, true, null, null, null, 1),
('18a0387b-b87b-4971-89d0-d28b91ca5a28', 'gm_data_analysis', 'year_12', 'proficient', 'extended_response', 'A nursery measures the height, in centimetres, of nine saplings. The results are shown in the table below.', null, null, 'See the per-part marking guidance.', 'VCE-GM-U34-AOS1', null, true, true, null, null, '[{"label":"a","prompt":"Write down the median height, in centimetres.","marks":1,"expected_answer":"50 cm","explanation":"Ordered, the heights are 30, 42, 45, 47, 50, 51, 55, 58, 62. With nine values the median is the fifth, which is 50."},{"label":"b","prompt":"Find the first quartile, the third quartile and the interquartile range.","marks":2,"expected_answer":"Q1 = 43.5 cm, Q3 = 56.5 cm, IQR = 13 cm","explanation":"The median splits the ordered data, leaving 30, 42, 45, 47 below and 51, 55, 58, 62 above. The lower group has median (42 + 45) ÷ 2 = 43.5 and the upper group (55 + 58) ÷ 2 = 56.5, so the interquartile range is 56.5 − 43.5 = 13. One mark for the two quartiles, one for the interquartile range."},{"label":"c","prompt":"Show that this data set contains no outliers.","marks":2,"expected_answer":"The fences are at 24 cm and 76 cm, and every height lies between them.","explanation":"An outlier lies more than 1.5 interquartile ranges beyond a quartile, and 1.5 × 13 = 19.5. The lower fence is 43.5 − 19.5 = 24 and the upper fence is 56.5 + 19.5 = 76. The smallest height, 30, is above 24 and the largest, 62, is below 76, so there are no outliers. One mark for computing the fences, one for the comparison."},{"label":"d","prompt":"Find the mean height, in centimetres, correct to two decimal places.","marks":1,"expected_answer":"48.89 cm","explanation":"The nine heights total 440 cm, so the mean is 440 ÷ 9 = 48.89 cm correct to two decimal places."},{"label":"e","prompt":"The mean is lower than the median. Explain what this suggests about the shape of the distribution.","marks":1,"expected_answer":"A slight negative skew — the low value of 30 cm pulls the mean below the median.","explanation":"The mean is affected by extreme values but the median is not. Here the single low height of 30 cm drags the mean down to 48.89 while the median stays at 50, which indicates a tail towards the lower values, that is a slight negative skew."},{"label":"f","prompt":"A tenth sapling is measured and found to be 85 cm tall. Explain the effect of including this sapling on the median and on the mean.","marks":2,"expected_answer":"The median rises only slightly, from 50 cm to 50.5 cm; the mean rises sharply, from 48.89 cm to 52.5 cm.","explanation":"With ten values the median is the average of the fifth and sixth, that is (50 + 51) ÷ 2 = 50.5, barely changed. The new total is 525 cm, so the mean becomes 525 ÷ 10 = 52.5, a much larger shift. The height of 85 cm is above the upper fence of 76 cm, so it is an outlier, and this illustrates that the median is resistant to outliers while the mean is not. One mark for each measure."}]'::jsonb, null),
('2bc1ce40-0bc2-4809-9d82-65c651601ef5', 'gm_data_analysis', 'year_12', 'proficient', 'extended_response', 'The scores on a test are approximately normally distributed with a mean of 68 and a standard deviation of 9.', null, null, 'See the per-part marking guidance.', 'VCE-GM-U34-AOS1', null, true, true, null, null, '[{"label":"a","prompt":"Find the percentage of students with scores between 59 and 77.","marks":1,"expected_answer":"68%","explanation":"The scores 59 and 77 are one standard deviation either side of the mean, because 68 − 9 = 59 and 68 + 9 = 77. By the 68–95–99.7% rule, 68% of values lie within one standard deviation of the mean."},{"label":"b","prompt":"Find the standardised score of a student who scored 86.","marks":1,"expected_answer":"z = 2","explanation":"The standardised score is z = (86 − 68) ÷ 9 = 2, so the score is two standard deviations above the mean."},{"label":"c","prompt":"Using the 68–95–99.7% rule, find the percentage of students who scored above 86.","marks":2,"expected_answer":"2.5%","explanation":"From part b, 86 is two standard deviations above the mean. The rule says 95% of scores lie within two standard deviations, leaving 5% outside. That 5% is split evenly between the two tails, so 2.5% of students scored above 86. One mark for the 5% outside, one for halving it."},{"label":"d","prompt":"In a group of 400 students, find the number expected to score below 50.","marks":1,"expected_answer":"10 students","explanation":"The score 50 is two standard deviations below the mean, because 68 − 2 × 9 = 50, so 2.5% of students fall below it. That is 0.025 × 400 = 10 students."}]'::jsonb, null),
('6fc93388-be41-4af0-99ed-4ccb081c2cba', 'gm_data_analysis', 'year_12', 'proficient', 'extended_response', 'The scatterplot below shows the test mark and the hours of study for six students, together with the least squares line fitted to the data. The equation of this line is mark = 44 + 3.5 × hours.', null, null, 'See the per-part marking guidance.', 'VCE-GM-U34-AOS1', null, true, true, null, null, '[{"label":"a","prompt":"Name the explanatory variable in this study.","marks":1,"expected_answer":"Hours of study","explanation":"The explanatory variable is the one used to predict the other. Here hours of study is used to predict the test mark, so hours of study is explanatory and mark is the response variable."},{"label":"b","prompt":"Interpret the slope of the least squares line in terms of the variables in this study.","marks":1,"expected_answer":"On average, each extra hour of study is associated with an increase of 3.5 marks.","explanation":"The slope is the average change in the response variable for a one-unit increase in the explanatory variable, so one more hour of study is associated with 3.5 more marks on average. The answer must name both variables to earn the mark."},{"label":"c","prompt":"Use the least squares line to predict the mark of a student who studies for 9 hours.","marks":1,"expected_answer":"75.5 marks","explanation":"Substituting into the equation gives mark = 44 + 3.5 × 9 = 75.5."},{"label":"d","prompt":"Find the residual for the student who studied for 10 hours and scored 77.","marks":2,"expected_answer":"−2","explanation":"The predicted mark is 44 + 3.5 × 10 = 79. The residual is the actual value minus the predicted value, that is 77 − 79 = −2. One mark for the predicted value, one for the residual. The negative sign shows the line overpredicts this student’s mark."},{"label":"e","prompt":"The coefficient of determination is 0.982. Interpret this value in terms of the variables in this study.","marks":1,"expected_answer":"98.2% of the variation in test mark is explained by the variation in hours of study.","explanation":"The coefficient of determination gives the proportion of the variation in the response variable explained by the variation in the explanatory variable. Here that is 98.2%, and the answer must name both variables."}]'::jsonb, null),
('fb4cadc8-2100-4ed5-8400-1d622d6e07a2', 'gm_data_analysis', 'year_12', 'proficient', 'extended_response', 'The table below shows a company’s sales, in thousands of dollars, for each quarter of one year.', null, null, 'See the per-part marking guidance.', 'VCE-GM-U34-AOS1', null, true, true, null, null, '[{"label":"a","prompt":"Find the mean quarterly sales figure for this year, in thousands of dollars.","marks":1,"expected_answer":"$110 thousand","explanation":"The four quarters total 440, so the mean is 440 ÷ 4 = 110 thousand dollars."},{"label":"b","prompt":"Show that the seasonal index for quarter 3 is 0.8.","marks":1,"expected_answer":"88 ÷ 110 = 0.8","explanation":"A seasonal index is the quarter’s figure divided by the mean for the year: 88 ÷ 110 = 0.8. An index below 1 means quarter 3 is a quieter-than-average quarter."},{"label":"c","prompt":"Find the seasonal index for quarter 4, correct to two decimal places.","marks":1,"expected_answer":"1.25","explanation":"The seasonal index is 137 ÷ 110 = 1.2455, which is 1.25 correct to two decimal places. As a check, the four indices must sum to 4."},{"label":"d","prompt":"In quarter 4 of the following year, actual sales were $160 000. Using the index found in part c., find the deseasonalised sales figure, correct to the nearest thousand dollars.","marks":1,"expected_answer":"$128 000","explanation":"Deseasonalised figure = actual figure ÷ seasonal index = 160 000 ÷ 1.25 = 128 000 dollars."}]'::jsonb, null),
('352fcd1a-c10f-4739-b35d-0107d8cbcdaf', 'gm_financial', 'year_12', 'proficient', 'extended_response', 'A printer is purchased for $4800 and is depreciated using the reducing balance method at a rate of 20% per annum.', null, null, 'See the per-part marking guidance.', 'VCE-GM-U34-AOS2', null, true, true, null, null, '[{"label":"a","prompt":"Write down a recurrence relation that models the value Vₙ, in dollars, of the printer after n years.","marks":1,"expected_answer":"V₀ = 4800, Vₙ₊₁ = 0.8Vₙ","explanation":"Losing 20% of its value each year leaves 80% of the previous value, so the multiplier is 0.8 and the starting value is 4800."},{"label":"b","prompt":"Find the value of the printer after three years, correct to the nearest cent.","marks":1,"expected_answer":"$2457.60","explanation":"Applying the multiplier three times gives 4800 × 0.8³ = 4800 × 0.512 = 2457.60 dollars."},{"label":"c","prompt":"Find the total depreciation over the first three years.","marks":1,"expected_answer":"$2342.40","explanation":"The total depreciation is the fall in value: 4800 − 2457.60 = 2342.40 dollars."}]'::jsonb, null),
('66a5e179-e89c-42a7-8b68-8bebf292ab16', 'gm_financial', 'year_12', 'proficient', 'extended_response', 'Eli invests $15 000 in an account paying 5.2% interest per annum, compounding quarterly.', null, null, 'See the per-part marking guidance.', 'VCE-GM-U34-AOS2', null, true, true, null, null, '[{"label":"a","prompt":"Find the quarterly interest rate.","marks":1,"expected_answer":"1.3%","explanation":"The annual rate is divided by the number of compounding periods in a year: 5.2 ÷ 4 = 1.3% per quarter."},{"label":"b","prompt":"Find the value of the investment after five years, correct to the nearest cent.","marks":2,"expected_answer":"$19 421.38","explanation":"Five years is 20 quarters at a multiplier of 1.013 per quarter, so the value is 15 000 × 1.013²⁰ = $19 421.38. One mark for identifying 20 periods at 1.3%, one for the value."},{"label":"c","prompt":"Find the total interest earned over the five years.","marks":1,"expected_answer":"$4421.38","explanation":"The interest is the growth in the balance: 19 421.38 − 15 000 = 4421.38 dollars."}]'::jsonb, null),
('db89cd1c-6743-4dca-9e5e-9628ea59c9a0', 'gm_financial', 'year_12', 'advanced', 'extended_response', 'Maya borrows $320 000 to buy a house. Interest is charged at 6% per annum, compounding monthly, and she makes repayments of $2100 at the end of each month.', null, null, 'See the per-part marking guidance.', 'VCE-GM-U34-AOS2', null, true, true, null, null, '[{"label":"a","prompt":"Write down a recurrence relation that models the balance Bₙ, in dollars, of the loan after n months.","marks":1,"expected_answer":"B₀ = 320 000, Bₙ₊₁ = 1.005Bₙ − 2100","explanation":"The monthly interest rate is 6 ÷ 12 = 0.5%, giving a multiplier of 1.005, and the repayment of 2100 is then subtracted."},{"label":"b","prompt":"Find the balance of the loan after two months, correct to the nearest cent.","marks":2,"expected_answer":"$318 997.50","explanation":"After one month the balance is 320 000 × 1.005 − 2100 = 319 500. After two months it is 319 500 × 1.005 − 2100 = 318 997.50 dollars. One mark for each application of the rule."},{"label":"c","prompt":"Find the total interest charged over these two months.","marks":1,"expected_answer":"$3197.50","explanation":"Maya repaid 2 × 2100 = 4200 but the balance fell by only 320 000 − 318 997.50 = 1002.50, so the rest went to interest: 4200 − 1002.50 = 3197.50 dollars."},{"label":"d","prompt":"Explain why the amount of interest charged decreases from one month to the next.","marks":1,"expected_answer":"Interest is charged on the outstanding balance, and each repayment reduces that balance.","explanation":"Each month the interest is 0.5% of whatever is still owed. Because every repayment is larger than the interest charged, the balance falls each month, so the interest charged on it falls too — and a larger share of each repayment goes to the principal."}]'::jsonb, null),
('c885e39a-00dc-4cf5-89dc-b93311524fb9', 'gm_matrices', 'year_12', 'proficient', 'extended_response', 'A drinks stall sells three sizes: small (S), medium (M) and large (L). Matrix P below gives the price, in dollars, of each size. On one day the stall sold 120 small, 85 medium and 64 large drinks. These sales are written as a column matrix Q, with the sizes in the order small, medium, large.', null, null, 'See the per-part marking guidance.', 'VCE-GM-U34-AOS3', null, true, true, null, null, '[{"label":"a","prompt":"Write down the order of matrix P.","marks":1,"expected_answer":"1 × 3","explanation":"Matrix P has one row and three columns, so its order is 1 × 3. Matrix Q is 3 × 1."},{"label":"b","prompt":"Evaluate the product PQ.","marks":1,"expected_answer":"PQ = [1502]","explanation":"The product is 4 × 120 + 6 × 85 + 8 × 64 = 480 + 510 + 512 = 1502. Because P is 1 × 3 and Q is 3 × 1, the product is a 1 × 1 matrix."},{"label":"c","prompt":"Explain what the element of PQ represents in this context.","marks":1,"expected_answer":"The stall’s total takings for the day, $1502.","explanation":"Each term of the product multiplies a price by the number sold at that price, and the three terms are added, so the single element is the total revenue in dollars."}]'::jsonb, null),
('a71134a6-aaa0-432d-b4f9-f16b079828e0', 'gm_matrices', 'year_12', 'advanced', 'extended_response', 'Two gyms, A and B, share 1000 members between them. Each month 15% of gym A’s members move to gym B, and 10% of gym B’s members move to gym A. No other members join or leave. At the start, gym A has 600 members and gym B has 400.', null, null, 'See the per-part marking guidance.', 'VCE-GM-U34-AOS3', null, true, true, null, null, '[{"label":"a","prompt":"Write down the transition matrix T for this situation, with the rows and columns in the order A, B.","marks":1,"expected_answer":"T has first row 0.85, 0.10 and second row 0.15, 0.90","explanation":"The first column describes where gym A’s members go: 85% stay at A and 15% move to B. The second column describes gym B’s: 10% move to A and 90% stay. Each column sums to 1 because no members are lost."},{"label":"b","prompt":"Find the number of members at each gym after one month.","marks":2,"expected_answer":"Gym A has 550 members and gym B has 450","explanation":"Gym A keeps 0.85 × 600 = 510 and gains 0.10 × 400 = 40, giving 550. Gym B keeps 0.90 × 400 = 360 and gains 0.15 × 600 = 90, giving 450. The two still total 1000. One mark for each gym."},{"label":"c","prompt":"Find the number of members at gym A in the long run.","marks":1,"expected_answer":"400 members","explanation":"In the steady state the numbers stop changing, so 0.85a + 0.10b = a, which gives 0.10b = 0.15a and therefore b = 1.5a. Since a + b = 1000, we get 2.5a = 1000, so a = 400."}]'::jsonb, null),
('9f5d382a-c590-4ba8-8846-303384bac708', 'gm_matrices', 'year_12', 'proficient', 'extended_response', 'Consider the pair of simultaneous equations 3x + 2y = 19 and 4x − y = 7.', null, null, 'See the per-part marking guidance.', 'VCE-GM-U34-AOS3', null, true, true, null, null, '[{"label":"a","prompt":"Write this pair of equations as a matrix equation of the form AX = B.","marks":1,"expected_answer":"A has first row 3, 2 and second row 4, −1; X is the column matrix x, y; B is the column matrix 19, 7.","explanation":"The coefficients form the 2 × 2 matrix A, the unknowns form the 2 × 1 matrix X, and the right-hand sides form the 2 × 1 matrix B."},{"label":"b","prompt":"Find the determinant of the coefficient matrix A.","marks":1,"expected_answer":"−11","explanation":"For a 2 × 2 matrix with first row a, b and second row c, d, the determinant is ad − bc. Here 3 × (−1) − 2 × 4 = −3 − 8 = −11. Because it is not zero, A has an inverse and the equations have a unique solution."},{"label":"c","prompt":"Hence solve the pair of equations.","marks":1,"expected_answer":"x = 3 and y = 5","explanation":"Multiplying both sides by the inverse of A gives X = A⁻¹B, which yields x = 3 and y = 5. Checking in the original equations: 3 × 3 + 2 × 5 = 19 and 4 × 3 − 5 = 7."}]'::jsonb, null),
('167922d3-ffde-4cd8-8407-2fa43029ab9a', 'gm_matrices', 'year_12', 'advanced', 'extended_response', 'Four people are numbered 1 to 4. In the communication matrix C below, the element in row i and column j is 1 if person i can send a message directly to person j, and 0 otherwise.', null, null, 'See the per-part marking guidance.', 'VCE-GM-U34-AOS3', null, true, true, null, null, '[{"label":"a","prompt":"How many people can person 1 send a message to directly?","marks":1,"expected_answer":"2 people","explanation":"Row 1 of the matrix is 0, 1, 1, 0. The two entries of 1 are in columns 2 and 3, so person 1 can send directly to persons 2 and 3."},{"label":"b","prompt":"Find the number of two-step communication links from person 1 to person 4.","marks":1,"expected_answer":"1 link","explanation":"Two-step links are counted by the element in row 1, column 4 of C². That is row 1 of C combined with column 4 of C, giving 0 × 0 + 1 × 0 + 1 × 1 + 0 × 0 = 1. The single route is person 1 to person 3 to person 4."}]'::jsonb, null),
('35f20a81-a88f-4a52-9fe5-80c66c701a8f', 'gm_networks', 'year_12', 'proficient', 'extended_response', 'The graph below shows the roads connecting six towns. Each vertex represents a town and each edge represents a road.', null, null, 'See the per-part marking guidance.', 'VCE-GM-U34-AOS4', null, true, true, null, null, '[{"label":"a","prompt":"Write down the degree of vertex B.","marks":1,"expected_answer":"3","explanation":"Three edges meet at B — the roads to A, to C and to D — so the degree of B is 3."},{"label":"b","prompt":"Determine the sum of the degrees of all the vertices.","marks":1,"expected_answer":"16","explanation":"Every edge adds 1 to the degree of each of its two endpoints, so the sum of the degrees is twice the number of edges. The graph has 8 edges, so the sum is 16."},{"label":"c","prompt":"This graph is connected and planar. Use Euler’s formula to find the number of faces.","marks":1,"expected_answer":"4 faces","explanation":"Euler’s formula is v + f = e + 2. Substituting v = 6 and e = 8 gives 6 + f = 10, so f = 4. The faces include the infinite region outside the graph."},{"label":"d","prompt":"Explain whether an Eulerian trail exists for this graph.","marks":1,"expected_answer":"No — four vertices have an odd degree, and an Eulerian trail needs exactly zero or two.","explanation":"The degrees are A 2, B 3, C 3, D 3, E 3 and F 2, so B, C, D and E all have odd degree. An Eulerian trail, which uses every edge exactly once, exists only when the number of odd-degree vertices is zero or two, so no such trail exists here."}]'::jsonb, null),
('a88deca2-ada4-4900-b810-8de149d9986c', 'gm_networks', 'year_12', 'proficient', 'extended_response', 'The weighted graph below shows the cost, in thousands of dollars, of laying pipe between six sites. Pipe is to be laid so that every site is connected, at the lowest possible total cost.', null, null, 'See the per-part marking guidance.', 'VCE-GM-U34-AOS4', null, true, true, null, null, '[{"label":"a","prompt":"Find the total cost of the minimum spanning tree, in thousands of dollars.","marks":2,"expected_answer":"$20 thousand","explanation":"Adding edges from cheapest to dearest and skipping any that would form a cycle gives TU (2), QR (3), PR (4), ST (5) and then QS (6), which joins the two halves. The total is 2 + 3 + 4 + 5 + 6 = 20 thousand dollars. One mark for a correct spanning tree, one for the total."},{"label":"b","prompt":"How many edges does the minimum spanning tree contain?","marks":1,"expected_answer":"5 edges","explanation":"A spanning tree on n vertices always has exactly n − 1 edges. With 6 sites that is 5 edges, which matches the five chosen in part a."}]'::jsonb, null),
('12658905-d56b-44b4-8875-a5d1e3adbdae', 'gm_networks', 'year_12', 'advanced', 'extended_response', 'A project consists of eight activities. The table below shows each activity, its duration in days and its immediate predecessors.', null, null, 'See the per-part marking guidance.', 'VCE-GM-U34-AOS4', null, true, true, null, null, '[{"label":"a","prompt":"Determine the earliest start time for activity F.","marks":1,"expected_answer":"Day 9","explanation":"Activity F cannot begin until both C and D are finished. C runs from day 3 to day 7 and D runs from day 3 to day 9, so the later of the two finishing times, day 9, is the earliest start time for F."},{"label":"b","prompt":"Find the minimum time, in days, to complete the project.","marks":2,"expected_answer":"15 days","explanation":"The project takes as long as its longest path. That path is B, E, G, H, taking 6 + 2 + 5 + 2 = 15 days. The alternatives are shorter: A, D, F, H takes 14 days and A, C, F, H takes 12 days. One mark for identifying the paths, one for the longest total."},{"label":"c","prompt":"Write down the critical path for this project.","marks":1,"expected_answer":"B–E–G–H","explanation":"The critical path is the longest path through the project, B–E–G–H at 15 days. Every activity on it has zero float, so delaying any one of them delays the whole project."},{"label":"d","prompt":"Find the float time, in days, for activity C.","marks":1,"expected_answer":"3 days","explanation":"C can start as early as day 3. Working backwards, H must start by day 13 and F by day 10, so C must finish by day 10 and can start as late as day 6. The float is 6 − 3 = 3 days."}]'::jsonb, null),
('fa71cae9-e8b7-410a-8504-2af88be26fe4', 'reading_comprehension', 'grade_4', 'foundation', 'multiple_choice', 'Why could Mia hear the sea from her bedroom?', '["The window had been left open","Her house was very close to the beach","The storm was unusually strong","The shed roof had blown away"]'::jsonb, 2, 'The text says hearing the sea from her bedroom "only happened before the worst storms", so it is a sign of how strong this storm was.', 'AC9E4LY05', '10759824-b2a1-43d2-a7be-36fc03b3fa92', null, true, null, null, null, null),
('b9d9638a-e448-48b2-8d0d-273f1b02480c', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'What causes the young shearwaters to land in the town?', '["They are confused by the lights of the town","They are blown there by the wind","They are looking for food","They are too tired to reach the island"]'::jsonb, 0, 'The text says the young birds "became confused by the lights of the town and landed on roads and footpaths".', 'AC9E4LY05', '10759824-b2a1-43d2-a7be-36fc03b3fa92', null, true, null, null, null, null),
('5f357fa9-56b0-4dba-bf7c-4f42f1342eff', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'Why does Mia’s grandmother tell her to get her boots?', '["The floor of the house is wet","She wants Mia to go to bed","They are walking to the bakery for bread","They are going outside into the storm"]'::jsonb, 3, 'The grandmother arrives with a torch and a blanket and says the birds will come down tonight, so the boots are for going out into the rain to help them.', 'AC9E4LY05', '10759824-b2a1-43d2-a7be-36fc03b3fa92', null, true, null, null, null, null),
('246e5478-8b9a-48bc-915f-741d2d85adce', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'How does Mia carry the bird safely?', '["She wraps it in the blanket","She folds its wings gently against its body","She puts it inside her coat","She carries it in the torch box"]'::jsonb, 1, 'The text says she "folded its wings gently against its body the way her grandmother had shown her".', 'AC9E4LY05', '10759824-b2a1-43d2-a7be-36fc03b3fa92', null, true, null, null, null, null),
('065056f5-3626-4059-bced-d11df6583c1c', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'In the sentence "the rain came sideways", what does the word sideways tell the reader?', '["The rain was falling very lightly","The wind was blowing very strongly","The rain had almost stopped","The rain was warm"]'::jsonb, 1, 'Rain only falls sideways when it is being driven by strong wind, so the word tells the reader how fierce the storm was without saying so directly.', 'AC9E4LY05', '10759824-b2a1-43d2-a7be-36fc03b3fa92', null, true, null, null, null, null),
('ae96b403-0c95-4fa6-a36d-d9658a8dc13a', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'Which word best describes Mia’s grandmother?', '["Nervous","Impatient","Forgetful","Experienced"]'::jsonb, 3, 'She knows the birds will come down, knows what to bring, and has already taught Mia how to hold a bird, all of which show she has done this many times before.', 'AC9E4LY05', '10759824-b2a1-43d2-a7be-36fc03b3fa92', null, true, null, null, null, null),
('4f76a405-4a56-4ff7-9d4b-8620932efdcf', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', '"Mia’s arms ached and her boots were full of water, and she had never felt prouder." What does this sentence suggest about Mia?', '["She felt the hard work had been worth it","She wished she had stayed at home","She thought the work had been too hard","She was hoping for a reward"]'::jsonb, 0, 'The sentence places the discomfort and the pride side by side, which shows that the effort was part of why she felt proud rather than a reason to regret it.', 'AC9E4LY05', '10759824-b2a1-43d2-a7be-36fc03b3fa92', null, true, null, null, null, null),
('e3641a9d-d7fa-46a1-9420-257e4bf34207', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'What is the main purpose of this text?', '["To explain how shearwaters build their nests","To warn readers about dangerous storms","To tell a story about a girl helping wildlife","To describe life on an island"]'::jsonb, 2, 'The text follows one character through one night and focuses on what she does and how she feels, which makes it a narrative rather than an information report.', 'AC9E4LY05', '10759824-b2a1-43d2-a7be-36fc03b3fa92', null, true, null, null, null, null),
('afd0029f-0724-41c9-abf3-258609c758e4', 'reading_comprehension', 'grade_4', 'foundation', 'multiple_choice', 'How deep can an ant nest reach?', '["Two centimetres","Twenty metres","Half a metre","Two metres"]'::jsonb, 3, 'The first sentence says a colony "can build a nest that reaches two metres underground".', 'AC9E4LY05', 'f69ff874-4b06-4905-a631-3eeb1b74d803', null, true, null, null, null, null),
('19263f1a-52a9-4693-9610-7742912ba868', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'According to the text, who decides how the nest will be built?', '["The queen ant","No ant is in charge","The oldest worker","The ants vote on a plan"]'::jsonb, 1, 'The text says directly that "no ant is in charge" and that each worker simply follows simple rules.', 'AC9E4LY05', 'f69ff874-4b06-4905-a631-3eeb1b74d803', null, true, null, null, null, null),
('03a5a774-7ada-4a9c-be30-cede27ac6885', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'How do the tunnels form?', '["Ants dig them out in straight lines","Rain washes them out of the ground","They are the spaces left between piles of dropped soil","Larger animals make them first"]'::jsonb, 2, 'The text explains that piles of dropped soil become walls, and "the spaces between them become tunnels".', 'AC9E4LY05', 'f69ff874-4b06-4905-a631-3eeb1b74d803', null, true, null, null, null, null),
('a858f8f2-d600-423c-b46f-3d640853ac4f', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'Why does air flowing through the widest tunnels matter?', '["It keeps the deepest chambers cool","It helps the ants find their way","It carries food into the nest","It dries out the walls"]'::jsonb, 0, 'The text says air flows through the widest tunnels, "which keeps the deepest chambers cool even on hot days".', 'AC9E4LY05', 'f69ff874-4b06-4905-a631-3eeb1b74d803', null, true, null, null, null, null),
('e349cad3-f3ec-4dd9-86ca-f49b641e002b', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'What do the outer tunnels do when it rains?', '["They carry the rain away from the nursery","They fill up and are abandoned","They collect water for the colony to drink","They close over to keep the rain out"]'::jsonb, 0, 'The text says rain "runs down the outer tunnels and away from the nursery, where the eggs are kept".', 'AC9E4LY05', 'f69ff874-4b06-4905-a631-3eeb1b74d803', null, true, null, null, null, null),
('cf0e3500-5b4f-438d-bc77-d1650358d276', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'Why does the writer mention engineers?', '["To explain how buildings are made","To suggest that ants are becoming a problem","To show that people have learned from ant nests","To compare engineers with scientists"]'::jsonb, 2, 'The engineers are introduced as an example of humans copying the ants’ design, which supports the writer’s point that ants are great builders.', 'AC9E4LY05', 'f69ff874-4b06-4905-a631-3eeb1b74d803', null, true, null, null, null, null),
('0efafcb0-b175-4077-8313-93d1150b80cb', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'The word "chambers" in this text means', '["the ants that dig","rooms or spaces inside the nest","small piles of soil","the entrances to the nest"]'::jsonb, 1, 'The text describes the deepest chambers being kept cool, which shows they are spaces inside the nest rather than ants or soil.', 'AC9E4LY05', 'f69ff874-4b06-4905-a631-3eeb1b74d803', null, true, null, null, null, null),
('c36d4941-65e5-410e-8b69-b61e432f3c2d', 'reading_comprehension', 'grade_4', 'advanced', 'multiple_choice', 'Why does the writer end with "A creature with a brain the size of a full stop has taught us something about keeping cool"?', '["To explain how small an ant’s brain is","To suggest that ants are cleverer than people","To warn the reader not to disturb ant nests","To emphasise how surprising it is that something so small can teach us"]'::jsonb, 3, 'By setting the tiny brain against the useful lesson, the writer makes the contrast the reader is meant to notice, which is the point of the whole article.', 'AC9E4LY05', 'f69ff874-4b06-4905-a631-3eeb1b74d803', null, true, null, null, null, null),
('ce0af821-8ac9-43f4-928d-caad87483491', 'reading_comprehension', 'grade_4', 'foundation', 'multiple_choice', 'What are the small stones for?', '["To soak up the water","To measure the rain","To stop the bottle blowing over","To hold the funnel in place"]'::jsonb, 2, 'Step 2 says the stones "stop the bottle blowing over in the wind".', 'AC9E4LY05', 'eadfa9b1-873c-47a4-9750-2b5858392d75', null, true, null, null, null, null),
('3317ab9c-24d8-40a6-a4bc-12ceca849892', 'reading_comprehension', 'grade_4', 'foundation', 'multiple_choice', 'Which step needs an adult’s help?', '["Cutting the top off the bottle","Putting in the stones","Marking the centimetres","Emptying the gauge"]'::jsonb, 0, 'Step 1 says to ask an adult to cut the top third off the bottle, because scissors are being used on hard plastic.', 'AC9E4LY05', 'eadfa9b1-873c-47a4-9750-2b5858392d75', null, true, null, null, null, null),
('a0fcd278-7dad-4cf8-82c1-0438f01c9e19', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'What does the cut-off top of the bottle become?', '["A lid","A handle","A measuring cup","A funnel"]'::jsonb, 3, 'Step 3 says to turn it upside down and push it in "so that it makes a funnel".', 'AC9E4LY05', 'eadfa9b1-873c-47a4-9750-2b5858392d75', null, true, null, null, null, null),
('76772e4a-72a8-4df2-96da-4fb7b9ed0fbd', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'What should you do straight after pouring in the water?', '["Put the gauge outside","Mark the line and write zero beside it","Add more stones","Measure the water with the ruler"]'::jsonb, 1, 'Step 4 says to pour in water until it just covers the stones, then "Mark this line and write zero beside it".', 'AC9E4LY05', 'eadfa9b1-873c-47a4-9750-2b5858392d75', null, true, null, null, null, null),
('1ffbbb01-8ef0-4d77-8acc-df5e217d3ed0', 'reading_comprehension', 'grade_4', 'advanced', 'multiple_choice', 'Why should the rain gauge be placed away from trees and walls?', '["So it does not get knocked over","So trees and walls do not block the rain","So it is easier to find","So the water stays cool"]'::jsonb, 1, 'The text gives the instruction but not the reason, so the reader has to work it out: anything overhead or beside the gauge would stop some rain reaching it and give a low reading.', 'AC9E4LY05', 'eadfa9b1-873c-47a4-9750-2b5858392d75', null, true, null, null, null, null),
('540f8ead-cde1-4ad8-a87c-a338336cafa8', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'How often should the gauge be checked?', '["Once a week","Whenever it rains","Once a month","At the same time each day"]'::jsonb, 3, 'The text says to "Check it at the same time each day", which makes each measurement cover the same length of time.', 'AC9E4LY05', 'eadfa9b1-873c-47a4-9750-2b5858392d75', null, true, null, null, null, null),
('03d9935e-7fd8-4d6a-a734-cdbc9f9ffa51', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'What should you do after writing down the measurement?', '["Empty it","Add fresh water","Move the gauge","Mark a new zero line"]'::jsonb, 0, 'The text says to check it, "write down the measurement, and then empty it", so that the next day’s reading starts from zero.', 'AC9E4LY05', 'eadfa9b1-873c-47a4-9750-2b5858392d75', null, true, null, null, null, null),
('beaf9d73-8f52-4379-9aca-9218cdbc24bb', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'What is the purpose of this text?', '["To explain why rain falls","To describe the weather in one place","To explain how to make and use a rain gauge","To persuade readers to study weather"]'::jsonb, 2, 'The text lists materials and then gives numbered steps, which is the structure of a procedure.', 'AC9E4LY05', 'eadfa9b1-873c-47a4-9750-2b5858392d75', null, true, null, null, null, null),
('17124d95-593b-4c3b-913f-8668908ede4a', 'reading_comprehension', 'grade_4', 'foundation', 'multiple_choice', 'What is the extra rule of a buddy bench?', '["Only new students may sit on it","You may only sit on it at lunchtime","You must ask a teacher before sitting on it","Sitting on it means you would like someone to play with"]'::jsonb, 3, 'The text explains that the bench is ordinary apart from one rule: sitting on it is a way of saying you would like someone to play with.', 'AC9E4LY05', '1d97bbcc-98e8-4b2a-bd0c-b4ddb02a1d9d', null, true, null, null, null, null),
('1bf43cad-5d71-4ec2-88a6-8c66cc9a4d36', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'What did teachers at Kingsley Primary notice?', '["Students were playing more games","Fewer students were spending lunchtime alone","The bench was rarely used","Students were arguing less"]'::jsonb, 1, 'The text says teachers noticed "far fewer students were spending lunchtime alone after the bench was put in".', 'AC9E4LY05', '1d97bbcc-98e8-4b2a-bd0c-b4ddb02a1d9d', null, true, null, null, null, null),
('a10b8536-1b1d-4207-9139-d369d3391282', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'Why does the writer include what a Kingsley student said?', '["To fill space in the article","To show that the bench was expensive","To support the argument with a real experience","To explain the rules of the bench"]'::jsonb, 2, 'Quoting someone who actually used the bench gives the writer’s argument evidence from a real school rather than only the writer’s own opinion.', 'AC9E4LY05', '1d97bbcc-98e8-4b2a-bd0c-b4ddb02a1d9d', null, true, null, null, null, null),
('941bb6d9-5fc1-492e-97fb-126295bf8d61', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'Which argument does the writer disagree with?', '["That students should simply be braver","That benches are too expensive","That lunchtime should be longer","That teachers should organise games"]'::jsonb, 0, 'The writer raises this view with "Some people say", then answers it, which shows it is the opposing argument.', 'AC9E4LY05', '1d97bbcc-98e8-4b2a-bd0c-b4ddb02a1d9d', null, true, null, null, null, null),
('11018fdd-f7be-4a04-9703-f31719ea98b5', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'How does the writer answer that argument?', '["By saying asking to join a game is hard, especially for new students","By saying that bravery does not matter","By saying teachers should decide instead","By saying the bench will make students braver"]'::jsonb, 0, 'The writer accepts that bravery is involved but argues the task is genuinely difficult, particularly for someone new to the school.', 'AC9E4LY05', '1d97bbcc-98e8-4b2a-bd0c-b4ddb02a1d9d', null, true, null, null, null, null),
('cedd708f-46ea-4d43-910c-bbcd4d90fc35', 'reading_comprehension', 'grade_4', 'advanced', 'multiple_choice', '"A bench does not ask you to be brave." What does the writer mean?', '["The bench is not frightening to sit on","The bench will make students braver over time","Sitting on the bench lets you ask for company without speaking","Brave students do not need the bench"]'::jsonb, 2, 'The following sentence explains it: the bench "gives you a way to say something without having to find the words".', 'AC9E4LY05', '1d97bbcc-98e8-4b2a-bd0c-b4ddb02a1d9d', null, true, null, null, null, null),
('b65c662a-ce37-423d-9fe6-dbb9e230f373', 'reading_comprehension', 'grade_4', 'proficient', 'multiple_choice', 'What is the writer’s main purpose?', '["To describe what happens at lunchtime","To persuade the reader that the school should get a buddy bench","To explain how benches are built","To compare two schools"]'::jsonb, 1, 'The text states a problem, proposes a solution, answers an objection and ends with a call to act, which is the structure of a persuasive text.', 'AC9E4LY05', '1d97bbcc-98e8-4b2a-bd0c-b4ddb02a1d9d', null, true, null, null, null, null),
('6672ff9a-37ff-40df-a322-6a289722cd54', 'reading_comprehension', 'grade_4', 'advanced', 'multiple_choice', '"A bench costs very little. Loneliness at lunchtime costs a great deal more." Why does the writer finish with these two sentences?', '["To explain how much a bench costs","To suggest the school cannot afford a bench","To show that loneliness cannot be measured","To contrast a small cost with a much larger problem"]'::jsonb, 3, 'The two short sentences use the same word, costs, in two different ways so that the reader weighs the price of a bench against the price of doing nothing.', 'AC9E4LY05', '1d97bbcc-98e8-4b2a-bd0c-b4ddb02a1d9d', null, true, null, null, null, null),
('efd54365-f0e5-4aa8-9c2a-36262f565e7a', 'reading_comprehension', 'grade_6', 'foundation', 'multiple_choice', 'How long had Tomas worked at the lighthouse?', '["Eleven years","Twenty-one years","Forty-one years","Ninety-eight years"]'::jsonb, 2, 'The opening sentence says "For forty-one years, Tomas had climbed the ninety-eight steps".', 'AC9E6LY05', '9eccc254-1731-43cd-a597-a5b05ae79131', null, true, null, null, null, null),
('68020ff6-48b7-4432-bb3e-a23c08b98ba5', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'What does the detail about knowing which step creaked suggest?', '["The routine had become deeply familiar through long repetition","The lighthouse was badly built","Tomas was afraid of the stairs","The steps needed repairing"]'::jsonb, 0, 'Knowing individual steps by their sound and wear is the kind of knowledge that only comes from doing something thousands of times, which is the writer’s way of showing the length of his service.', 'AC9E6LY05', '9eccc254-1731-43cd-a597-a5b05ae79131', null, true, null, null, null, null),
('a3fcfaff-9053-4b9e-a408-f8b8d734032a', 'reading_comprehension', 'grade_6', 'advanced', 'multiple_choice', '"He understood the arithmetic of it." What does this mean?', '["He had studied mathematics","He had counted the steps himself","He disagreed with the numbers in the letter","He accepted that the decision made financial sense"]'::jsonb, 3, 'Arithmetic here stands for the cost calculation behind automation: a machine is cheaper than a keeper, and Tomas can see why the department decided as it did.', 'AC9E6LY05', '9eccc254-1731-43cd-a597-a5b05ae79131', null, true, null, null, null, null),
('acb3e29c-2deb-4c15-b839-a94ab4c8f6f8', 'reading_comprehension', 'grade_6', 'advanced', 'multiple_choice', 'Why does the writer mention that the man from the department "stayed exactly eleven minutes"?', '["To show he was in a hurry to catch a train","To suggest the decision was impersonal and he had little interest in Tomas","To show how short the meeting was meant to be","To explain that he was rude to Tomas"]'::jsonb, 1, 'The precision of "exactly eleven minutes" makes the visit sound measured out in advance, which contrasts sharply with the forty-one years being ended by it.', 'AC9E6LY05', '9eccc254-1731-43cd-a597-a5b05ae79131', null, true, null, null, null, null),
('91c278a0-7a07-499a-90ff-b6d9409d0326', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'What does the writer mean by "the lamp was not the only thing he had been keeping"?', '["He had taken things from the lighthouse","He had also kept records and watched over the fishing boats","He had kept the cottage tidy","He had kept the letter a secret"]'::jsonb, 1, 'The paragraphs that follow list the other things he kept: the record book, the three-in-the-morning watch, and twice a man’s life.', 'AC9E6LY05', '9eccc254-1731-43cd-a597-a5b05ae79131', null, true, null, null, null, null),
('58307537-779b-4cb9-96bf-5ce9870e1c9f', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'What had Tomas done twice?', '["Repaired the lamp himself","Written to the department","Refused to climb the steps","Noticed a light moving wrongly and saved a man’s life"]'::jsonb, 3, 'The text says "Twice he had kept a man alive by noticing... that a light on the water was not moving the way a light on the water should".', 'AC9E6LY05', '9eccc254-1731-43cd-a597-a5b05ae79131', null, true, null, null, null, null),
('5d1d8e24-a8b1-49a3-b8e3-1b35809f8016', 'reading_comprehension', 'grade_6', 'advanced', 'multiple_choice', 'Why does Tomas light the lamp on his last evening even though the machine would do it?', '["The act matters to him personally, as a way of saying goodbye","He does not trust the new machine","He has not been told the machine is working","He wants to prove the machine is unnecessary"]'::jsonb, 0, 'The text notes the machine "would have done it for him", so lighting it is not needed; he does it because it is his last chance to do the thing he has done for forty-one years.', 'AC9E6LY05', '9eccc254-1731-43cd-a597-a5b05ae79131', null, true, null, null, null, null),
('f260820a-0428-40e3-bf1b-9c3aba914eb5', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'Which word best describes the mood of this text?', '["Angry","Frightening","Wistful","Cheerful"]'::jsonb, 2, 'The text is quiet and looks back on something valuable that is ending, without bitterness or protest, which is what wistful describes.', 'AC9E6LY05', '9eccc254-1731-43cd-a597-a5b05ae79131', null, true, null, null, null, null),
('01e1c30d-8010-4f7d-b0b3-27bf39eb422b', 'reading_comprehension', 'grade_6', 'foundation', 'multiple_choice', 'How many fatal shark incidents occur worldwide each year?', '["About five hundred","About a hundred","Hundreds of thousands","Fewer than ten"]'::jsonb, 3, 'The text states that "sharks are involved in fewer than ten fatal incidents a year" worldwide.', 'AC9E6LY05', '681b853c-9ef9-40f9-afce-dde37a305b90', null, true, null, null, null, null),
('5c168a21-34bf-42fb-9e76-c0eacc56a3ae', 'reading_comprehension', 'grade_6', 'foundation', 'multiple_choice', 'Which animal does the text say kills around five hundred people a year?', '["The mosquito","The hippopotamus","The shark","The crocodile"]'::jsonb, 1, 'The text says "Hippopotamuses kill around five hundred people", far more than sharks.', 'AC9E6LY05', '681b853c-9ef9-40f9-afce-dde37a305b90', null, true, null, null, null, null),
('07fa7e13-a7db-4a76-bb00-f5bf68b5c761', 'reading_comprehension', 'grade_6', 'advanced', 'multiple_choice', '"our sense of risk is built for stories, not for statistics" — what does the writer mean?', '["People prefer reading fiction to reading numbers","Statistics about sharks are unreliable","We judge danger by how easily we can picture it rather than by the numbers","Stories about sharks are usually untrue"]'::jsonb, 2, 'The writer explains it in the next sentences: a dramatic, well-reported event is easy to bring to mind, and "When something is easy to bring to mind, we assume it must be common".', 'AC9E6LY05', '681b853c-9ef9-40f9-afce-dde37a305b90', null, true, null, null, null, null),
('a26bb29d-d55d-471f-a92d-fb1023e985ea', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'Why does the writer mention coconuts, vending machines and bathtubs?', '["To show how small the risk from sharks is by comparison","To list other dangers people should worry about","To suggest that homes are dangerous places","To make the article more amusing"]'::jsonb, 0, 'Setting sharks against three harmless-sounding everyday objects makes the true size of the risk clear more forcefully than a number alone would.', 'AC9E6LY05', '681b853c-9ef9-40f9-afce-dde37a305b90', null, true, null, null, null, null),
('db4070e4-c330-4ea1-b571-c3469e3f0af4', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'What proportion of shark species are threatened with extinction?', '["About a third","About a tenth","About a half","Nearly all of them"]'::jsonb, 0, 'The text says "roughly a third of shark species are now threatened with extinction".', 'AC9E6LY05', '681b853c-9ef9-40f9-afce-dde37a305b90', null, true, null, null, null, null),
('c9d557b1-0b85-40f5-afd8-b2cb66880368', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'Why do shark populations recover slowly?', '["They are hunted all year round","They live in very cold water","They mature slowly and produce few young","They have few places left to live"]'::jsonb, 2, 'The text gives this as the reason: "Sharks mature slowly and produce few young, so their populations recover slowly or not at all".', 'AC9E6LY05', '681b853c-9ef9-40f9-afce-dde37a305b90', null, true, null, null, null, null),
('2288589e-43d7-492d-bd72-d30f9184a858', 'reading_comprehension', 'grade_6', 'advanced', 'multiple_choice', '"The shark, it turns out, has far more to fear from us." Why does the writer end with this sentence?', '["To warn readers to stay out of the sea","To reverse the idea the article began with","To explain how sharks hunt","To suggest sharks are becoming more dangerous"]'::jsonb, 1, 'The article opens with people fearing sharks and closes by turning that around, which sums up the writer’s argument in a single line.', 'AC9E6LY05', '681b853c-9ef9-40f9-afce-dde37a305b90', null, true, null, null, null, null),
('450a13f5-b9a3-493e-abe1-2b1ed5b31f94', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'What is the writer’s main purpose?', '["To describe how sharks hunt","To persuade readers to swim less often","To compare sharks with hippopotamuses","To correct a common misunderstanding about sharks"]'::jsonb, 3, 'The whole text sets a widespread belief against evidence and explains why the belief persists, which is the shape of a corrective argument.', 'AC9E6LY05', '681b853c-9ef9-40f9-afce-dde37a305b90', null, true, null, null, null, null),
('7730a8e3-27d0-440a-bf7a-b84546d99f9e', 'reading_comprehension', 'grade_6', 'foundation', 'multiple_choice', 'According to the writer, what do some students do by chapter four?', '["They read ahead of the class","They choose a different book","They stop reading and rely on class discussion","They ask the teacher for help"]'::jsonb, 2, 'The text says some students "quietly stop reading by chapter four and rely on class discussion to fill the gaps".', 'AC9E6LY05', '195be416-c28e-479b-aab3-7e472fa44712', null, true, null, null, null, null),
('2f23a3aa-a6cd-4998-b481-f5907ef80c8a', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'What does the writer admit is true about set texts?', '["They teach students to read closely","They are always too difficult","They are chosen by students","They are cheaper for schools"]'::jsonb, 0, 'The writer concedes this directly: "We are told that set texts teach us to read closely, and that is true."', 'AC9E6LY05', '195be416-c28e-479b-aab3-7e472fa44712', null, true, null, null, null, null),
('f5c23b53-e59c-4d53-a711-c5e9d4b9f066', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'What is the writer actually proposing?', '["That novels should be removed from school","That students should read only easy books","That class discussion should be banned","That teachers should offer several demanding novels and let students choose"]'::jsonb, 3, 'The writer proposes offering "four novels instead of one, all demanding, all worth studying", with each student choosing.', 'AC9E6LY05', '195be416-c28e-479b-aab3-7e472fa44712', null, true, null, null, null, null),
('79183cd5-8703-4447-bc27-9caef985584e', 'reading_comprehension', 'grade_6', 'advanced', 'multiple_choice', 'Why does the writer say the skills being taught do not depend on everybody holding the same book?', '["Because the skills are never tested","Because those skills can be practised on any demanding novel","Because students already have those skills","Because teachers do not check them"]'::jsonb, 1, 'The listed skills are general reading skills, so they can be developed using any sufficiently challenging text rather than one particular title.', 'AC9E6LY05', '195be416-c28e-479b-aab3-7e472fa44712', null, true, null, null, null, null),
('c9616f20-fa8d-4975-a808-15684934dd78', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'What do schools that have tried this report?', '["Students read fewer books overall","Students are more likely to finish and to read another book afterwards","Essay marks improve immediately","Teachers find it harder to plan lessons"]'::jsonb, 1, 'The text says students who choose "are more likely to finish it, and more likely to read another one afterwards without being asked".', 'AC9E6LY05', '195be416-c28e-479b-aab3-7e472fa44712', null, true, null, null, null, null),
('aa3b128c-a889-4777-a8c6-aaf188087e39', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'Which does the writer say matters more than an essay mark?', '["Finishing the set novel","Choosing a difficult book","Taking part in class discussion","Reading another book without being asked"]'::jsonb, 3, 'The writer says of that finding, "That second part matters more than any essay mark."', 'AC9E6LY05', '195be416-c28e-479b-aab3-7e472fa44712', null, true, null, null, null, null),
('6e600f74-cc35-44eb-ba22-c0825551f01e', 'reading_comprehension', 'grade_6', 'advanced', 'multiple_choice', '"The point of studying literature is not to survive one novel in Year 6." What does the word survive suggest?', '["That the novel is endured rather than enjoyed","That the novel is dangerous","That the novel is very long","That most students fail"]'::jsonb, 0, 'Survive is a word used about hardship, so choosing it for reading a novel implies the experience is something to be got through rather than valued.', 'AC9E6LY05', '195be416-c28e-479b-aab3-7e472fa44712', null, true, null, null, null, null),
('4b5df43d-3724-4454-8f37-6d3eef48eac0', 'reading_comprehension', 'grade_6', 'advanced', 'multiple_choice', 'Why does the writer end with "you may find we choose harder books than you expect"?', '["To admit the plan might fail","To ask teachers for a longer reading list","To answer the worry that students would choose easy books","To show that students dislike reading"]'::jsonb, 2, 'The most obvious objection to letting students choose is that they will take the easy option, and the closing line meets that objection head on.', 'AC9E6LY05', '195be416-c28e-479b-aab3-7e472fa44712', null, true, null, null, null, null),
('78dae00b-f9bd-4098-bbfa-69e4254455dd', 'reading_comprehension', 'grade_6', 'foundation', 'multiple_choice', 'How did the water first enter the house?', '["Through an open door","Through a broken window","Down from the roof","Up through the floor"]'::jsonb, 3, 'The opening line says "The water came up through the floor first, which nobody expected."', 'AC9E6LY05', '110459fc-229e-4ca1-9724-f5fc18c35c3e', null, true, null, null, null, null),
('0229c091-fce2-4dd5-a0e6-425e2253d68e', 'reading_comprehension', 'grade_6', 'advanced', 'multiple_choice', 'What does "The river had its own timetable" mean?', '["The river rose at the same time every year","The river did not follow the predictions people had made","The council published a timetable","The flood happened exactly on schedule"]'::jsonb, 1, 'Both Dad and the council said "until evening", and the water arrived at two o’clock, so the sentence points out that the river ignored everybody’s predictions.', 'AC9E6LY05', '110459fc-229e-4ca1-9724-f5fc18c35c3e', null, true, null, null, null, null),
('265111fd-8a91-4097-bcf8-ead6a0b36307', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'What first told the family that the water had arrived?', '["A warning on the radio","The dog began barking","The hallway carpet had gone dark","A neighbour knocked on the door"]'::jsonb, 2, 'The text says the brother "noticed that the carpet in the hallway had gone dark", which was the water soaking up through it.', 'AC9E6LY05', '110459fc-229e-4ca1-9724-f5fc18c35c3e', null, true, null, null, null, null),
('867673cc-07a3-4727-91e3-ae950265f7c0', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'What surprised the narrator during the flood?', '["How ordinary and calm it felt","How quickly the water rose","How much was lost","How loud everything was"]'::jsonb, 0, 'The narrator says directly, "What surprised me was how ordinary it felt while it was happening. Nobody shouted."', 'AC9E6LY05', '110459fc-229e-4ca1-9724-f5fc18c35c3e', null, true, null, null, null, null),
('d0f17427-06dd-45e7-a9ad-d9489c68aeb8', 'reading_comprehension', 'grade_6', 'advanced', 'multiple_choice', 'Why does the writer repeat "upstairs, leave it, upstairs, leave it"?', '["To show how fast and automatic the decisions were","To show the family could not agree","To list everything that was saved","To show that the family was panicking"]'::jsonb, 0, 'The clipped repetition imitates the rhythm of decisions made in "about two seconds each", letting the reader feel the speed rather than being told about it.', 'AC9E6LY05', '110459fc-229e-4ca1-9724-f5fc18c35c3e', null, true, null, null, null, null),
('79463c2b-9c7e-4a42-9f11-5536d1d5c3c7', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'What did the water leave behind?', '["A layer of sand","Broken windows","Eleven centimetres of silt and a smell","Nothing at all"]'::jsonb, 2, 'The text says the water "left eleven centimetres of silt on everything, and a smell I still cannot describe".', 'AC9E6LY05', '110459fc-229e-4ca1-9724-f5fc18c35c3e', null, true, null, null, null, null),
('4ea37fa2-754a-45a8-92a1-4add6902bf98', 'reading_comprehension', 'grade_6', 'proficient', 'multiple_choice', 'Why does the writer mention the man from two streets over?', '["To explain who caused the flood","To show the kindness of strangers afterwards","To suggest the family needed to pay him","To show that the street was crowded"]'::jsonb, 1, 'The man is a stranger who worked for six hours and left before he could be thanked, which is the writer’s clearest example of unasked-for kindness.', 'AC9E6LY05', '110459fc-229e-4ca1-9724-f5fc18c35c3e', null, true, null, null, null, null),
('041a1700-3a38-4083-840d-381b012a7030', 'reading_comprehension', 'grade_6', 'advanced', 'multiple_choice', '"But that is not the part I think about." What does this suggest the writer remembers most?', '["The fear during the flood","The loss of the kitchen","The warnings that were wrong","The help given by neighbours and strangers"]'::jsonb, 3, 'The paragraph before this line is entirely about neighbours arriving with shovels and a stranger cleaning the kitchen, so that is what the closing sentence points back to.', 'AC9E6LY05', '110459fc-229e-4ca1-9724-f5fc18c35c3e', null, true, null, null, null, null),
('ed5fd2ab-0f14-452b-b435-c280acb8a639', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'What does the writer mean by "she had learned every line of a part she would never play"?', '["Priya had been given the wrong script","Priya was not allowed to rehearse","Priya had prepared completely for something she expected never to perform","Priya had forgotten her own part"]'::jsonb, 2, 'The sentence sets total preparation against no expectation of performing, which establishes both her diligence and the apparent pointlessness of it.', 'AC9E8LY05', 'fff60ac6-1825-4f91-9604-7414da933061', null, true, null, null, null, null),
('07d17709-79ce-497c-a2c1-f6cdc359513c', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'Why had Priya told nobody about the four-beat pause?', '["Understudies who give notes to the lead lose their position","She was not certain she was right","She wanted to use it herself one day","The director had told her to stay silent"]'::jsonb, 0, 'The text explains the unwritten rule: such understudies "do not remain understudies for long; they simply stop being invited".', 'AC9E8LY05', 'fff60ac6-1825-4f91-9604-7414da933061', null, true, null, null, null, null),
('14ed5123-6a4a-4efe-94bc-083dbbf94404', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', 'How is Aisha’s injury deliberately described?', '["As a dramatic, shocking accident","As an injury nobody noticed","As something Aisha had faked","As something undramatic — a wrong step and a small sound"]'::jsonb, 3, 'The writer explicitly rules out drama — "not dramatically, not with a scream" — so that the moment which changes everything is almost unnoticeable.', 'AC9E8LY05', 'fff60ac6-1825-4f91-9604-7414da933061', null, true, null, null, null, null),
('6a5ddab5-42c4-4d48-b0c0-492e54bda07d', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', 'Why does the director ask about the pause rather than whether Priya is ready?', '["He has forgotten her name","He is testing whether she genuinely knows the part","He is trying to delay the decision","He wants her to refuse the role"]'::jsonb, 1, 'A single specific question about an interpretive choice reveals far more than a yes-or-no about readiness, and her instant, exact answer passes the test.', 'AC9E8LY05', 'fff60ac6-1825-4f91-9604-7414da933061', null, true, null, null, null, null),
('59772f7b-663d-4dba-8d05-eec9cc6d0762', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', '"It was not a question, so she did not answer it." What does this reveal about Priya?', '["She was too nervous to speak","She is precise and self-controlled","She had not heard the director","She was angry with the director"]'::jsonb, 1, 'Noticing that "And you said nothing" is a statement rather than a question, and declining to fill the silence, shows the same exactness she brings to the four-beat pause.', 'AC9E8LY05', 'fff60ac6-1825-4f91-9604-7414da933061', null, true, null, null, null, null),
('0ba26389-90c3-4270-a4e8-9e03c83c6c8b', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'What does Priya understand from the director’s reaction?', '["That he does not want her in the role","That Aisha will return the next night","That the pause should be two beats after all","That she has been given the part and criticised at the same time"]'::jsonb, 3, 'The text says she understood "she had just been given the part and criticised in the same breath, and that both were fair".', 'AC9E8LY05', 'fff60ac6-1825-4f91-9604-7414da933061', null, true, null, null, null, null),
('9917990e-5db6-4bce-bd49-399a6de67204', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', '"she could hear four hundred people not moving" — what does this convey?', '["The audience was completely absorbed","The audience was bored","The theatre was almost empty","The audience could not see the stage"]'::jsonb, 0, 'Describing silence as something audible, and as the absence of movement from a specific number of people, conveys total attention more vividly than applause would.', 'AC9E8LY05', 'fff60ac6-1825-4f91-9604-7414da933061', null, true, null, null, null, null),
('bd66ecf9-c762-43d6-bfa9-7f1ab6aae0d5', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', 'What does Aisha’s final remark mean?', '["Priya only succeeded because Aisha was injured","Aisha intends to give up acting","Priya’s ability was always there; only its recognition has changed","Priya should thank Aisha for the opportunity"]'::jsonb, 2, 'Aisha says "You were always going to be better" and locates the change entirely in the fact that "now somebody else knows", not in Priya’s ability.', 'AC9E8LY05', 'fff60ac6-1825-4f91-9604-7414da933061', null, true, null, null, null, null),
('8c664546-67b8-4929-98c1-098f08cdeb6f', 'reading_literary_analysis', 'year_8', 'foundation', 'multiple_choice', 'What is a recommendation system’s usual target?', '["To show users accurate information","To reduce the time users spend online","To recommend only popular content","To keep the user engaged for longer"]'::jsonb, 3, 'The opening paragraph states the target directly: "keep you here longer".', 'AC9E8LY05', '90ef1ed8-8397-47d6-8606-f43f45f0bf5d', null, true, null, null, null, null),
('89ffdaac-7b6d-4d39-826c-e71fd2bf198d', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'When does the writer say the difficulty begins?', '["When users watch cooking videos","When the system finds that some material holds attention better than the rest","When engineers change the system","When too many people use the system at once"]'::jsonb, 1, 'The text marks this as the turning point: the difficulty begins "when the system discovers... that certain kinds of material hold attention better than others".', 'AC9E8LY05', '90ef1ed8-8397-47d6-8606-f43f45f0bf5d', null, true, null, null, null, null),
('d5e4faed-c0ae-43b4-a019-c19216fc1e67', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', '"in the way water drifts downhill" — what does this comparison suggest?', '["The process is slow and can be stopped easily","The system was designed to cause harm","The drift is automatic and unintended rather than deliberate","The effect only happens in certain countries"]'::jsonb, 2, 'Water does not choose to run downhill; it follows the shape it is given. The comparison makes the drift a consequence of the system’s design rather than anyone’s intention, which the writer states in the same sentence: "not out of malice".', 'AC9E8LY05', '90ef1ed8-8397-47d6-8606-f43f45f0bf5d', null, true, null, null, null, null),
('de17067f-6761-4bb2-84bf-697e0240b391', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'What is the "second effect" the writer describes?', '["The system learns from behaviour rather than stated preferences, building a model from weak moments","The system becomes slower over time","The system shows the same content to everybody","The system stops recommending accurate content"]'::jsonb, 0, 'The writer explains that because the system learns "from what you do rather than from what you say you want", repeated careless clicks become the basis of its model of you.', 'AC9E8LY05', '90ef1ed8-8397-47d6-8606-f43f45f0bf5d', null, true, null, null, null, null),
('122b3f2e-9231-4668-ae31-5d0103c2b2d9', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'How does the writer respond to blaming users for weak willpower?', '["By arguing it misunderstands how unequal the contest is","By agreeing that users should try harder","By suggesting users should be fined","By saying willpower cannot be measured"]'::jsonb, 0, 'The writer answers "This misunderstands the contest", then sets one distracted person against a system running millions of experiments a day.', 'AC9E8LY05', '90ef1ed8-8397-47d6-8606-f43f45f0bf5d', null, true, null, null, null, null),
('7f9e4139-a7dd-495e-b4e2-f15655d4357e', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', 'Why does the writer contrast "four seconds of attention" with "millions of experiments a day"?', '["To show how quickly systems improve","To explain how recommendation systems are built","To show how mismatched the user and the system are","To suggest users should spend less time online"]'::jsonb, 2, 'Placing the two figures side by side makes the imbalance concrete, which is the evidence for the claim that blaming willpower misses the point.', 'AC9E8LY05', '90ef1ed8-8397-47d6-8606-f43f45f0bf5d', null, true, null, null, null, null),
('c50b180b-115d-4848-bb03-0a5655651f34', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', 'What is the writer’s main argument in the final paragraph?', '["That engineers should be punished","That harm can arise without anyone intending it, from a slightly wrong target pursued with vast resources","That recommendation systems should be banned","That users should choose their own content"]'::jsonb, 1, 'The closing paragraph explicitly removes villainy from the explanation and lists the three conditions that are sufficient on their own.', 'AC9E8LY05', '90ef1ed8-8397-47d6-8606-f43f45f0bf5d', null, true, null, null, null, null),
('d53655f3-2062-4a78-a735-12f5ddd288ac', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'Which word best describes the tone of this text?', '["Outraged","Humorous","Uncertain","Measured"]'::jsonb, 3, 'The writer repeatedly concedes points, rules out blame, and builds the argument step by step rather than through emotive language, which is a measured tone.', 'AC9E8LY05', '90ef1ed8-8397-47d6-8606-f43f45f0bf5d', null, true, null, null, null, null),
('f405f3a7-fb9a-4b77-a2ba-08c34e3a4570', 'reading_literary_analysis', 'year_8', 'foundation', 'multiple_choice', 'What does the writer say we have nearly eliminated?', '["Reading for pleasure","Waiting in queues","Boredom from ordinary life","Original ideas"]'::jsonb, 2, 'The opening sentence states it: "We have, in about fifteen years, very nearly eliminated boredom from ordinary life."', 'AC9E8LY05', 'a2a4fb48-dc3f-47ff-8b3f-724b41c7aca6', null, true, null, null, null, null),
('37320080-5ce9-4202-b9cb-182864342961', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', 'Why does the writer say boredom being unpleasant is "precisely its function"?', '["Because the discomfort is what makes us act on it","Because unpleasant feelings are always useful","Because boredom is a kind of illness","Because people enjoy complaining"]'::jsonb, 0, 'The writer explains that boredom is "uncomfortable enough that we do something about it", so the unpleasantness is the mechanism, not a side effect.', 'AC9E8LY05', 'a2a4fb48-dc3f-47ff-8b3f-724b41c7aca6', null, true, null, null, null, null),
('c63221ab-12f0-4796-b3c8-8d171dbbeead', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'According to the writer, what do children do after a period of loud complaint?', '["Ask an adult for a screen","Fall asleep","Give up and do nothing","Build something or invent a complicated game"]'::jsonb, 3, 'The text says they "build something, or make up a game with rules of forbidding complexity".', 'AC9E8LY05', 'a2a4fb48-dc3f-47ff-8b3f-724b41c7aca6', null, true, null, null, null, null),
('ee7388c9-2eee-4962-8feb-c3bc52bbc08e', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', '"The complaint is not a failure of the process. It is the process." What does the writer mean?', '["Children should be told not to complain","The discomfort is a necessary stage rather than a sign something is wrong","Complaining prevents children from inventing","Adults should ignore children entirely"]'::jsonb, 1, 'The writer reframes the complaint as part of how invention happens, so relieving it immediately would interrupt the very thing that produces the invention.', 'AC9E8LY05', 'a2a4fb48-dc3f-47ff-8b3f-724b41c7aca6', null, true, null, null, null, null),
('438d9b7b-e912-435b-8a8c-0154fcd57197', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'What do researchers find about people asked to sit and do nothing?', '["They become irritable and unhelpful","They perform better on a later creative task","They remember less afterwards","They take longer to finish the task"]'::jsonb, 1, 'The text reports that such people "perform better than people who were kept occupied beforehand".', 'AC9E8LY05', 'a2a4fb48-dc3f-47ff-8b3f-724b41c7aca6', null, true, null, null, null, null),
('f344008b-a969-4259-8eb6-481294d67f73', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', 'What concession does the writer make?', '["That boredom is always valuable","That screens have no benefits","That the research may be wrong","That boredom is not always productive, such as in a hospital waiting room"]'::jsonb, 3, 'The writer says "I am not romanticising discomfort" and gives the waiting-room example, which narrows the claim and makes it harder to dismiss.', 'AC9E8LY05', 'a2a4fb48-dc3f-47ff-8b3f-724b41c7aca6', null, true, null, null, null, null),
('277773b0-fb00-4bed-8b66-9f33540c4ddf', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'What does the writer say actually worries them?', '["That we never find out what we would have thought instead","The hour spent scrolling","That children complain too much","That researchers disagree"]'::jsonb, 0, 'The final paragraph draws this distinction explicitly: "What worries me is not the hour spent scrolling. It is that we no longer find out what we would have thought instead."', 'AC9E8LY05', 'a2a4fb48-dc3f-47ff-8b3f-724b41c7aca6', null, true, null, null, null, null),
('f96ca34b-6e4a-48bf-a551-76f6606882d7', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', 'Why does the writer say this loss "will not appear in any argument about screen time"?', '["Because nobody is interested in the subject","Because the research is too recent","Because it cannot be measured","Because screen time is falling anyway"]'::jsonb, 2, 'The writer says it is "not a loss anybody can measure, which is exactly why it will not appear", and then argues that being unmeasurable is why it gets overlooked rather than why it is unimportant.', 'AC9E8LY05', 'a2a4fb48-dc3f-47ff-8b3f-724b41c7aca6', null, true, null, null, null, null),
('fc2649e6-d990-457c-a63c-4f1fa035b091', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', 'What does the writer mean by "true in the way that a photograph of a meal is the same as the meal"?', '["The network’s letter contained a factual error","The new service will be of much higher quality","Listeners will not notice any difference","The replacement service is technically similar but lacks what actually mattered"]'::jsonb, 3, 'A photograph accurately represents a meal while being useless as food. The comparison concedes the network’s claim is literally true and denies that it means anything.', 'AC9E8LY05', 'aa1f4cb7-c601-4cb1-949f-57b78c33b269', null, true, null, null, null, null),
('39c441fc-0214-4740-b57b-e9bc236200ac', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'How does Ellie know how many listeners have no internet connection?', '["The network provided the figure","From eleven years of taking their calls","From a survey of the listening area","The hospital gave her a list"]'::jsonb, 1, 'The text says "she had counted them, more or less, across eleven years of taking calls".', 'AC9E8LY05', 'aa1f4cb7-c601-4cb1-949f-57b78c33b269', null, true, null, null, null, null),
('741e41ed-a70c-4bac-babf-170056c71995', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', 'Why does the writer list Mrs Dettmann, the Baillie brothers and the night nurse?', '["To show that the audience was very small","To explain who complained about the closure","To make the audience concrete and personal rather than a statistic","To show that the callers knew one another"]'::jsonb, 2, 'The writer moves straight from a number, four hundred and eleven, to three specific people, which converts an abstraction into individuals the reader can care about.', 'AC9E8LY05', 'aa1f4cb7-c601-4cb1-949f-57b78c33b269', null, true, null, null, null, null),
('78f0ec10-2d83-4920-8c1f-9561c8dcca51', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'What is notable about the Baillie brothers?', '["They have not spoken since 1998 but requested the same song","They founded the radio station","They both work at the hospital","They live in Brisbane"]'::jsonb, 0, 'The text gives exactly this detail, which quietly suggests how much the two men still have in common despite the estrangement.', 'AC9E8LY05', 'aa1f4cb7-c601-4cb1-949f-57b78c33b269', null, true, null, null, null, null),
('4f606cb3-392c-4cf0-9598-304798adcbf5', 'reading_literary_analysis', 'year_8', 'proficient', 'multiple_choice', 'What does Ellie do instead of reading the network’s closing statement?', '["She speaks personally to her listeners","She plays music without speaking","She criticises the network on air","She reads out the listeners’ names"]'::jsonb, 0, 'The text says she "did not read the closing statement the network had supplied" and then gives her own words, which thank the listeners directly.', 'AC9E8LY05', 'aa1f4cb7-c601-4cb1-949f-57b78c33b269', null, true, null, null, null, null),
('2c3b0e6e-5d2f-4076-98d3-18cba7fd5323', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', '"the particular quiet of a place that has stopped transmitting" — what does this suggest?', '["The equipment had broken down","The room was soundproofed","A silence that feels final and unlike ordinary quiet","Everybody had already left the building"]'::jsonb, 2, 'The word particular insists this is a specific kind of silence, distinguishing the permanent ending of transmission from a room simply being quiet.', 'AC9E8LY05', 'aa1f4cb7-c601-4cb1-949f-57b78c33b269', null, true, null, null, null, null),
('4aba3837-aaaf-46c4-b3de-7f6bcdc69951', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', 'Why does Mrs Dettmann not hang up?', '["She is waiting for Ellie to correct herself","The call is really about connection and farewell, not pronunciation","She has fallen asleep","She wants to request a song"]'::jsonb, 1, 'The pronunciation complaint is the excuse for the call; the long silence that neither of them fills is what the call is actually for.', 'AC9E8LY05', 'aa1f4cb7-c601-4cb1-949f-57b78c33b269', null, true, null, null, null, null),
('f688e8d1-929f-45f9-ac6c-22b0eb284dff', 'reading_literary_analysis', 'year_8', 'advanced', 'multiple_choice', 'What is the main idea of this text?', '["Regional radio is technically outdated","Listeners should have protested the closure","Ellie should have accepted the network’s decision","Something valuable has been lost that a technically equivalent service cannot replace"]'::jsonb, 3, 'Every element — the photograph comparison, the named listeners, the unscripted farewell, the final call — works to show what the Brisbane broadcast will not carry.', 'AC9E8LY05', 'aa1f4cb7-c601-4cb1-949f-57b78c33b269', null, true, null, null, null, null),
('3bf97402-b76f-4344-8774-e27e61b785d0', 'grammar_punctuation', 'grade_4', 'developing', 'short_answer', 'One word in this sentence is spelt incorrectly. Write the correct spelling of that word.
We went to the libary after school.', null, null, 'The correct spelling is "library".', 'AC9E4LY10', null, null, true, 'library', null, null, null),
('44d66441-9d40-4afd-bdb9-e9667f5d3335', 'grammar_punctuation', 'grade_4', 'developing', 'short_answer', 'One word in this sentence is spelt incorrectly. Write the correct spelling of that word.
