('016a3eab-5d4a-4bda-9a88-b9d3143e48ef', 'geometry_measurement', 'grade_6', 'developing', 'multiple_choice', 'Which object has 5 faces, 8 edges and 5 corners?', '["","","",""]'::jsonb, 0, 'A square pyramid has a square base and 4 triangles (5 faces), 8 edges and 5 corners. The triangular prism also has 5 faces, but it has 9 edges and 6 corners.', 'AC9M6SP01', null, null, true, null, null, null, null),
