('feb0191a-d9e6-417e-8c48-5891674c79f5', 'geometry_measurement', 'grade_6', 'proficient', 'multiple_choice', 'In which direction is the beach from the shop?', '["north-east","north-west","south-east","south-west"]'::jsonb, 0, 'From the shop, the beach is further up (north) and further right (east), so it is north-east of the shop.', 'AC9M6SP02', null, null, true, null, null, null, null),
