('2c7945c8-d625-4cd4-90c9-8443981e621b', 'geometry_measurement', 'grade_6', 'proficient', 'multiple_choice', 'What is the size of angle t?', '["40°","60°","130°","50°"]'::jsonb, 3, 'The angles in a triangle add to 180°. t = 180 − 55 − 75 = 50°. The answer 130° is 55 + 75.', 'AC9M6M04', null, null, true, null, null, null, null),
