('e384cec8-000c-4061-9b7f-188c3cd4d268', 'number_operations', 'grade_3', 'proficient', 'multiple_choice', 'Which number rounds to 70 when it is rounded to the nearest ten?', '["64","74","76","78"]'::jsonb, 1, '74 is between 70 and 80 and closer to 70. 76 and 78 are closer to 80, and 64 rounds to 60.', 'AC9M3N01', null, null, true, null, null, null, null),
('28f1aeff-cf4c-4d84-a9a9-bae531e79a85', 'number_operations', 'grade_3', 'developing', 'multiple_choice', 'Grace has 38 marbles.
