('f50bb1f8-286d-4760-a307-4eefc3ac26eb', 'geometry_measurement', 'grade_3', 'foundation', 'multiple_choice', 'What time does the clock show?', '["3:30","6:15","6:30","3:06"]'::jsonb, 0, 'The long hand points to 6, which is 30 minutes. The short hand is halfway between 3 and 4, so the time is 3:30.', 'AC9M3M03', null, null, true, null, null, null, null),
