('f6217ff9-1aa4-4b91-aa62-ab6096e21b19', 'geometry_measurement', 'grade_3', 'proficient', 'short_answer', 'How long is the crayon?', null, null, 'The crayon starts at 1 cm and ends at 8 cm, so it is 8 − 1 = 7 cm long. Reading only the end gives 8 cm.', 'AC9M3M01', null, null, true, '7 cm', ARRAY['7']::text[], null, null),
('bdfdda5a-f1a9-4e6f-bcc1-5c193e53954c', 'geometry_measurement', 'grade_3', 'developing', 'multiple_choice', 'How much water is in the jug?', '["60 mL","600 mL","700 mL","6 L"]'::jsonb, 1, 'The water reaches the 600 mL mark, one mark above 500 mL. Each mark on this jug is 100 mL.', 'AC9M3M01', null, null, true, null, null, null, null),
('d38e1101-c82a-40e6-9098-440e168b78c2', 'geometry_measurement', 'grade_3', 'developing', 'multiple_choice', 'Ben weighs a bag of potatoes.
