('e2f70aae-d5e7-4d84-a56d-f69638185321', 'geometry_measurement', 'grade_3', 'developing', 'multiple_choice', 'Which object has 6 faces that are all squares?', '["","","",""]'::jsonb, 3, 'A cube has 6 faces and every one is a square, like object D. Object C also has 6 faces, but most of them are rectangles.', 'AC9M3SP01', null, null, true, null, null, null, null),
('6765a40d-47f0-45a6-9a8b-a446cf92c7ac', 'geometry_measurement', 'grade_3', 'proficient', 'multiple_choice', 'This net is folded along the dashed lines.
