('724cdb79-08ee-437e-ae01-715cd40c3dfc', 'geometry_measurement', 'grade_3', 'developing', 'multiple_choice', 'Which is the best estimate for the height of a classroom door?', '["2 m","2 cm","20 m","200 m"]'::jsonb, 0, 'A door is a little taller than an adult, which is about 2 metres. 2 cm is shorter than your finger, and 20 m is taller than a house.', 'AC9M3M02', null, null, true, null, null, null, null),
('7f168bde-798f-4e6f-89bd-4a21511f0f4e', 'geometry_measurement', 'grade_3', 'proficient', 'multiple_choice', 'Which jug has exactly 300 mL of water in it?', '["","","",""]'::jsonb, 2, 'Jug C has marks every 100 mL, and the water is one mark above 200 mL, which is 300 mL. Jug A has 200 mL, B has 350 mL and D has 750 mL.', 'AC9M3M01', null, null, true, null, null, null, null),
('af8d04e2-4888-414a-aa2c-37ef784d143a', 'geometry_measurement', 'grade_3', 'developing', 'multiple_choice', 'How many centimetres are there in 1 metre?', '["10","60","100","1000"]'::jsonb, 2, 'There are 100 centimetres in 1 metre. 1000 is the number of millimetres in a metre.', 'AC9M3M02', null, null, true, null, null, null, null),
('9ce048da-3b95-448c-89b4-9ff8acdde216', 'statistics_probability', 'grade_3', 'developing', 'short_answer', 'The pictograph shows how many apples the canteen sold each day.
