('fe4a5278-75f6-40fa-bf47-6bbb85fc9af0', 'number_operations', 'grade_5', 'foundation', 'multiple_choice', 'What number do these blocks show?', '["253","2053","2503","20 053"]'::jsonb, 1, 'There are 2 thousands, no hundreds, 5 tens and 3 ones, which make 2053. 253 leaves out the thousands.', 'AC9M5N01', null, null, true, null, null, null, null),
('e5576362-aff9-49bf-8f28-e7fca72c9706', 'number_operations', 'grade_5', 'developing', 'short_answer', 'The crowd at a football match was 38 562.
