('a849fda2-1bc8-4520-bb57-700f49f666fb', 'geometry_measurement', 'grade_5', 'developing', 'multiple_choice', 'What is the mass of the parcel on the scale?', '["1.07 kg","1.35 kg","1.7 kg","17 kg"]'::jsonb, 2, 'Each small mark is 0.1 kg. The needle is 2 marks past 1.5, so the parcel is 1.5 + 0.2 = 1.7 kg.', 'AC9M5M01', null, null, true, null, null, null, null),
